__MATX("endo",{"res":{"ch":[{"pts":[["","L'endocrinologie étudie la sécrétion interne, donc les hormones."],["","Une hormone est une substance chimique sécrétée par une glande endocrine, transportée par le sang, agissant à distance sur une cible."],["","Le système endocrinien coordonne 7 grandes fonctions vitales."],["","Le cours cite 9 hormones exemples."]],"tabs":[],"imgs":[]},{"pts":[["","Exocrine : sécrétion par un canal ; endocrine : sécrétion directe dans le sang."],["","Une glande amphicrine est à la fois endocrine et exocrine, exemple le pancréas."],["","Les hormones peptidiques sont de petites protéines circulant librement et agissant via des récepteurs membranaires."],["","Les stéroïdes dérivent du cholestérol, sont transportés liés à une protéine (inactifs), et agissent sur des récepteurs intracellulaires."],["","Les hormones mono-aminées dérivent de la tyrosine : catécholamines et hormones thyroïdiennes."]],"tabs":[],"imgs":[[256,"Glande thyroïde : exemple de glande endocrine"],[257,"Principaux organes endocriniens (hypophyse, thyroïde, surrénales, pancréas, gonades)"]]},{"pts":[["","Chaque hormone a une glande d'origine et une action principale sur sa cible."],["","La FSH fait mûrir le follicule et stimule la spermatogenèse ; la LH déclenche l'ovulation et stimule la testostérone."],["","Insuline (cellules β) hypoglycémiante ; glucagon (cellules α) hyperglycémiant."],["","Glomérulée → aldostérone ; fasciculée → cortisol ; réticulée → androgènes ; médullaire → adrénaline."],["","La régulation hormonale maintient l'équilibre par rétrocontrôle, par certaines substances (glycémie) et par stimulation nerveuse."]],"tabs":[],"imgs":[[258,"Tableau : glandes endocrines, hormones et actions physiologiques principales"]]},{"pts":[["","La thyroïde a deux types de cellules et fabrique T4, T3 et calcitonine à partir de tyrosine et d'iode."],["","La thyroïde est commandée par la TSH hypophysaire, elle-même stimulée par la TRH hypothalamique, avec rétrocontrôle."],["","Le pancréas amphicrine : acini séreux (99 %) exocrines et îlots de Langerhans (1 %) endocrines."],["","L'insuline est stimulée par l'élévation de la glycémie, des acides gras et des acides aminés ; le glucagon par la baisse de la glycémie."],["","La sécrétion surrénalienne est régulée par l'hypothalamus (CRF) et l'hypophyse (ACTH) ; l'aldostérone aussi par le système rénine-angiotensine."],["","L'hypothalamus, cerveau endocrinien, sécrète TRH, GnRH, CRF, ADH et ocytocine."],["","L'adénohypophyse sécrète 6 hormones ; la neurohypophyse contient ADH et ocytocine ; elle est reliée à l'hypothalamus par l'infundibulum."],["","Le système endocrinien fonctionne comme un orchestre ; tout dérèglement a un impact sérieux."]],"tabs":[],"imgs":[[259,"Anatomie de la thyroïde (cartilage thyroïde, glande, trachée, parathyroïdes)"],[260,"Histologie thyroïdienne : thyréocytes (99,9 %) et cellules C (0,1 %)"],[261,"Axe TRH → TSH → hormones thyroïdiennes et rétrocontrôle"],[262,"Le pancréas, glande amphicrine"],[263,"Surrénales : corticosurrénale (3 zones) et médullosurrénale"],[264,"Régulation : hypothalamus (CRF) → hypophyse (ACTH) → aldostérone, cortisol, androgènes"],[265,"Axe hypothalamo-hypophyso-gonadique (testicules et ovaires)"],[266,"Hypothalamus et hypophyse : neurones neurosécréteurs et système porte"],[267,"Communication de l'axe hypothalamo-hypophysaire avec la thyroïde et les testicules"],[268,"« Que retenir ? » : le système endocrinien comme un orchestre"]]},{"pts":[["","Le diabète est une MNT majeure de l'OMS, épidémie mondiale, frein au développement ; prévalence 6,2 % en Côte d'Ivoire."],["","Le diabète est une hyperglycémie permanente ; glycémie normale 0,7–1 g/l ; diabète si ≥ 1,26 g/l à 2 reprises."],["","Type 1 : déficit absolu en insuline ; type 2 : déficit relatif + défaut d'action ; type 3 : cause identifiable ; type 4 : gestationnel."],["","DT1 : auto-immun, brutal, jeune, 20 % ; DT2 : insulino-résistance, insidieux, obésité, fréquent."],["","Les signes cardinaux du diabète sont polyurie (> 4 L/24 h), polydipsie, polyphagie et amaigrissement malgré l'appétit."],["","Des situations cliniques particulières doivent faire rechercher un diabète."],["","Trois méthodes, une seule suffit : glycémie à jeun ≥ 1,26 g/l ×2, glycémie post-prandiale/aléatoire ≥ 2 g/l ×2, HbA1c ≥ 6,5 % si GAJ 1,10–1,26."],["","Les complications sont aiguës (métaboliques, infectieuses) ou chroniques (macro et microvasculaires)."],["","La stratégie de lutte repose sur la prévention du diabète, la prévention des complications et l'éducation thérapeutique."],["","Cinq sujets d'éducation thérapeutique ; objectifs : normaliser la glycémie, chercher les complications, réduire les facteurs de risque CV."],["","Le régime supprime les sucres rapides, réduit les complexes, évite les graisses animales, favorise fibres et huiles végétales."],["","L'activité physique régulière (≥ 30 min/j) potentialise le régime et protège le cœur."],["","Les antidiabétiques sont classés selon leur mode d'action ; l'insuline existe en formes rapide, lente, intermédiaire (NPH), mixte."]],"tabs":[{"t":"Fiche pathologie : Diabète de type 1","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Diabète de type 1","Syndrome polyuro-polydipsique brutal + amaigrissement","—","—","Asthénie, polyphagie, cétose, sujet < 30 ans","Glycémie à jeun ≥ 1,26 g/l ×2, bandelette (glucose, cétones)","Insuline, ETP, régime, activité physique"]],"c":null},{"t":"Fiche pathologie : Diabète de type 2","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Diabète de type 2","Découverte fortuite ou par complication","—","—","Obésité, hérédité, infections, furoncles","GAJ ≥ 1,26 g/l ×2, GPP ≥ 2 g/l, HbA1c ≥ 6,5 %","Régime, activité ≥ 30 min/j, antidiabétiques oraux, ETP"]],"c":null}],"imgs":[[269,"Tableau comparatif diabète de type 1 / type 2"],[270,"Critères diagnostiques : glycémie à jeun, post-prandiale, HbA1c"],[271,"Régime : supprimer les sucres rapides, réduire les sucres complexes, éviter graisses animales, fibres"],[272,"Réduction de la consommation d'alcool et suppression de la cigarette"]]},{"pts":[["","L'acidocétose survient surtout chez le DT1 connu, déclenchée par infection, stress, corticoïdes ou arrêt d'insuline."],["","Cétose sans acidose au début, puis dyspnée de Kussmaul, troubles de conscience, déshydratation, vomissements, douleurs abdominales, odeur cétonique, coma."],["","Hyperglycémie franche, acidose métabolique, kaliémie normale ou élevée avec déplétion potassique constante."],["","PEC : réhydratation au sérum physiologique, insulinothérapie intensive, corrections, traitement du facteur déclenchant."],["","Complications : collapsus, hypoglycémies, œdème cérébral (excès d'hypotoniques ou baisse trop rapide de la glycémie), accidents thromboemboliques."],["","Devant un diabétique connu avec forte glycosurie et cétonurie, injections supplémentaires d'insuline rapide ; le coma est pris en charge en service de référence."]],"tabs":[{"t":"Fiche pathologie : Acidocétose diabétique","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Acidocétose diabétique","Dyspnée de Kussmaul + odeur cétonique","Douleurs abdominales","—","Vomissements, déshydratation, troubles de conscience → coma","Hyperglycémie, acidose, cétonémie, kaliémie","SSI, insuline intensive, K/Na, facteur déclenchant, référence"]],"c":null}],"imgs":[]},{"pts":[["","Les malaises hypoglycémiques correspondent habituellement à une glycémie < 0,7 g/l."],["","L'hypoglycémie résulte d'un déséquilibre glucides-insuline-exercice, ou de l'alcool, des β-bloquants, des salicylés."],["","L'hypoglycémie modérée donne pâleur, tremblements, palpitations, faim intense, sueurs."],["","Avec l'ancienneté du diabète, les signes d'alerte diminuent et apparaissent diplopie, troubles de l'élocution, agressivité, attitudes bizarres."],["","L'hypoglycémie sévère nécessite une aide extérieure ; complications : ischémie, AVC, crises, chutes, coma, mort subite."],["","Traitement rapide : sucre par la bouche si conscient, glucagon 1 mg IM ou glucosé hypertonique IV si inconscient, puis collation glucidique."]],"tabs":[{"t":"Fiche pathologie : Hypoglycémie","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Hypoglycémie","Sueurs, tremblements, faim intense (glycémie < 0,7 g/l)","—","—","Pâleur, palpitations, diplopie, agressivité, coma","Glycémie capillaire","Sucre si conscient ; glucagon 1 mg IM ou glucosé hypertonique IV ; collation"]],"c":null}],"imgs":[]},{"pts":[["","L'hyperthyroïdie est une hyperproduction de T3/T4 ; le syndrome clinique est la thyrotoxicose."],["","Signes généraux, cardiaques, musculaires, digestifs et neuropsychiatriques d'accélération."],["","La maladie de Basedow est la cause la plus fréquente ; autres : adénome toxique, goitre multinodulaire, surcharge iodée, iatrogénie."],["","Basedow : T3L et T4L élevées, TSH très basse ; thrombopénie, leucopénie, neutropénie, hyperglycémie, hypocholestérolémie."],["","Traitement spécifique : antithyroïdiens de synthèse ≥ 18 mois pour Basedow, surveillance NFS ; symptomatique : bêtabloquant, sédatifs, corticoïdes."],["","Toute fièvre sous antithyroïdiens impose une NFS pour rechercher une agranulocytose."]],"tabs":[{"t":"Fiche pathologie : Hyperthyroïdie (Basedow)","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Hyperthyroïdie (Basedow)","Thermophobie, tachycardie, amaigrissement malgré appétit","—","—","Tremblements, diarrhée, nervosité, exophtalmie","T3L/T4L ↑, TSH très basse","ATS ≥ 18 mois + NFS ; bêtabloquant, sédatifs"]],"c":null}],"imgs":[[273,"Signes cliniques de l'hyperthyroïdie (5 groupes)"],[274,"Exophtalmie de la maladie de Basedow"]]},{"pts":[["","L'hypothyroïdie, pathologie thyroïdienne la plus fréquente, est un fonctionnement ralenti (T3/T4 libres basses), à prédominance féminine."],["","Signes généraux : asthénie, prise de poids, anorexie, frilosité."],["","Signes spécifiques : infiltration cutanéo-muqueuse, visage en pleine lune, faux œdème élastique, chute des cheveux, peau sèche, ongles cassants, raucité de la voix, surdité."],["","Troubles nerveux, cardiaques (bradycardie, angor), digestifs (constipation), gynécologiques et musculaires."],["","Diagnostic : T3/T4 libres basses avec TSH élevée ; étiologies avec ou sans goitre (Hashimoto, De Quervain…)."],["","Traitement substitutif oral par Lévothyrox 1,2 à 1,5 µg/kg/j, début progressif si risque cardiaque, adaptation sur la TSH ou la T4L."]],"tabs":[{"t":"Fiche pathologie : Hypothyroïdie","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Hypothyroïdie","Ralentissement + infiltration cutanéo-muqueuse","Muscles douloureux, angor d'effort","—","Frilosité, prise de poids, bradycardie, constipation, voix rauque","T4L ↓, TSH ↑","Lévothyrox 1,2–1,5 µg/kg/j, progressif si cardiaque"]],"c":null}],"imgs":[[275,"Hypothyroïdie : visage bouffi et infiltration cutanéo-muqueuse"]]},{"pts":[["","L'hypercorticisme est une hypersécrétion de glucocorticoïdes, d'origine surrénalienne primaire ou secondaire à l'hypersécrétion d'ACTH (maladie de Cushing)."],["","Signes : obésité facio-tronculaire, diabète, HTA, myopathie, faiblesse musculaire, vergetures pourpres, agitation, ostéoporose."],["","L'hypocorticisme (insuffisance surrénalienne chronique = maladie d'Addison) donne fatigabilité, mélanodermie, hypotension, hypoglycémie, troubles digestifs."],["","L'insuffisance surrénalienne iatrogène est due à une corticothérapie de longue durée qui perturbe l'axe hypothalamo-hypophysaire."],["","Hypercorticisme (Cushing) et hypocorticisme (Addison) sont les deux affections surrénaliennes du cours."]],"tabs":[{"t":"Fiche pathologie : Hypercorticisme (Cushing)","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Hypercorticisme (Cushing)","Obésité facio-tronculaire","—","—","Vergetures pourpres, HTA, diabète, ostéoporose, myopathie","Cortisol (hypersécrétion glucocorticoïdes)","Traitement de la cause (adénome, ACTH)"]],"c":null},{"t":"Fiche pathologie : Hypocorticisme (Addison)","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Hypocorticisme (Addison)","Mélanodermie + fatigabilité","—","—","Hypotension, hypoglycémie, anorexie, vomissements","Insuffisance surrénalienne","Substitution, éviter arrêt brutal des corticoïdes"]],"c":null}],"imgs":[]},{"pts":[["","Mise en défaut de tout ou partie de l'antéhypophyse, entraînant un déficit sécrétoire périphérique, de révélation très progressive."],["","Aspect général : faciès pâle albâtre, peau fine, hypopilosité, cheveux fins, aréoles dépigmentées, sujet asthénique et frileux."],["","Le déficit gonadotrope est précoce et constant ; le thyréotrope plus tardif sans goitre ; le corticotrope sans mélanodermie ni choc."],["","Dans le déficit corticotrope, asthénie et hypotension orthostatique, sans mélanodermie, amaigrissement ni choc."],["","Formes : nanisme harmonieux chez l'enfant ; chez l'âgé hypoglycémies et hyponatrémies rebelles ; évolution vers hypoglycémies graves, insuffisance surrénale aiguë, coma."],["","La biologie montre un déficit hormonal périphérique, une glande périphérique intègre aux tests de stimulation et des hormones hypophysaires basses."]],"tabs":[{"t":"Fiche pathologie : Insuffisance antéhypophysaire","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Insuffisance antéhypophysaire","Faciès pâle albâtre, hypopilosité","—","—","Déficit gonadotrope précoce, frilosité, hypoTA orthostatique, hypoglycémie","Hormones périphériques et hypophysaires basses, Thorn normal","Substitution des déficits"]],"c":null}],"imgs":[]},{"pts":[["","L'obésité abdominale/viscérale est une constellation d'anomalies cliniques et biologiques, déterminant essentiel du diabète et des maladies cardiovasculaires."],["","Diagnostic : tour de taille > 94 cm (H) ou > 80 cm (F) + 2 critères parmi HTA, TG > 1,5 g/l, hyperglycémie/diabète, HDL bas."],["","En Côte d'Ivoire, la prévalence de l'obésité était de 23,55 % en 2005 selon la FID."],["","Tout repose sur l'insulino-résistance induite par la surcharge pondérale (génétique + environnement)."],["","La prise en charge est multidisciplinaire : régime, activité physique, médicaments, chirurgie."],["","Stratégie : lutte contre la surcharge pondérale, contre l'insulino-résistance et le diabète, contre le stress oxydatif."]],"tabs":[{"t":"Fiche pathologie : Syndrome métabolique / obésité abdominale","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Syndrome métabolique / obésité abdominale","Tour de taille > 94 cm (H) / > 80 cm (F)","—","—","HTA, TG > 1,5 g/l, hyperglycémie, HDL bas","Tour de taille + 2 critères","Régime, activité, insulino-sensibilisants, prise en charge multidisciplinaire"]],"c":null}],"imgs":[[276,"Diagnostic de l'obésité abdominale : tour de taille + 2 critères"],[277,"Prévalence du syndrome métabolique selon les auteurs"]]},{"pts":[["","L'HTA est une maladie silencieuse aux graves complications ; en CI, un adulte sur trois serait hypertendu et la moitié l'ignore."],["","L'HTA essentielle (95 %) est plurifactorielle ; l'HTA secondaire a une cause (rénale, endocrinienne, médicamenteuse) et guérit si on la traite."],["","La PA normale est 120/80 mmHg ; systolique = contraction ventriculaire, diastolique = relaxation."],["","HTA si PA ≥ 140/90 mmHg (135/85 en automesure), confirmée sur au moins 3 mesures."],["","HTA limitée 140-159/90-99, modérée 160-179/100-109, sévère > 180/110 mmHg."],["","L'HTA donne peu de symptômes : céphalées, vertiges, douleurs thoraciques, essoufflements, troubles visuels, fatigue."],["","Facteurs non modifiables (âge, sexe, hérédité) et modifiables (obésité, diabète, médicaments, stress, tabac, sel, alcool, sédentarité)."],["","L'HTA rigidifie les artères et favorise l'athérome : infarctus, AVC (40 % liés à l'HTA), AOMI, insuffisance cardiaque, dissection aortique, démences, insuffisance rénale, lésions oculaires."],["","Mesure après 10 min de repos, assis, aux deux bras, brassard adapté, 3 mesures ; MAPA sur 24-48 h dans certaines indications ; bilan biologique et ECG."],["","Formes évolutives : crise hypertensive, poussée hypertensive, urgence hypertensive (atteinte viscérale), fausse urgence."],["","Le traitement repose sur 8 familles d'antihypertenseurs, souvent associées (plus de la moitié des patients)."]],"tabs":[{"t":"Fiche pathologie : HTA","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["HTA","PA ≥ 140/90 mmHg sur ≥ 3 mesures (souvent muette)","Céphalées, douleurs thoraciques","—","Vertiges, essoufflement, troubles visuels","Mesures répétées, MAPA, ECG, bilan biologique","8 familles d'antihypertenseurs, hygiène de vie"]],"c":null}],"imgs":[[278,"Associations d'antihypertenseurs recommandées"]]},{"pts":[["","La fausse urgence est une élévation isolée de PA sans souffrance d'organe ; la vraie associe une atteinte viscérale engageant le pronostic vital."],["","Devant un AVC avec PA élevée : voie veineuse, éviter de baisser la PA, traitement symptomatique, référer."],["","Devant un OAP : VVP, baisser la PA < 140/90, oxygène, furosémide 40 mg/h, référer sans attendre."],["","Éclampsie (PA élevée, grossesse, troubles de conscience, convulsions, protéinurie) : VVP, PA < 155/105, pas de captopril, référer."],["","Chaque urgence hypertensive se reconnaît à son atteinte d'organe."],["","Toutes les urgences hypertensives imposent une voie veineuse périphérique et une référence."]],"tabs":[{"t":"Fiche pathologie : AVC hypertensif","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["AVC hypertensif","PA élevée + déficit moteur et/ou troubles de conscience","—","—","—","Clinique","VVP, NE PAS baisser la PA +++, symptomatique, référer"]],"c":null},{"t":"Fiche pathologie : OAP hypertensif","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["OAP hypertensif","PA élevée + détresse respiratoire","—","—","—","Clinique","VVP, PA < 140/90, O2, furosémide 40 mg/h, référer"]],"c":null},{"t":"Fiche pathologie : Éclampsie","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Éclampsie","PA élevée + grossesse + convulsions","—","—","Troubles de conscience, protéinurie","Protéinurie","VVP, PA < 155/105, pas de captopril, référer"]],"c":null}],"imgs":[]},{"pts":[["","Le cancer est une maladie où des cellules acquièrent indépendance, croissance illimitée, perte d'apoptose, angiogenèse, invasion et métastases."],["","Les cellules cancéreuses dérivent d'un même clone ; elles peuvent migrer et former des métastases, d'où un dépistage précoce."],["","Le cancer est une cause majeure de mortalité mondiale, avec une part croissante dans les pays en développement."],["","En 2012, l'Afrique comptait 846 961 cas et 591 161 décès ; 26 % des cancers africains sont liés à des infections chroniques."],["","Les cancers les plus fréquents en Afrique : sein, col de l'utérus, foie chez la femme ; prostate, foie, Kaposi chez l'homme."]],"tabs":[],"imgs":[[279,"Tumeur du poumon"],[280,"Incidence et mortalité des cancers en Afrique (Globocan 2012)"]]},{"pts":[["","Les cellules communiquent par jonctions intercellulaires, système paracrine et système endocrinien ; la disparition des jonctions est la première étape de la cancérogenèse."],["","L'oncogenèse résulte d'une accumulation de défauts du génome ; les cellules précancéreuses peuvent échapper à l'immunosurveillance (phase cachée)."],["","La multiplication tumorale n'est pas plus rapide mais n'est plus régulée ; le temps de doublement se compte en mois."],["","La tumeur se révèle par sa masse ou les troubles de compression qu'elle provoque."],["","L'invasion locale perturbe l'aspect et la fonction de l'organe et du tissu environnant."],["","Hémorragies fréquentes, nécrose par mauvaise vascularisation, découverte par métastase dans ~15 % des cas."]],"tabs":[],"imgs":[]},{"pts":[["","L'anorexie du cancer associe satiété précoce, nausées et troubles du goût ; elle est liée au cancer, au traitement ou au psychisme."],["","La cachexie (AEG avec amaigrissement) découle de l'anorexie et de l'évolution du cancer ; amaigrissement initial = mauvais pronostic."],["","La fièvre est fréquente (phase terminale) ; rechercher une infection ; certains cancers donnent une fièvre spécifique."],["","Les syndromes paranéoplasiques sont des manifestations systémiques liées à la tumeur et disparaissant avec elle ; les endocriniens sont des sécrétions ectopiques."],["","Les troubles hématologiques paranéoplasiques sont variés et très fréquents."],["","Manifestations dermatologiques (dermatomyosite, acanthosis nigricans…) et neurologiques paranéoplasiques."]],"tabs":[],"imgs":[]},{"pts":[["","Il existe les carcinomes, sarcomes, cancers hématopoïétiques et lymphomes ; et une classification par organe."],["","Les risques endogènes ont une composante héréditaire, à distinguer des comportements transmis."],["","Les facteurs exogènes incluent comportements, radioactivité, UV, micro-organismes, obésité, alimentation, mycotoxines, polluants, perturbateurs endocriniens, éclairage artificiel, nanomatériaux."],["","Facteurs probables : produits laitiers, viande, charcuteries, glucides à haut IG, pesticides, acrylamide, benzopyrène."],["","Fruits, légumes, fibres, antioxydants, phyto-œstrogènes, jeûne intermittent et activité physique sont protecteurs."],["","L'obésité jouerait un rôle dans 4 % des cancers, surtout hormono-dépendants, par production œstrogénique accrue."]],"tabs":[],"imgs":[]},{"pts":[["","La prévention repose sur l'évitement des cancérogènes, le rôle protecteur de certains aliments et le traitement des lésions précancéreuses."],["","Le dépistage détecte le plus tôt possible lésions précancéreuses ou cancers chez des personnes asymptomatiques."],["","Le diagnostic de certitude repose sur l'anatomopathologie d'un échantillon (biopsie ou pièce opératoire)."],["","Le traitement est pluridisciplinaire en milieu spécialisé : chirurgie, mini-invasif, chimio, radio, hormonal, immunologique…"],["","Il faut traiter les conséquences de la tumeur, les effets secondaires et la douleur."],["","L'efficacité des traitements alternatifs est souvent inexistante ou non validée en clinique."]],"tabs":[],"imgs":[]},{"pts":[["","Le cancer bronchique est une tumeur maligne de la muqueuse bronchique, de mauvais pronostic."],["","Le tabac cause 80 % des cancers bronchiques ; facteurs professionnels 20 % ; pollution."],["","Deux types : CBNPC (80 %, lent, opérable) et CBPC (20 %, très rapide, chimiosensible, non opérable)."],["","Signes respiratoires, d'extension locorégionale, généraux (AEG, fièvre) et métastatiques."],["","La fibroscopie bronchique est l'examen clé ; complétée par radio/scanner, ponction transpariétale, ACE et bilan d'extension."],["","Bilan d'extension et d'opérabilité, puis chirurgie + radiothérapie si opérable, radio-chimiothérapie sinon ; CBPC : chimiothérapie."]],"tabs":[{"t":"Fiche pathologie : Cancer bronchique","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Cancer bronchique","Toux persistante chez un fumeur","Douleur thoracique","Hémoptysie","Dyspnée, dysphonie, AEG (3A), fièvre","Fibroscopie bronchique (examen clé), scanner, ACE","Bilan d'extension/opérabilité ; chirurgie + radio ou radio-chimio"]],"c":null}],"imgs":[[281,"Cancer bronchique : tumeur au sein du poumon"]]},{"pts":[["","Le cancer de la prostate est hormono-dépendant, adénocarcinome dans 95 %, lent, second cancer masculin des pays industrialisés."],["","Facteurs favorisants : âge > 50 ans, formes familiales, origines ethniques (Noirs, Antillais)."],["","Le stade local est asymptomatique ; découverte fortuite ou par dépistage (PSA + TR annuels)."],["","Le stade évolué donne des signes locorégionaux, ganglionnaires et métastatiques (douleurs osseuses +++)."],["","Le PSA augmente en cas de cancer, HBP, trauma, infection ; confirmation par au moins 6 biopsies ; bilan d'extension."],["","Cancer localisé : prostatectomie radicale, radiothérapie, curiethérapie, ultrasons ; avancé : hormonothérapie (castration) et traitement palliatif."]],"tabs":[{"t":"Fiche pathologie : Cancer de la prostate","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Cancer de la prostate","Asymptomatique au stade local ; nodule dur au TR","Douleurs osseuses +++ (métastases)","Hématurie, rectorragies (évolué)","Dysurie, lymphœdème","TR + PSA, biopsies ≥ 6","Prostatectomie, radio, curiethérapie ; hormonothérapie si avancé"]],"c":null}],"imgs":[[282,"Prostate et toucher rectal"]]},{"pts":[["","Le cancer du sein est le plus fréquent chez la femme ; non invasif dans les canaux, invasif autour."],["","Signes : boule dure, écoulement mamelonnaire, douleur, rétraction du mamelon, peau épaissie, durcie ou rouge."],["","Auto-palpation régulière, mammographie gratuite tous les 2 ans dès 50 ans (± écho, IRM), biopsie pour confirmer, scanner/scintigraphie pour l'extension."],["","Prévention : premier enfant avant 30 ans et allaitement, peu d'alcool, perte de poids, alimentation équilibrée, activité physique."],["","La chirurgie est le premier traitement (tumorectomie dans > 80 %), suivie de radiothérapie, ± chimiothérapie, ± tamoxifène."],["","Survie à 5 ans d'environ 85 %, très variable selon le stade."]],"tabs":[{"t":"Fiche pathologie : Cancer du sein","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Cancer du sein","Boule dure du sein","Douleurs au sein","Écoulement du mamelon","Mamelon rétracté, peau épaissie/rouge","Mammographie, échographie, biopsie","Tumorectomie/mastectomie, radiothérapie, ± chimio, tamoxifène"]],"c":null}],"imgs":[[283,"Cancer du sein : cancer non invasif et invasif des canaux"]]},{"pts":[["","Le cancer du col est une tumeur maligne de la muqueuse cervicale, d'origine infectieuse (HPV) et d'évolution lente ; 85 % de carcinomes épidermoïdes."],["","Cancer de bon pronostic (survie 67 % à 5 ans) dont le dépistage par FCU a réduit de moitié cas et décès."],["","Le HPV, transmis par contact sexuel, est le principal agent ; une infection prolongée 10–15 ans serait responsable de 70 % des tumeurs ; vaccins contre 16 et 18."],["","Autres facteurs : rapports précoces, partenaires multiples, tabac, VIH/immunosuppression, multiparité, pilule, IST (herpès, chlamydiose)."],["","Les lésions précancéreuses (CIN) sont classées 1, 2, 3 selon l'épaisseur atteinte ; elles peuvent régresser ou progresser."],["","Le dépistage repose sur le frottis cervico-utérin, recommandé tous les 3 ans après 2 frottis normaux à 1 an, de 25 à 65 ans."],["","Souvent asymptomatique ; métrorragies provoquées ou spontanées, douleurs ; confirmation par biopsie avec examen anatomopathologique."],["","Le traitement, décidé en RCP avec consentement éclairé, associe chirurgie, radiothérapie (externe, curiethérapie) et chimiothérapie (5-FU, sels de platine)."]],"tabs":[{"t":"Fiche pathologie : Cancer du col de l'utérus","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Cancer du col de l'utérus","Souvent asymptomatique","Douleurs pendant les rapports, bas-ventre, lombaires","Métrorragies provoquées ou spontanées","Pertes blanches, troubles urinaires","FCU, colposcopie, biopsie/conisation, anapath","RCP ; chirurgie, radiothérapie, chimio (5-FU, sels de platine)"]],"c":null}],"imgs":[[284,"Cancer du col de l'utérus"],[285,"Papillomavirus humain (HPV)"],[286,"Évolution des CIN : régression, persistance, progression (Ostor 1993)"],[287,"Frottis : prélèvement de cellules à la surface du col"],[288,"Évolution du cancer du col de l'utérus (sain → stade très avancé)"],[289,"Examen anatomopathologique au microscope"]]},{"pts":[["","Le cancer de la vessie est le 2e cancer uro-génital, plus fréquent chez l'homme (3/1), âge moyen 65 ans ; superficiel 80 %, infiltrant 20 %."],["","Facteurs : tabac (50 %), expositions professionnelles, phénacétine, bilharziose."],["","Sémiologie : hématurie (1er signe), troubles mictionnels, cystite à ECBU stérile ; examens : ECBU cytologie, cystoscopie, UIV, échographie, scanner."],["","Arrêt du tabac ; tumeurs superficielles : résection endoscopique ; invasives : cystectomie avec curage et dérivation ; si métastases : radio-chimiothérapie."]],"tabs":[{"t":"Fiche pathologie : Cancer de la vessie","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Cancer de la vessie","Hématurie (1er signe)","—","Hématurie","Pollakiurie, dysurie, cystite à ECBU stérile","Cystoscopie, ECBU cytologie, échographie, scanner","Arrêt tabac ; résection endoscopique ; cystectomie si invasif"]],"c":null}],"imgs":[]}],"comp":[{"t":"Pathologies : tableau comparatif","h":["Pathologie","Signe cardinal","Douleur","Saignement","Signes associés","Examen clé","CAT / traitement"],"r":[["Diabète de type 1","Syndrome polyuro-polydipsique brutal + amaigrissement","—","—","Asthénie, polyphagie, cétose, sujet < 30 ans","Glycémie à jeun ≥ 1,26 g/l ×2, bandelette (glucose, cétones)","Insuline, ETP, régime, activité physique"],["Diabète de type 2","Découverte fortuite ou par complication","—","—","Obésité, hérédité, infections, furoncles","GAJ ≥ 1,26 g/l ×2, GPP ≥ 2 g/l, HbA1c ≥ 6,5 %","Régime, activité ≥ 30 min/j, antidiabétiques oraux, ETP"],["Acidocétose diabétique","Dyspnée de Kussmaul + odeur cétonique","Douleurs abdominales","—","Vomissements, déshydratation, troubles de conscience → coma","Hyperglycémie, acidose, cétonémie, kaliémie","SSI, insuline intensive, K/Na, facteur déclenchant, référence"],["Hypoglycémie","Sueurs, tremblements, faim intense (glycémie < 0,7 g/l)","—","—","Pâleur, palpitations, diplopie, agressivité, coma","Glycémie capillaire","Sucre si conscient ; glucagon 1 mg IM ou glucosé hypertonique IV ; collation"],["Hyperthyroïdie (Basedow)","Thermophobie, tachycardie, amaigrissement malgré appétit","—","—","Tremblements, diarrhée, nervosité, exophtalmie","T3L/T4L ↑, TSH très basse","ATS ≥ 18 mois + NFS ; bêtabloquant, sédatifs"],["Hypothyroïdie","Ralentissement + infiltration cutanéo-muqueuse","Muscles douloureux, angor d'effort","—","Frilosité, prise de poids, bradycardie, constipation, voix rauque","T4L ↓, TSH ↑","Lévothyrox 1,2–1,5 µg/kg/j, progressif si cardiaque"],["Hypercorticisme (Cushing)","Obésité facio-tronculaire","—","—","Vergetures pourpres, HTA, diabète, ostéoporose, myopathie","Cortisol (hypersécrétion glucocorticoïdes)","Traitement de la cause (adénome, ACTH)"],["Hypocorticisme (Addison)","Mélanodermie + fatigabilité","—","—","Hypotension, hypoglycémie, anorexie, vomissements","Insuffisance surrénalienne","Substitution, éviter arrêt brutal des corticoïdes"],["Insuffisance antéhypophysaire","Faciès pâle albâtre, hypopilosité","—","—","Déficit gonadotrope précoce, frilosité, hypoTA orthostatique, hypoglycémie","Hormones périphériques et hypophysaires basses, Thorn normal","Substitution des déficits"],["Syndrome métabolique / obésité abdominale","Tour de taille > 94 cm (H) / > 80 cm (F)","—","—","HTA, TG > 1,5 g/l, hyperglycémie, HDL bas","Tour de taille + 2 critères","Régime, activité, insulino-sensibilisants, prise en charge multidisciplinaire"],["HTA","PA ≥ 140/90 mmHg sur ≥ 3 mesures (souvent muette)","Céphalées, douleurs thoraciques","—","Vertiges, essoufflement, troubles visuels","Mesures répétées, MAPA, ECG, bilan biologique","8 familles d'antihypertenseurs, hygiène de vie"],["AVC hypertensif","PA élevée + déficit moteur et/ou troubles de conscience","—","—","—","Clinique","VVP, NE PAS baisser la PA +++, symptomatique, référer"],["OAP hypertensif","PA élevée + détresse respiratoire","—","—","—","Clinique","VVP, PA < 140/90, O2, furosémide 40 mg/h, référer"],["Éclampsie","PA élevée + grossesse + convulsions","—","—","Troubles de conscience, protéinurie","Protéinurie","VVP, PA < 155/105, pas de captopril, référer"],["Cancer bronchique","Toux persistante chez un fumeur","Douleur thoracique","Hémoptysie","Dyspnée, dysphonie, AEG (3A), fièvre","Fibroscopie bronchique (examen clé), scanner, ACE","Bilan d'extension/opérabilité ; chirurgie + radio ou radio-chimio"],["Cancer de la prostate","Asymptomatique au stade local ; nodule dur au TR","Douleurs osseuses +++ (métastases)","Hématurie, rectorragies (évolué)","Dysurie, lymphœdème","TR + PSA, biopsies ≥ 6","Prostatectomie, radio, curiethérapie ; hormonothérapie si avancé"],["Cancer du sein","Boule dure du sein","Douleurs au sein","Écoulement du mamelon","Mamelon rétracté, peau épaissie/rouge","Mammographie, échographie, biopsie","Tumorectomie/mastectomie, radiothérapie, ± chimio, tamoxifène"],["Cancer du col de l'utérus","Souvent asymptomatique","Douleurs pendant les rapports, bas-ventre, lombaires","Métrorragies provoquées ou spontanées","Pertes blanches, troubles urinaires","FCU, colposcopie, biopsie/conisation, anapath","RCP ; chirurgie, radiothérapie, chimio (5-FU, sels de platine)"],["Cancer de la vessie","Hématurie (1er signe)","—","Hématurie","Pollakiurie, dysurie, cystite à ECBU stérile","Cystoscopie, ECBU cytologie, échographie, scanner","Arrêt tabac ; résection endoscopique ; cystectomie si invasif"]],"c":null},{"t":"Signe / symptôme → pathologie évoquée","h":["Signe / symptôme","Pathologie(s) évoquée(s)"],"r":[["Polyurie / polydipsie","Diabète (DT1 surtout), acidocétose"],["Amaigrissement malgré appétit conservé","Diabète, hyperthyroïdie"],["Amaigrissement + AEG (3A)","Cancer bronchique, cachexie cancéreuse"],["Dyspnée de Kussmaul","Acidocétose diabétique"],["Odeur cétonique de l'haleine","Acidocétose diabétique"],["Sueurs, tremblements, faim intense","Hypoglycémie modérée"],["Agressivité, attitudes bizarres, diplopie","Hypoglycémie (neuroglucopénie)"],["Thermophobie, sueurs profuses","Hyperthyroïdie"],["Frilosité","Hypothyroïdie, insuffisance antéhypophysaire"],["Tachycardie, palpitations","Hyperthyroïdie, hypoglycémie"],["Bradycardie","Hypothyroïdie"],["Diarrhée motrice","Hyperthyroïdie"],["Constipation","Hypothyroïdie, tumeurs coliques"],["Visage en pleine lune, faux œdème ferme","Hypothyroïdie"],["Obésité facio-tronculaire, vergetures pourpres","Hypercorticisme (Cushing)"],["Mélanodermie","Maladie d'Addison"],["Faciès pâle albâtre, hypopilosité","Insuffisance antéhypophysaire"],["Aménorrhée sans bouffées de chaleur","Insuffisance antéhypophysaire (déficit gonadotrope)"],["Tour de taille augmenté","Syndrome métabolique / obésité abdominale"],["Céphalées, vertiges, troubles visuels","HTA, poussée hypertensive"],["Déficit moteur + PA élevée","AVC hypertensif"],["Détresse respiratoire + PA élevée","OAP hypertensif"],["Convulsions + grossesse + PA élevée","Éclampsie"],["Furoncles à répétition, prurit vaginal","Diabète (signes d'orientation)"],["Toux persistante","Cancer bronchique"],["Hémoptysie","Cancer bronchique"],["Dysphonie","Cancer bronchique (compression médiastinale), cancer du larynx"],["Boule dure du sein, peau d'orange","Cancer du sein"],["Mamelon rétracté, écoulement mamelonnaire","Cancer du sein"],["Métrorragies provoquées par les rapports","Cancer du col de l'utérus"],["Hématurie","Cancer de la vessie (1er signe), prostate évolué, rein"],["Douleurs osseuses","Métastases (cancer de la prostate +++)"],["Ganglion sus-claviculaire (Troisier)","Tumeur digestive ou pelvienne métastatique"],["Gros testicule non douloureux","Cancer du testicule"],["Hyponatrémie + œdème","Syndrome de Schwartz-Bartter (CBPC)"],["Hypercalcémie","Métastases osseuses, PTH ectopique (cancers épidermoïdes)"],["Doigts en baguette de tambour","Cancers bronchiques/gastriques (GH ectopique)"],["Fièvre prolongée inexpliquée","Hodgkin, leucémie, cancer du rein, métastases hépatiques"],["Polyglobulie","Tumeur rénale (EPO ectopique)"]],"c":null}]},"course":["<div class=\"pgm\">p. 7<\/div><h4>Introduction à l&#x27;Endocrinologie<\/h4><p>Le système endocrinien est un ensemble fonctionnel formé par les glandes endocrines. Il coordonne et régule les fonctions suivantes :<\/p><ul><li>Reproduction<\/li><li>Développement de l&#x27;embryon<\/li><li>Équilibration et maintien de l&#x27;eau et des électrolytes<\/li><li>Nutrition<\/li><li>Croissance<\/li><li>Réaction aux stimuli (peur, agitation)<\/li><li>Production, utilisation et stockage de l&#x27;énergie<\/li><\/ul><h4>Définition<\/h4><h4>Endocrinologie<\/h4><p>L&#x27;étude (logos) de la sécrétion (crine) interne (endo). Elle étudie de nombreux phénomènes physiologiques dans lesquels interviennent les hormones.<\/p><h4>Hormones<\/h4><p>C&#x27;est une substance chimique produite par les glandes endocrines. Elle est déversée dans le sang et transportée par la circulation sanguine. Elle exerce une action spécifique à distance sur un organe ou des cellules cibles.<\/p><h4>Quelques hormones<\/h4><ul><li>Insuline<\/li><li>Glucagon<\/li><li>Thyroxine<\/li><li>Testostérone<\/li><li>Œstrogène<\/li><li>Progestérone<\/li><li>Adrénaline<\/li><li>Cortisone<\/li><li>Parathormone<\/li><li>Etc.<\/li><\/ul>","<div class=\"pgm\">p. 8<\/div><h4>Différents types de glandes<\/h4><h4>Glandes exocrines<\/h4><p>Déversent leurs sécrétions à travers un canal :<\/p><ul><li>Soit à l&#x27;extérieur du corps : glandes sudoripares…<\/li><li>Soit dans une cavité : glandes salivaires…<\/li><\/ul><p>Exemple des glandes mammaires.<\/p><h4>Glandes endocrines<\/h4><p>Déversent leurs sécrétions (hormones) directement dans les vaisseaux sanguins qui les traversent.<\/p><p>Exemple de la glande thyroïde.<\/p><h4>Quelques organes endocriniens<\/h4><ul><li>Le pancréas<\/li><li>La thyroïde<\/li><li>Les parathyroïdes<\/li><li>Les surrénales<\/li><li>L&#x27;hypothalamus<\/li><li>L&#x27;hypophyse<\/li><li>Le thymus<\/li><li>Les testicules<\/li><li>Les ovaires<\/li><li>Etc.<\/li><\/ul><div class=\"pgm\">p. 9<\/div><h4>Glandes amphicrines<\/h4><p>Ce sont des glandes à la fois endocrines et exocrines. Exemple du pancréas.<\/p><h4>Quelques organes contenant des amas cellulaires qui sécrètent des hormones<\/h4><ul><li>Les reins<\/li><li>L&#x27;estomac<\/li><li>Le foie<\/li><li>L&#x27;intestin grêle<\/li><li>La peau<\/li><li>Le cœur<\/li><li>Etc.<\/li><\/ul><h4>Différents types d&#x27;hormones<\/h4><p>Les glandes endocrines fabriquent 3 grandes catégories d&#x27;hormones :<\/p><ul><li>1° Les hormones peptidiques<\/li><li>2° Les hormones stéroïdiennes<\/li><li>3° Les hormones mono-aminées<\/li><\/ul><h4>Hormones peptidiques<\/h4><p>Ce sont des petites protéines. Une fois sécrétées dans le sang, ces hormones y circulent librement. Elles agissent sur les cellules cibles par l&#x27;intermédiaire de récepteurs protéiques traversant les membranes plasmiques des cellules cibles. Les récepteurs sont spécifiques pour une hormone donnée, mais une hormone peut avoir plusieurs types de récepteurs membranaires.<\/p><h4>Exemples d&#x27;hormones peptidiques<\/h4><ul><li>L&#x27;insuline<\/li><li>Le glucagon<\/li><li>La parathormone<\/li><li>La prolactine<\/li><li>L&#x27;érythropoïétine<\/li><li>La GH<\/li><li>La TSH<\/li><\/ul><div class=\"pgm\">p. 10<\/div><ul><li>La LH<\/li><li>La FSH<\/li><li>L&#x27;ACTH<\/li><li>La TRH…<\/li><\/ul><h4>Hormones stéroïdiennes<\/h4><p>Ce sont des lipides synthétisés à partir d&#x27;un noyau de cholestérol.<\/p><p>Ces stéroïdes doivent s&#x27;allier avec des protéines plasmatiques afin d&#x27;être transportés dans le flux sanguin. Le complexe stéroïde-protéine est inactif, seule l&#x27;hormone stéroïde libre a une action endocrine. La protéine de transport ne libère l&#x27;hormone stéroïde qu&#x27;au niveau des capillaires sanguins qui irriguent les organes cibles.<\/p><p>Ces hormones stéroïdiennes agissent sur les récepteurs intra-cellulaires.<\/p><h4>Exemples d&#x27;hormones stéroïdiennes<\/h4><ul><li>Cortisol<\/li><li>Androgènes<\/li><li>Progestérone<\/li><li>Œstrogènes…<\/li><\/ul><h4>Hormones mono-aminées<\/h4><p>Elles dérivent toutes d&#x27;un acide aminé : la tyrosine.<\/p><p>Ce sont des petites molécules et leur mécanisme d&#x27;action sur les cellules cibles est proche des hormones peptidiques ; elles circulent librement dans le sang et agissent sur les cellules cibles par l&#x27;intermédiaire de récepteurs transmembranaires.<\/p><p>Le premier sous-groupe contient essentiellement :<\/p><ul><li>L&#x27;adrénaline<\/li><li>La noradrénaline<\/li><li>La dopamine<\/li><\/ul><p>L&#x27;autre sous-groupe est constitué par les hormones thyroïdiennes :<\/p><ul><li>T3 et T4.<\/li><\/ul><div class=\"pgm\">p. 11<\/div><p>Elles sont liées aux protéines plasmatiques dans leur transport, ce qui les inactive. Elles agissent sur des récepteurs intra-cellulaires. Seules les cellules cibles qui contiennent des récepteurs sont sensibles aux hormones.<\/p><h4>Différents modes d&#x27;action des hormones<\/h4><p>(Tableau : glande endocrine / hormone / abréviation / action physiologique principale)<\/p><ul><li>Neurohypophyse (provenant des neurones hypothalamiques) : hormone antidiurétique (ADH) → réabsorption de l&#x27;eau ; ocytocine → éjection du lait, contraction du muscle utérin.<\/li><li>Adénohypophyse : hormone de croissance (GH) → croissance de l&#x27;os et du muscle (hormone anabolisante) ; hormone corticotrope (ACTH) → favorise la libération des glucocorticoïdes et des androgènes ; hormone thyréotrope (TSH) → stimule la libération des hormones thyroïdiennes ; hormone folliculostimulante (FSH) → ovaire : stimule la maturation du follicule et la production d&#x27;œstrogènes ; testicule : stimule la spermatogenèse ; hormone lutéinisante (LH) → ovaire : déclenche l&#x27;ovulation et stimule la production d&#x27;œstrogènes et de progestérone ; testicule : stimule la production de testostérone ; prolactine (PRL) → stimule la lactation.<\/li><li>Thyroïde : hormones thyroïdiennes (TH, T3/T4) → augmentent le métabolisme cellulaire en favorisant la combustion du glucose ; croissance et développement des tissus (squelettique et nerveux).<\/li><li>Parathyroïde : parathormone (PTH) → élève le taux de calcium sanguin.<\/li><li>Îlots de Langerhans du pancréas : cellules β → insuline : augmente la perméabilité des cellules pour le glucose (diminution de la glycémie = hormone hypoglycémiante) ; cellules α → glucagon : élève la glycémie (hormone hyperglycémiante).<\/li><li>Surrénales, zone médullaire : adrénaline → hormone de l&#x27;urgence, action sur le cœur, les artérioles, le muscle lisse et augmente la glycémie.<\/li><li>Surrénales, zone corticale : glomérulée → aldostérone : rétention d&#x27;eau et de sels par le rein ; fasciculée → cortisol : action sur le métabolisme des cellules, sur l&#x27;immunité et la résistance à l&#x27;infection ; réticulée → androgènes : action virilisante.<\/li><li>Testicules : testostérone (T) → développement et maintien de l&#x27;appareil génital mâle et des caractères sexuels secondaires, du comportement.<\/li><li>Ovaires : thèque interne et corps jaune → œstrogènes (E) : développement et maintien de la fonction cyclique de l&#x27;appareil génital féminin, des caractères sexuels secondaires, des canaux galactophores ; corps jaune → progestérone (P) : développement des alvéoles mammaires, préparation de l&#x27;utérus à la nidation, maintien de la grossesse.<\/li><li>Placenta : œstrogènes, progestérone, hormone gonadotrophine chorionique (HCG) → maintien de la grossesse.<\/li><\/ul><h4>Régulation hormonale<\/h4><p>C&#x27;est le processus complexe par lequel la sécrétion des hormones est maintenue dans un équilibre utile à l&#x27;homéostasie. La libération des hormones dans le sang dépend de plusieurs facteurs, notamment :<\/p><h4>Concentration sanguine d&#x27;autres hormones<\/h4><p>En effet, le taux plasmatique d&#x27;une hormone détermine la sécrétion hypophysaire. Il s&#x27;en suit la notion de rétrocontrôle (feedback), qui peut être positif (augmentation du taux d&#x27;hormone) ou négatif (diminution du taux d&#x27;hormone).<\/p><h4>Certaines substances contrôlées par les hormones<\/h4>","<div class=\"pgm\">p. 11<\/div><p>Elles sont liées aux protéines plasmatiques dans leur transport, ce qui les inactive. Elles agissent sur des récepteurs intra-cellulaires. Seules les cellules cibles qui contiennent des récepteurs sont sensibles aux hormones.<\/p><h4>Différents modes d&#x27;action des hormones<\/h4><p>(Tableau : glande endocrine / hormone / abréviation / action physiologique principale)<\/p><ul><li>Neurohypophyse (provenant des neurones hypothalamiques) : hormone antidiurétique (ADH) → réabsorption de l&#x27;eau ; ocytocine → éjection du lait, contraction du muscle utérin.<\/li><li>Adénohypophyse : hormone de croissance (GH) → croissance de l&#x27;os et du muscle (hormone anabolisante) ; hormone corticotrope (ACTH) → favorise la libération des glucocorticoïdes et des androgènes ; hormone thyréotrope (TSH) → stimule la libération des hormones thyroïdiennes ; hormone folliculostimulante (FSH) → ovaire : stimule la maturation du follicule et la production d&#x27;œstrogènes ; testicule : stimule la spermatogenèse ; hormone lutéinisante (LH) → ovaire : déclenche l&#x27;ovulation et stimule la production d&#x27;œstrogènes et de progestérone ; testicule : stimule la production de testostérone ; prolactine (PRL) → stimule la lactation.<\/li><li>Thyroïde : hormones thyroïdiennes (TH, T3/T4) → augmentent le métabolisme cellulaire en favorisant la combustion du glucose ; croissance et développement des tissus (squelettique et nerveux).<\/li><li>Parathyroïde : parathormone (PTH) → élève le taux de calcium sanguin.<\/li><li>Îlots de Langerhans du pancréas : cellules β → insuline : augmente la perméabilité des cellules pour le glucose (diminution de la glycémie = hormone hypoglycémiante) ; cellules α → glucagon : élève la glycémie (hormone hyperglycémiante).<\/li><li>Surrénales, zone médullaire : adrénaline → hormone de l&#x27;urgence, action sur le cœur, les artérioles, le muscle lisse et augmente la glycémie.<\/li><li>Surrénales, zone corticale : glomérulée → aldostérone : rétention d&#x27;eau et de sels par le rein ; fasciculée → cortisol : action sur le métabolisme des cellules, sur l&#x27;immunité et la résistance à l&#x27;infection ; réticulée → androgènes : action virilisante.<\/li><li>Testicules : testostérone (T) → développement et maintien de l&#x27;appareil génital mâle et des caractères sexuels secondaires, du comportement.<\/li><li>Ovaires : thèque interne et corps jaune → œstrogènes (E) : développement et maintien de la fonction cyclique de l&#x27;appareil génital féminin, des caractères sexuels secondaires, des canaux galactophores ; corps jaune → progestérone (P) : développement des alvéoles mammaires, préparation de l&#x27;utérus à la nidation, maintien de la grossesse.<\/li><li>Placenta : œstrogènes, progestérone, hormone gonadotrophine chorionique (HCG) → maintien de la grossesse.<\/li><\/ul><h4>Régulation hormonale<\/h4><p>C&#x27;est le processus complexe par lequel la sécrétion des hormones est maintenue dans un équilibre utile à l&#x27;homéostasie. La libération des hormones dans le sang dépend de plusieurs facteurs, notamment :<\/p><h4>Concentration sanguine d&#x27;autres hormones<\/h4><p>En effet, le taux plasmatique d&#x27;une hormone détermine la sécrétion hypophysaire. Il s&#x27;en suit la notion de rétrocontrôle (feedback), qui peut être positif (augmentation du taux d&#x27;hormone) ou négatif (diminution du taux d&#x27;hormone).<\/p><h4>Certaines substances contrôlées par les hormones<\/h4><div class=\"pgm\">p. 12<\/div><p>C&#x27;est le cas de l&#x27;action de la glycémie sur l&#x27;insulinémie. En effet, lorsque la glycémie s&#x27;élève, cela déclenche la sécrétion de l&#x27;insuline dans le sang.<\/p><h4>Stimulation nerveuse<\/h4><p>Durant les 13 premiers jours du cycle, la libération dans le sang d&#x27;œstrogènes par les ovaires va être détectée par le cerveau (hypophyse) qui va limiter la sécrétion de FSH et LH.<\/p><p>Le stress important et continu va enclencher la sécrétion du cortisone par les surrénales.<\/p><h4>Organisation anatomique et fonctionnelle de quelques glandes endocrines<\/h4><h4>Thyroïde<\/h4><p>Du point de vue histologique, la thyroïde possède 02 types de cellules :<\/p><ul><li>Thyréocytes (99,9 %) : sécrètent les hormones thyroïdiennes<\/li><li>Cellules C (0,1 %) : sécrètent la thyrocalcitonine<\/li><\/ul><p>Pour synthétiser ses hormones, la thyroïde utilise : un acide aminé = la tyrosine, et un métal = l&#x27;iode.<\/p><p>Ainsi, Tyrosine + Iode = Thyroxine (T4).<\/p><p>La glande thyroïde produit essentiellement :<\/p><ul><li>La thyroxine (T4) ou tétra-iodo-thyronine<\/li><li>La tri-iodo-thyronine (T3)<\/li><li>La calcitonine<\/li><\/ul><p>La sécrétion des hormones thyroïdiennes est sous le contrôle de la TSH produite par l&#x27;hypophyse. L&#x27;hypophyse elle-même est stimulée par l&#x27;hypothalamus via une autre hormone : la TRH.<\/p>","<div class=\"pgm\">p. 12<\/div><p>C&#x27;est le cas de l&#x27;action de la glycémie sur l&#x27;insulinémie. En effet, lorsque la glycémie s&#x27;élève, cela déclenche la sécrétion de l&#x27;insuline dans le sang.<\/p><h4>Stimulation nerveuse<\/h4><p>Durant les 13 premiers jours du cycle, la libération dans le sang d&#x27;œstrogènes par les ovaires va être détectée par le cerveau (hypophyse) qui va limiter la sécrétion de FSH et LH.<\/p><p>Le stress important et continu va enclencher la sécrétion du cortisone par les surrénales.<\/p><h4>Organisation anatomique et fonctionnelle de quelques glandes endocrines<\/h4><h4>Thyroïde<\/h4><p>Du point de vue histologique, la thyroïde possède 02 types de cellules :<\/p><ul><li>Thyréocytes (99,9 %) : sécrètent les hormones thyroïdiennes<\/li><li>Cellules C (0,1 %) : sécrètent la thyrocalcitonine<\/li><\/ul><p>Pour synthétiser ses hormones, la thyroïde utilise : un acide aminé = la tyrosine, et un métal = l&#x27;iode.<\/p><p>Ainsi, Tyrosine + Iode = Thyroxine (T4).<\/p><p>La glande thyroïde produit essentiellement :<\/p><ul><li>La thyroxine (T4) ou tétra-iodo-thyronine<\/li><li>La tri-iodo-thyronine (T3)<\/li><li>La calcitonine<\/li><\/ul><p>La sécrétion des hormones thyroïdiennes est sous le contrôle de la TSH produite par l&#x27;hypophyse. L&#x27;hypophyse elle-même est stimulée par l&#x27;hypothalamus via une autre hormone : la TRH.<\/p><div class=\"pgm\">p. 13<\/div><p>L&#x27;hypophyse fonctionne avec un mécanisme de rétro-contrôle (feed-back). Cela veut dire qu&#x27;un contrôle constant du taux d&#x27;hormones thyroïdiennes dans le sang permet à l&#x27;hypophyse de lancer ou de stopper la production hormonale de la thyroïde.<\/p><h4>Pancréas<\/h4><p>= Glande annexe au tube digestif de type amphicrine, c&#x27;est-à-dire à la fois exocrine et endocrine.<\/p><p>Au plan histologique, la composante exocrine du parenchyme pancréatique est formée d&#x27;acini séreux (99 %) et la composante endocrine constituée par les îlots de Langerhans (1 % du parenchyme). Les populations cellulaires endocrines comprennent essentiellement des endocrinocytes alpha (α) synthétisant le glucagon et des endocrinocytes bêta (β) élaborant davantage l&#x27;insuline.<\/p><p>Le pancréas endocrine sécrète et déverse dans le sang des hormones telles que :<\/p><ul><li>Glucagon<\/li><li>Insuline<\/li><li>Somatostatine<\/li><li>Polypeptide pancréatique<\/li><\/ul><p>La sécrétion d&#x27;insuline s&#x27;active par l&#x27;augmentation de la glycémie, l&#x27;élévation des taux plasmatiques d&#x27;acides gras et d&#x27;acides aminés. Par ailleurs, la sécrétion du glucagon s&#x27;active par la diminution de la glycémie.<\/p><h4>Surrénales<\/h4><div class=\"pgm\">p. 14<\/div><p>(Schéma : corticosurrénale — zone glomérulée → aldostérone ; zone fasciculée → cortisol ; zone réticulée → hormones sexuelles ; médullosurrénale → adrénaline, noradrénaline.)<\/p><p>La régulation de la sécrétion de ses hormones est assurée par l&#x27;hypothalamus et l&#x27;hypophyse selon le schéma : hypothalamus → CRF → hypophyse antérieure → ACTH → surrénales.<\/p><ul><li>Zone glomérulée → aldostérone (régulée aussi par le système rénine-angiotensine et l&#x27;équilibre hydrominéral Na+/K+)<\/li><li>Zone fasciculée → cortisol<\/li><li>Zone réticulée → androgènes<\/li><\/ul><h4>Testicules et ovaires<\/h4><p>(Schéma : axe hypothalamo-hypophysaire → LH et FSH libérées dans le sang → testicules / ovaires → hormones sexuelles.)<\/p><h4>Hypothalamus et hypophyse<\/h4><p>(Schéma : neurones neurosécréteurs des noyaux paraventriculaire et supra-optique, système porte hypothalamo-hypophysaire, hypophyse antérieure et postérieure, vasopressine et ocytocine.)<\/p><div class=\"pgm\">p. 15<\/div><h4>L&#x27;hypothalamus<\/h4><p>C&#x27;est le cerveau endocrinien de l&#x27;organisme puisqu&#x27;il commande la sécrétion de toutes les glandes endocrines du corps. Il sécrète :<\/p><ul><li>TRH (thyreo releasing hormone) qui stimule la sécrétion et la libération de TSH hypophysaire (qui stimule la glande thyroïde)<\/li><li>GnRH (gonadotrophin releasing hormone) qui provoque à la fois la libération de FSH et de LH (qui régulent la sécrétion des glandes sexuelles)<\/li><li>CRF (cortico releasing factor) qui favorise la libération d&#x27;ACTH par l&#x27;hypophyse et sa synthèse (action sur la glande corticosurrénale qui sécrète du cortisol)<\/li><li>ADH ou hormone antidiurétique ou vasopressine<\/li><li>Ocytocine<\/li><\/ul><p>Les 2 dernières hormones (ocytocine et ADH) sont sécrétées au niveau de l&#x27;hypothalamus puis transportées par la tige pituitaire dans l&#x27;hypophyse postérieure ou post-hypophyse où elles sont stockées.<\/p><h4>Hypophyse<\/h4><p>L&#x27;hypophyse est reliée à l&#x27;hypothalamus par l&#x27;infundibulum (tige de connexion ou tige pituitaire). La glande se divise en deux parties :<\/p><p>L&#x27;adénohypophyse ou antéhypophyse, partie glandulaire de l&#x27;hypophyse, qui sécrète six hormones :<\/p><ul><li>GH<\/li><li>TSH<\/li><li>FSH<\/li><li>LH<\/li><li>PRL<\/li><li>ACTH<\/li><\/ul><p>La post-hypophyse ou neurohypophyse est la partie postérieure de la glande qui contient deux hormones : ADH et OT (ocytocine).<\/p><h4>Communication entre l&#x27;axe hypothalamo-hypophysaire et : la thyroïde, les testicules<\/h4><div class=\"pgm\">p. 16<\/div><h4>Que retenir ?<\/h4><p>Le système endocrinien se présente comme un parfait orchestre devant réaliser une harmonieuse symphonie :<\/p><ul><li>Cerveau → hypothalamus (compositeur) : délivre des compositions = hormones de stimulation<\/li><li>Hypophyse (chef d&#x27;orchestre) : s&#x27;assure que les musiciens jouent bien leurs partitions<\/li><li>Lobe antérieur : FSH → ovaire ; LH → testicule ; ACTH (corticotrope) → cortex surrénale ; TSH (thyréostimuline) → thyroïde ; prolactine → glandes mammaires ; somatotrope (STH) → os et cartilage ; mélanotrope (MSH) → peau<\/li><li>Lobe postérieur : vasopressine (antidiurétique) → reins ; ocytocine → utérus<\/li><li>Instruments producteurs de la bonne musique = hormones ; musiciens qui accordent leurs instruments et les jouent = glandes endocrines et organes cibles<\/li><\/ul><h4>Dérèglement hormonal<\/h4><p>Nous savons que les hormones sont au cœur de la coordination et de la régulation de toutes les fonctions vitales de notre organisme. Ainsi, tout dysfonctionnement de leur production, sécrétion ou régulation aura un impact sérieux et délétère sur le déroulé de la vie.<\/p><p>Les pathologies en lien avec un dérèglement hormonal sont nombreuses. La recherche de leur diagnostic et la mise en place d&#x27;un traitement adéquat constituent une bonne partie de l&#x27;activité du clinicien endocrinologue.<\/p><h4>Pathologies endocriniennes courantes<\/h4><h4>Affections du pancréas<\/h4><h4>Diabète<\/h4><p>Le diabète fait partie des quatre principales MNT de l&#x27;OMS. C&#x27;est une maladie chronique qui est responsable de conséquences multiformes, gravissimes et souvent débilitantes.<\/p>","<div class=\"pgm\">p. 16<\/div><h4>Que retenir ?<\/h4><p>Le système endocrinien se présente comme un parfait orchestre devant réaliser une harmonieuse symphonie :<\/p><ul><li>Cerveau → hypothalamus (compositeur) : délivre des compositions = hormones de stimulation<\/li><li>Hypophyse (chef d&#x27;orchestre) : s&#x27;assure que les musiciens jouent bien leurs partitions<\/li><li>Lobe antérieur : FSH → ovaire ; LH → testicule ; ACTH (corticotrope) → cortex surrénale ; TSH (thyréostimuline) → thyroïde ; prolactine → glandes mammaires ; somatotrope (STH) → os et cartilage ; mélanotrope (MSH) → peau<\/li><li>Lobe postérieur : vasopressine (antidiurétique) → reins ; ocytocine → utérus<\/li><li>Instruments producteurs de la bonne musique = hormones ; musiciens qui accordent leurs instruments et les jouent = glandes endocrines et organes cibles<\/li><\/ul><h4>Dérèglement hormonal<\/h4><p>Nous savons que les hormones sont au cœur de la coordination et de la régulation de toutes les fonctions vitales de notre organisme. Ainsi, tout dysfonctionnement de leur production, sécrétion ou régulation aura un impact sérieux et délétère sur le déroulé de la vie.<\/p><p>Les pathologies en lien avec un dérèglement hormonal sont nombreuses. La recherche de leur diagnostic et la mise en place d&#x27;un traitement adéquat constituent une bonne partie de l&#x27;activité du clinicien endocrinologue.<\/p><h4>Pathologies endocriniennes courantes<\/h4><h4>Affections du pancréas<\/h4><h4>Diabète<\/h4><p>Le diabète fait partie des quatre principales MNT de l&#x27;OMS. C&#x27;est une maladie chronique qui est responsable de conséquences multiformes, gravissimes et souvent débilitantes.<\/p><div class=\"pgm\">p. 17<\/div><p>Pour l&#x27;OMS, le diabète représente aujourd&#x27;hui une épidémie mondiale. La croissance de sa prévalence reste exponentielle dans le monde entier du fait de l&#x27;industrialisation responsable du changement du mode de vie des populations.<\/p><p>Désormais, dans nos pays subsahariens, plus qu&#x27;un problème de santé publique majeur, le diabète est devenu un frein au développement. En Côte d&#x27;Ivoire, la prévalence du diabète est de 6,2 % (PREVADIA 2017).<\/p><h4>Définition<\/h4><p>Le diabète est une élévation anormale et permanente du taux de sucre dans le sang. Le sucre présent dans le sang a du mal à être utilisé car il a des difficultés à entrer dans les cellules du corps, par suite d&#x27;une carence partielle ou totale en insuline ou d&#x27;une difficulté d&#x27;action de l&#x27;insuline.<\/p><p>La glycémie normale est comprise entre 0,7 et 1 g/l. Le seuil rénal du glucose est de 1,8 g/l. Toute personne ayant une glycémie ≥ 1,26 g/l au moins à 2 reprises est considérée comme diabétique.<\/p><p>Le diabète est donc dû soit à :<\/p><ul><li>un déficit absolu de la sécrétion d&#x27;insuline : c&#x27;est le diabète de type 1 ;<\/li><li>un déficit relatif de la sécrétion de l&#x27;insuline associé à un défaut d&#x27;action de cette hormone : c&#x27;est le diabète de type 2. Plus fréquent et d&#x27;évolution insidieuse, il pose le véritable problème de santé publique.<\/li><\/ul><p>Ces deux situations physiologiques sont responsables de la survenue d&#x27;une hyperglycémie chronique.<\/p><p>Par ailleurs, il existe deux autres types de diabètes :<\/p><p>Le diabète de type 3, qui est un diabète dû à une cause objective (une maladie, un traitement, etc.), identifiable et curable. Le diabète de type 4, appelé diabète gestationnel, lequel survient chez la femme enceinte et disparaît après l&#x27;accouchement.<\/p><div class=\"pgm\">p. 18<\/div><h4>Physiopathogénèse<\/h4><p>(Tableau comparatif diabète de type 1 / diabète de type 2)<\/p><ul><li>Cause — type 1 : affection du pancréas endocrine. Les îlots de Langerhans ne sécrètent plus d&#x27;insuline (insulinopénie), qui est indispensable à l&#x27;absorption du glucose par les cellules de l&#x27;organisme. Destruction des îlots du pancréas qui s&#x27;aggrave dans le temps : insulinopénie de plus en plus marquée.<\/li><li>Cause — type 2 : insulino-résistance. La sensibilité des tissus à l&#x27;insuline est diminuée. Le pancréas n&#x27;arrive pas à suivre la demande, il s&#x27;épuise peu à peu. Le pancréas augmente sa sécrétion d&#x27;insuline ⇒ la glycémie reste normale un certain temps ; épuisement du pancréas ; survient une intolérance au glucose (réversible) ; évolution vers l&#x27;insulino-nécessitant.<\/li><li>Origine — type 1 : auto-immune (prédisposition génétique), virale, trauma du pancréas… — type 2 : obésité, hérédité…<\/li><li>Début et découverte — type 1 : brutal ; asthénie ; syndrome polyuro-polydipsique (cardinal) ; amaigrissement ; survenue de complication : acidocétose. Jeunes &lt; 30 ans (mais diabète de type 1 lent possible). — type 2 : insidieux ; fortuite ou à l&#x27;occasion de complications (infarctus, infections…) ; obésité ; maturité (mais de plus en plus de jeunes car l&#x27;obésité augmente).<\/li><li>Épidémiologie — type 1 : moins fréquent, 20 % des cas ; sujet jeune ++ — type 2 : plus fréquent ; problème de santé publique majeur.<\/li><\/ul><p>Les travaux actuels sont orientés dans :<\/p><ul><li>L&#x27;identification des sujets à très haut risque de développer la maladie dans une perspective thérapeutique de prévention<\/li><\/ul><div class=\"pgm\">p. 19<\/div><ul><li>La recherche de moyens et techniques de dépistage précoce des complications afin d&#x27;en ralentir l&#x27;évolution<\/li><li>Le développement de nouveaux modes d&#x27;administration de l&#x27;insuline<\/li><\/ul><h4>Diagnostic<\/h4><h4>Signes d&#x27;orientation<\/h4><p>Des situations cliniques particulières doivent faire rechercher la présence d&#x27;un diabète chez tout patient :<\/p><ul><li>Furoncles à répétition<\/li><li>Lésion cutanée flamboyante<\/li><li>Prurit vaginal récurrent chez la femme<\/li><li>Macrosomie<\/li><li>Infertilité<\/li><li>Avortement spontané à répétition<\/li><li>Mort in utero<\/li><li>Malformation fœtale<\/li><li>Amaigrissement inexpliqué, surtout chez le gériatre<\/li><li>Énurésie persistante chez le grand enfant<\/li><li>Devant une cataracte, un glaucome ou une baisse brutale de la vision<\/li><li>Dysfonctionnement érectile chez un adulte jeune<\/li><li>Etc.<\/li><\/ul><h4>Signes cardinaux<\/h4><ul><li>Une polydipsie<\/li><li>Une polyurie (diurèse &gt; 4 L/24 h)<\/li><li>Une polyphagie<\/li><li>Un amaigrissement malgré un appétit conservé<\/li><\/ul><p>Ces signes imposent la recherche de glucose et de corps cétoniques dans les urines par bandelettes réactives, ainsi que la recherche d&#x27;une hyperglycémie. En effet, le diagnostic du diabète reste d&#x27;abord un diagnostic biologique.<\/p><p>Trois méthodes existent en pratique courante mais une seule méthode diagnostique suffit. Ce sont :<\/p><div class=\"pgm\">p. 20<\/div><ul><li>Glycémie à jeun (au moins 08 heures) ≥ 1,26 g/l (à 2 reprises)<\/li><li>Glycémie post-prandiale ou glycémie aléatoire ≥ 2 g/l (à 2 reprises)<\/li><li>Glycémie à jeun entre 1,10 et 1,26 g/l : HbA1c (≥ 6,5 %)<\/li><\/ul><h4>Évolution<\/h4><p>Sans une prise en charge adéquate, le diabète va évoluer vers des complications. Il existe deux groupes de complications : complications aiguës et complications chroniques ou dégénératives.<\/p><h4>Complications aiguës<\/h4><p>Elles se déclinent en 02 groupes : les complications métaboliques et les complications infectieuses.<\/p><h4>Complications métaboliques<\/h4><ul><li>Acidocétose<\/li><li>Acidose lactique<\/li><li>Hypoglycémie<\/li><li>Etc.<\/li><\/ul><h4>Complications infectieuses<\/h4><p>Il peut s&#x27;agir d&#x27;une infection de sévérité et de localisation variables. Exemple :<\/p><ul><li>Une pneumopathie<\/li><li>Une fasciite nécrosante<\/li><li>Etc.<\/li><\/ul><h4>Complications chroniques ou dégénératives<\/h4><p>On distingue à ce niveau 02 groupes de complications.<\/p><h4>Complications macrovasculaires<\/h4><ul><li>AVC<\/li><li>AOMI<\/li><li>IDM<\/li><\/ul><h4>Complications microvasculaires<\/h4><ul><li>Rétinopathie diabétique<\/li><li>Néphropathie diabétique<\/li><li>Neuropathie diabétique<\/li><\/ul><div class=\"pgm\">p. 21<\/div><h4>Stratégie globale de lutte contre le diabète<\/h4><p>Un triptyque basique et essentiel guide la stratégie globale de la lutte contre le diabète, à savoir :<\/p><ul><li>1. La lutte contre la survenue du diabète. Pour ce faire, les séances de dépistage couplées à des activités de sensibilisation sont organisées.<\/li><li>2. La lutte contre la survenue des complications du diabète chez les sujets atteints. Celle-ci fait appel à la conduite du traitement et au suivi des patients.<\/li><li>3. L&#x27;organisation de l&#x27;éducation thérapeutique individuelle ou collective.<\/li><\/ul><h4>La lutte contre la survenue du diabète<\/h4><p>Le dépistage systématique reste de mise en cas de :<\/p><ul><li>Obésité abdominale<\/li><li>Traitements potentiellement diabétogènes : corticothérapie, contraceptifs et autres<\/li><li>Existence de facteurs de risque : ATCD d&#x27;HTA, ATCD d&#x27;hyperglycémie transitoire, ATCD familiaux d&#x27;obésité, de diabète, ATCD de macrosomie, etc.<\/li><\/ul><p>La sensibilisation de la population sur les mesures de prévention du diabète et autres maladies non transmissibles. Il s&#x27;agit, entre autres contenus du message, de :<\/p><ul><li>Encourager une alimentation saine et équilibrée<\/li><li>Encourager la pratique d&#x27;une activité physique, c&#x27;est-à-dire lutter contre la sédentarité<\/li><\/ul><h4>La lutte contre la survenue de complications du diabète<\/h4><p>Il s&#x27;agit de conduire une prise en charge efficiente du patient diabétique. Les fondements de celle-ci sont :<\/p><ul><li>Traiter précocement<\/li><li>Chercher les molécules efficaces<\/li><li>Associer tôt les médicaments<\/li><\/ul><h4>L&#x27;organisation de l&#x27;éducation thérapeutique<\/h4><div class=\"pgm\">p. 22<\/div><p>Les sujets à aborder lors des séances d&#x27;éducation thérapeutique peuvent être les suivants :<\/p><ul><li>Alimentation<\/li><li>Activités physiques<\/li><li>Soins des pieds<\/li><li>Prise de médicaments<\/li><li>Hypoglycémie<\/li><\/ul><h4>Moyens thérapeutiques du traitement du diabète<\/h4><p>Les objectifs poursuivis dans la prise en charge du patient sont :<\/p><ul><li>Normaliser la glycémie<\/li><li>Rechercher les éventuelles complications et les prendre en charge<\/li><li>Réduire les facteurs de risque cardio-vasculaires<\/li><\/ul><p>Les moyens utilisés pour atteindre ces objectifs sont :<\/p><h4>Le régime alimentaire<\/h4><p>Quels aliments choisir ?<\/p><ul><li>Suppression de la consommation des sucres rapides<\/li><li>Réduction des sucres complexes<\/li><li>Éviction de la consommation de graisses animales<\/li><li>Consommation de fibres alimentaires solubles (légumineuses)<\/li><li>Utilisation préférentielle d&#x27;huiles végétales<\/li><li>Rapport graisses saturées / mono-insaturées / poly-insaturées de 1/1/1<\/li><\/ul><div class=\"pgm\">p. 23<\/div><ul><li>Suppression de la cigarette<\/li><li>Réduction de la consommation de l&#x27;alcool<\/li><\/ul><p>Comment confectionner et prendre les aliments ?<\/p><p>Éviter autant que possible (au maximum 1 fois/semaine) :<\/p><ul><li>Les fritures et les sauces grasses<\/li><\/ul><p>Consommer autant que possible (tous les jours) :<\/p><ul><li>Repas au four<\/li><li>Repas à la poêle<\/li><li>Sauces sans huile<\/li><li>Les braisés<\/li><\/ul><h4>L&#x27;activité physique<\/h4><p>Intérêts de l&#x27;activité physique :<\/p><ul><li>Participe à l&#x27;assimilation des glucides, donc potentialise le régime<\/li><li>Participe à la lutte contre les facteurs de risque vasculaire, donc améliore le pronostic vital<\/li><li>Maintient la masse maigre, donc améliore la qualité de vie<\/li><li>Participe au renforcement du système immunitaire, donc améliore la défense contre les maladies<\/li><\/ul><p>Quelle activité physique et comment la conduire ?<\/p><ul><li>La pratique de l&#x27;activité doit être régulière, modérée et fréquente<\/li><li>Le type et la durée sont fonction de l&#x27;âge<\/li><li>L&#x27;adaptation doit être progressive<\/li><\/ul><div class=\"pgm\">p. 24<\/div><ul><li>Tenir compte des éventuelles complications<\/li><li>Tenir compte des goûts et de l&#x27;environnement<\/li><li>Tenir compte de l&#x27;équilibre glycémique<\/li><\/ul><p>La durée minimale attendue est d&#x27;au moins 30 minutes par jour. Elle peut revêtir plusieurs formes :<\/p><ul><li>La marche rapide<\/li><li>Le ménage<\/li><li>Le jardinage<\/li><li>La danse<\/li><li>La gymnastique au sol<\/li><\/ul><h4>Les médicaments antidiabétiques<\/h4><p>Selon le mode d&#x27;action, on distingue :<\/p><ul><li>Médicaments qui retardent la digestion des glucides complexes : inhibiteurs des α-glucosidases (acarbose, miglitol…)<\/li><li>Médicaments qui diminuent la réabsorption rénale de glucose : inhibiteurs du SGLT2 (dapagliflozine…)<\/li><li>Médicaments qui stimulent la sécrétion de l&#x27;insuline : sulfamides (glimépiride…) ; glinides (répaglinide…) ; incrétinomimétiques (iDPP4 et GLP1)<\/li><li>Médicaments qui luttent contre l&#x27;insulinorésistance : biguanides (metformine…) ; glitazones (rosiglitazone…)<\/li><\/ul><h4>Insuline<\/h4><ul><li>Rapide : insulines humaines (Actrapid) ; insulines ultra-rapides (analogues rapides) : asparte (Novorapid) et glulisine (Apidra)<\/li><li>Lente : insuline humaine : insuline zinc (Ultratard) ; insuline lente (Insulatard) ; analogues synthétiques : insuline glargine (Lantus)<\/li><li>Intermédiaire : insuline NPH (Neutral Protamine Hagedorn)<\/li><li>Mixte : rapide (30 %) + NPH (70 %) (Mixtard 30, Insuman mix 30)<\/li><\/ul>","<div class=\"pgm\">p. 25<\/div><h4>Acidocétose diabétique<\/h4><h4>a) Modes d&#x27;apparition<\/h4><p>Survient le plus souvent chez des diabétiques de type 1 connus :<\/p><p>au cours d&#x27;infections sévères (50 %), de stress (infarctus, traumatismes), d&#x27;une corticothérapie, d&#x27;un arrêt de l&#x27;insulinothérapie soit accidentel (pompe sous-cutanée) soit volontaire. Par ailleurs, une autosurveillance défectueuse est fréquemment retrouvée. Parfois révélatrice d&#x27;un diabète (30 % des cas).<\/p><h4>b) Tableaux cliniques<\/h4><p>Au début, cétose sans acidose.<\/p><p>Dans le cas d&#x27;un diabète connu, l&#x27;importance du tableau polyuro-polydipsique, de l&#x27;asthénie et la découverte d&#x27;une forte glycosurie et d&#x27;une forte cétonurie doivent motiver le malade à pratiquer sans attendre des injections supplémentaires d&#x27;insuline rapide.<\/p><p>En l&#x27;absence de traitement, surviennent de façon progressive :<\/p><ul><li>une dyspnée de Kussmaul<\/li><li>des troubles de conscience<\/li><li>une déshydratation extracellulaire avec collapsus cardio-vasculaire<\/li><li>des vomissements<\/li><li>des douleurs abdominales<\/li><li>une odeur cétonique de l&#x27;haleine<\/li><\/ul><p>L&#x27;évolution non traitée se fait vers un coma profond.<\/p><h4>c) Le tableau biologique est constitué :<\/h4><ul><li>d&#x27;une hyperglycémie franche<\/li><li>d&#x27;une acidose métabolique, avec<\/li><li>intense hypocapnie et cétonémie importante<\/li><li>d&#x27;une kaliémie normale ou élevée, mais la déplétion potassique est constante.<\/li><\/ul><p>La natrémie est variable en fonction de l&#x27;importance des pertes hydrosodées. Il existe parfois une hyponatrémie factice, conséquence d&#x27;une forte hypertriglycéridémie. Une recherche bactériologique (hémocultures, CBU) doit être réalisée.<\/p><h4>d) L&#x27;évolution<\/h4><p>Habituellement, elle est favorable avec une prise en charge correcte :<\/p><div class=\"pgm\">p. 26<\/div><ul><li>Réhydratation avec du SSI (= sérum physiologique)<\/li><li>Insulinothérapie intensive<\/li><li>Correction de l&#x27;acidose<\/li><li>Correction des déplétions sodée et potassique<\/li><li>Traitement du facteur déclenchant<\/li><li>Prévention des complications de décubitus<\/li><\/ul><p>Parfois compliquée :<\/p><ul><li>Collapsus par déshydratation et acidose intenses<\/li><li>Hypoglycémies<\/li><li>Œdème cérébral favorisé par l&#x27;excès d&#x27;apports liquidiens hypotoniques ou la réduction trop rapide de l&#x27;hyperglycémie<\/li><li>Accidents thromboemboliques<\/li><\/ul><p>NB : la prise en charge du coma se fera dans un service de référence.<\/p><h4>Hypoglycémie<\/h4><p>Les causes des malaises hypoglycémiques sont :<\/p><ul><li>Parfois la rançon d&#x27;une recherche trop soigneuse de l&#x27;équilibre glycémique<\/li><li>Correspondent habituellement à des glycémies inférieures à 0,7 g/l<\/li><li>Peuvent s&#x27;observer cliniquement chez un diabétique déséquilibré lors du retour brutal en normoglycémie<\/li><\/ul><p>Au cours d&#x27;un déséquilibre de la balance glucides-insuline-exercice physique avec :<\/p><ul><li>Ration glucidique trop faible (omission d&#x27;une collation, repas pris avec retard)<\/li><li>Insuline résorbée trop importante (excès de dose, lipodystrophies, anticorps anti-insuline)<\/li><li>Exercice physique trop important ou imprévu<\/li><\/ul><p>Au cours de la prise d&#x27;alcool, de médicaments comme les β-bloquants ou les salicylés.<\/p><p>On distingue plusieurs stades :<\/p><h4>L&#x27;hypoglycémie modérée<\/h4><ul><li>Pâleur<\/li><li>Tremblements<\/li><\/ul>","<div class=\"pgm\">p. 26<\/div><ul><li>Réhydratation avec du SSI (= sérum physiologique)<\/li><li>Insulinothérapie intensive<\/li><li>Correction de l&#x27;acidose<\/li><li>Correction des déplétions sodée et potassique<\/li><li>Traitement du facteur déclenchant<\/li><li>Prévention des complications de décubitus<\/li><\/ul><p>Parfois compliquée :<\/p><ul><li>Collapsus par déshydratation et acidose intenses<\/li><li>Hypoglycémies<\/li><li>Œdème cérébral favorisé par l&#x27;excès d&#x27;apports liquidiens hypotoniques ou la réduction trop rapide de l&#x27;hyperglycémie<\/li><li>Accidents thromboemboliques<\/li><\/ul><p>NB : la prise en charge du coma se fera dans un service de référence.<\/p><h4>Hypoglycémie<\/h4><p>Les causes des malaises hypoglycémiques sont :<\/p><ul><li>Parfois la rançon d&#x27;une recherche trop soigneuse de l&#x27;équilibre glycémique<\/li><li>Correspondent habituellement à des glycémies inférieures à 0,7 g/l<\/li><li>Peuvent s&#x27;observer cliniquement chez un diabétique déséquilibré lors du retour brutal en normoglycémie<\/li><\/ul><p>Au cours d&#x27;un déséquilibre de la balance glucides-insuline-exercice physique avec :<\/p><ul><li>Ration glucidique trop faible (omission d&#x27;une collation, repas pris avec retard)<\/li><li>Insuline résorbée trop importante (excès de dose, lipodystrophies, anticorps anti-insuline)<\/li><li>Exercice physique trop important ou imprévu<\/li><\/ul><p>Au cours de la prise d&#x27;alcool, de médicaments comme les β-bloquants ou les salicylés.<\/p><p>On distingue plusieurs stades :<\/p><h4>L&#x27;hypoglycémie modérée<\/h4><ul><li>Pâleur<\/li><li>Tremblements<\/li><\/ul><div class=\"pgm\">p. 27<\/div><ul><li>Palpitations<\/li><li>Faim intense<\/li><li>Sueurs<\/li><\/ul><p>Ces signes diminuent avec l&#x27;ancienneté du diabète et certains signes sont moins perceptibles par le patient, avec :<\/p><ul><li>Diplopie<\/li><li>Troubles de l&#x27;élocution<\/li><li>Difficultés à se concentrer<\/li><li>Agressivité<\/li><li>Attitudes bizarres<\/li><\/ul><h4>L&#x27;hypoglycémie sévère et le coma<\/h4><p>Fréquente, nécessitant une aide extérieure et parfois compliquée :<\/p><ul><li>Ischémie myocardique, accident vasculaire cérébral<\/li><li>Crises comitiales<\/li><li>Chute avec fractures, accidents de la circulation<\/li><li>Évolution en l&#x27;absence de traitement vers le coma<\/li><li>Risque de mort subite<\/li><\/ul><p>Le traitement s&#x27;impose rapidement dans tous les cas :<\/p><ul><li>Prise de morceaux de sucre<\/li><li>Voire glucagon intra-nasal en cas de malades conscients<\/li><li>1 mg de glucagon IM<\/li><li>Glucosé hypertonique par voie IV en cas de malades inconscients<\/li><li>Collation glucidique doit être prise après le retour de la conscience, afin d&#x27;éviter une récidive<\/li><\/ul><h4>Affections de la thyroïde<\/h4><h4>Hyperthyroïdies<\/h4><h4>Définition<\/h4><p>Hyperproduction de T3 et T4 par la glande thyroïde.<\/p><p>Syndrome clinique = thyrotoxicose (accélération du métabolisme).<\/p>","<div class=\"pgm\">p. 27<\/div><ul><li>Palpitations<\/li><li>Faim intense<\/li><li>Sueurs<\/li><\/ul><p>Ces signes diminuent avec l&#x27;ancienneté du diabète et certains signes sont moins perceptibles par le patient, avec :<\/p><ul><li>Diplopie<\/li><li>Troubles de l&#x27;élocution<\/li><li>Difficultés à se concentrer<\/li><li>Agressivité<\/li><li>Attitudes bizarres<\/li><\/ul><h4>L&#x27;hypoglycémie sévère et le coma<\/h4><p>Fréquente, nécessitant une aide extérieure et parfois compliquée :<\/p><ul><li>Ischémie myocardique, accident vasculaire cérébral<\/li><li>Crises comitiales<\/li><li>Chute avec fractures, accidents de la circulation<\/li><li>Évolution en l&#x27;absence de traitement vers le coma<\/li><li>Risque de mort subite<\/li><\/ul><p>Le traitement s&#x27;impose rapidement dans tous les cas :<\/p><ul><li>Prise de morceaux de sucre<\/li><li>Voire glucagon intra-nasal en cas de malades conscients<\/li><li>1 mg de glucagon IM<\/li><li>Glucosé hypertonique par voie IV en cas de malades inconscients<\/li><li>Collation glucidique doit être prise après le retour de la conscience, afin d&#x27;éviter une récidive<\/li><\/ul><h4>Affections de la thyroïde<\/h4><h4>Hyperthyroïdies<\/h4><h4>Définition<\/h4><p>Hyperproduction de T3 et T4 par la glande thyroïde.<\/p><p>Syndrome clinique = thyrotoxicose (accélération du métabolisme).<\/p><div class=\"pgm\">p. 28<\/div><h4>Signes cliniques<\/h4><ul><li>1. Signes généraux : asthénie, amaigrissement, appétit augmenté, hyperthermie modérée, soif, sueurs profuses et thermophobie<\/li><li>2. Troubles cardiaques : tachycardie, troubles du rythme (tachyarythmie, palpitations) voire insuffisance cardiaque<\/li><li>3. Troubles musculaires : fatigabilité à l&#x27;effort, fonte musculaire<\/li><li>4. Troubles digestifs : diarrhées motrices<\/li><li>5. Troubles neuropsychiatriques : tremblements, irritabilité, hyperexcitabilité, nervosité, insomnie parfois, confusion<\/li><\/ul><h4>Étiologie des hyperthyroïdies<\/h4><ul><li>Maladie de Basedow : la plus fréquente cause<\/li><li>Adénome toxique de la thyroïde<\/li><li>Tumeur bénigne sécrétant en excès des hormones thyroïdiennes<\/li><li>Goitre multinodulaire toxique<\/li><li>Surcharge iodée : 5 à 6 % des causes<\/li><li>Iatrogène : soit médicaments (Cordarone +++), soit examens Rx<\/li><li>Causes rares<\/li><\/ul><h4>Diagnostic<\/h4><h4>Cas de la maladie de Basedow<\/h4><ul><li>T3 libre et T4 libre élevées avec<\/li><li>TSH très basse (même sous stimulation par TRH)<\/li><li>Biologie standard : thrombopénie, leucopénie et neutropénie, hyperglycémie, hypocholestérolémie<\/li><\/ul><p>Autres examens :<\/p><div class=\"pgm\">p. 29<\/div><ul><li>Scintigraphie à l&#x27;iode ou au technétium (rarement utilisée) : on note une répartition homogène<\/li><li>Échographie : on note une glande homogène<\/li><\/ul><h4>Traitement<\/h4><h4>Traitement médical spécifique<\/h4><p>= Apport d&#x27;antithyroïdiens de synthèse = Néomercazole®, Basdène®, PTU®, pendant au moins 18 mois pour la maladie de Basedow.<\/p><p>Surveillance : NFS — recherche une agranulocytose ; se fait au début du TTT puis en cas de fièvre.<\/p><h4>Traitement médical symptomatique<\/h4><ul><li>Bêtabloquant<\/li><li>Sédatifs<\/li><li>Corticoïdes<\/li><\/ul><h4>Hypothyroïdies<\/h4><h4>Définition<\/h4><p>Pathologie thyroïdienne la plus fréquente<\/p><p>= Dérèglement de la thyroïde qui fonctionne au ralenti (baisse de T3 et T4 libres) :<\/p><ul><li>Ralentissement du métabolisme<\/li><li>Infiltration cutanéo-muqueuse diffuse<\/li><li>Prédominance féminine<\/li><\/ul><h4>Éléments cliniques<\/h4><h4>Signes généraux<\/h4><ul><li>Asthénie<\/li><li>Prise de poids<\/li><li>Anorexie<\/li><li>Frilosité<\/li><\/ul><h4>Signes spécifiques<\/h4><ul><li>Infiltration cutanéo-muqueuse<\/li><li>Visage en pleine lune (rond, œdématié)<\/li><li>Faux œdème élastique et ferme<\/li><li>Chute des cheveux et dépilation (fins)<\/li><li>Peau sèche<\/li><li>Ongles secs et cassants<\/li><li>Raucité de la voix et ronflement<\/li><li>Surdité<\/li><\/ul>","<div class=\"pgm\">p. 29<\/div><ul><li>Scintigraphie à l&#x27;iode ou au technétium (rarement utilisée) : on note une répartition homogène<\/li><li>Échographie : on note une glande homogène<\/li><\/ul><h4>Traitement<\/h4><h4>Traitement médical spécifique<\/h4><p>= Apport d&#x27;antithyroïdiens de synthèse = Néomercazole®, Basdène®, PTU®, pendant au moins 18 mois pour la maladie de Basedow.<\/p><p>Surveillance : NFS — recherche une agranulocytose ; se fait au début du TTT puis en cas de fièvre.<\/p><h4>Traitement médical symptomatique<\/h4><ul><li>Bêtabloquant<\/li><li>Sédatifs<\/li><li>Corticoïdes<\/li><\/ul><h4>Hypothyroïdies<\/h4><h4>Définition<\/h4><p>Pathologie thyroïdienne la plus fréquente<\/p><p>= Dérèglement de la thyroïde qui fonctionne au ralenti (baisse de T3 et T4 libres) :<\/p><ul><li>Ralentissement du métabolisme<\/li><li>Infiltration cutanéo-muqueuse diffuse<\/li><li>Prédominance féminine<\/li><\/ul><h4>Éléments cliniques<\/h4><h4>Signes généraux<\/h4><ul><li>Asthénie<\/li><li>Prise de poids<\/li><li>Anorexie<\/li><li>Frilosité<\/li><\/ul><h4>Signes spécifiques<\/h4><ul><li>Infiltration cutanéo-muqueuse<\/li><li>Visage en pleine lune (rond, œdématié)<\/li><li>Faux œdème élastique et ferme<\/li><li>Chute des cheveux et dépilation (fins)<\/li><li>Peau sèche<\/li><li>Ongles secs et cassants<\/li><li>Raucité de la voix et ronflement<\/li><li>Surdité<\/li><\/ul><div class=\"pgm\">p. 30<\/div><h4>Autres manifestations<\/h4><ul><li>Troubles nerveux : gestes lents et malhabiles, somnolence, paresthésies<\/li><li>Troubles cardiaques : bradycardie, baisse du débit cardiaque, angor d&#x27;effort<\/li><li>Troubles digestifs : constipation<\/li><li>Troubles gynécologiques : aménorrhée ou infertilité<\/li><li>Troubles musculaires : muscles durs et douloureux, retard à la décontraction musculaire<\/li><\/ul><h4>Éléments paracliniques<\/h4><h4>Diagnostic biologique<\/h4><ul><li>T3 et T4 libres basses avec<\/li><li>TSH élevée<\/li><\/ul><p>(Sauf pour les rares hypothyroïdies d&#x27;origine centrale où la TSH est basse.)<\/p><h4>Diagnostic radiologique<\/h4><ul><li>Échographie (non indispensable)<\/li><li>Thyroïde atrophique ou hétérogène selon l&#x27;étiologie<\/li><li>Scintigraphie (totalement inutile)<\/li><\/ul><h4>Éléments étiologiques<\/h4><h4>Hypothyroïdie sans goitre<\/h4><ul><li>Atrophie thyroïdienne idiopathique<\/li><li>Post-traitement<\/li><li>Insuffisance thyréotrope (origine hypophysaire)<\/li><\/ul><h4>Hypothyroïdie avec goitre<\/h4><ul><li>Thyroïdite de Hashimoto<\/li><li>Iatrogène : ATS, médicaments iodés<\/li><li>Thyroïdite de De Quervain<\/li><li>Hypothyroïdie congénitale<\/li><\/ul><h4>Traitement<\/h4><p>Substitutif par voie orale : Lévothyrox (= T4L) 1,2 à 1,5 µg/kg/jour.<\/p><p>Début progressif si risque cardiaque (surtout personne âgée).<\/p><p>Adaptation sur la TSH (en cas d&#x27;origine périphérique = causes les plus fréquentes) ou sur la T4 libre (en cas d&#x27;origine centrale = causes rares).<\/p><h4>Affections des glandes surrénales<\/h4>","<div class=\"pgm\">p. 31<\/div><h4>Hypercorticisme<\/h4><p>= Hypersécrétion des glucocorticoïdes. On distingue :<\/p><ul><li>1. L&#x27;hypercorticisme d&#x27;origine primaire surrénalienne = hyperfonctionnement surrénalien : adénome de la surrénale ; cancer de la surrénale<\/li><li>2. L&#x27;hypercorticisme d&#x27;origine secondaire = hypersécrétion de l&#x27;ACTH, qui est la « maladie de Cushing »<\/li><\/ul><h4>Signes cliniques<\/h4><ul><li>Obésité facio-tronculaire<\/li><li>Diabète<\/li><li>Hypertension<\/li><li>Myopathie<\/li><li>Faiblesse musculaire<\/li><li>Vergetures pourpres<\/li><li>Agitation et irritabilité<\/li><li>Ostéoporose<\/li><\/ul><h4>Hypocorticisme<\/h4><ul><li>1. Insuffisance en glucocorticoïde<\/li><li>2. Insuffisance surrénalienne chronique = « maladie d&#x27;Addison »<\/li><\/ul><h4>Signes cliniques<\/h4><ul><li>Fatigabilité<\/li><li>Mélanodermie<\/li><li>Hypo TA<\/li><li>Hypoglycémie<\/li><li>Troubles digestifs : anorexie, diarrhées, vomissements<\/li><li>3. Insuffisance surrénalienne iatrogène : traitement par corticoïdes longue durée ; dysfonctionnement de l&#x27;axe hypothalamo-hypophysaire<\/li><\/ul>","<div class=\"pgm\">p. 32<\/div><h4>Insuffisance antéhypophysaire globale<\/h4><h4>Définition<\/h4><ul><li>C&#x27;est une mise en défaut de tout ou partie de l&#x27;antéhypophyse, d&#x27;origine hypophysaire ou supra-hypophysaire, primitive ou secondaire, entraînant un déficit sécrétoire périphérique<\/li><li>Révélation clinique très progressive<\/li><li>Pronostic lié à l&#x27;importance des déficits, à l&#x27;étiologie<\/li><\/ul><h4>Étude clinique<\/h4><h4>1. Aspect général évocateur<\/h4><ul><li>Faciès pâle, de teinte albâtre, avec un visage peu expressif et juvénile<\/li><li>Peau fine, atrophique, sèche<\/li><li>Hypopilosité du visage, des creux axillaires et des régions sexuelles<\/li><li>Cheveux fins, cassants<\/li><li>Aréoles des seins dépigmentées<\/li><li>Sujet adynamique, asthénique, indifférent, frileux<\/li><li>Chez l&#x27;homme, changement de la voix, faible, à tonalité féminine<\/li><\/ul><h4>2. Les autres signes endocriniens<\/h4><ul><li>Le déficit gonadotrope est précoce et constant, avec :<\/li><li>chez l&#x27;homme : impuissance, baisse de la libido, atrophie testiculaire<\/li><li>chez la femme : aménorrhée sans bouffées de chaleur, frigidité, sécheresse des muqueuses et atrophie des seins<\/li><li>Le déficit thyréotrope survient plus tardivement : pas de goitre ; sujet ralenti et frileux<\/li><li>Le déficit corticotrope s&#x27;accompagne : d&#x27;une asthénie et d&#x27;une hypotension orthostatique ; pas de mélanodermie ni d&#x27;amaigrissement ; pas de choc cardio-vasculaire du fait de l&#x27;intégrité du système rénine-angiotensine<\/li><li>Chez l&#x27;adulte, le déficit somatotrope, qui est fréquent, passe inaperçu<\/li><\/ul><div class=\"pgm\">p. 33<\/div><h4>3. Signes généraux<\/h4><ul><li>Anémie modérée<\/li><li>Hypoglycémie fréquente<\/li><\/ul><h4>4. L&#x27;évolution non traitée se fait vers :<\/h4><ul><li>La survenue d&#x27;hypoglycémies graves<\/li><li>L&#x27;insuffisance surrénale aiguë<\/li><li>Le coma (hypothermie, collapsus cardio-vasculaire)<\/li><\/ul><h4>Formes cliniques<\/h4><h4>1. Chez l&#x27;enfant<\/h4><ul><li>Nanisme hypophysaire de type harmonieux<\/li><li>Âge statural &lt; âge osseux &lt; âge réel (il est plus petit)<\/li><li>Cassure de la courbe de croissance dès 1 an<\/li><li>Fonctions supérieures habituellement normales<\/li><li>Diagnostic parfois plus tardif à l&#x27;adolescence devant un impubérisme<\/li><\/ul><h4>2. Chez le sujet âgé<\/h4><ul><li>Tableau neuropsychique, digestif ou musculaire<\/li><li>Hypoglycémies ou hyponatrémies rebelles aux rééquilibrations ioniques<\/li><\/ul><h4>Étude biologique<\/h4><p>Les signes biologiques concernent 4 niveaux différents :<\/p><ul><li>le secteur hypothalamique<\/li><li>le secteur hypophysaire<\/li><li>la glande périphérique<\/li><li>le retentissement sur les tissus cibles<\/li><\/ul><p>La biologie s&#x27;attachera à préciser trois critères communs :<\/p><ul><li>un déficit hormonal périphérique<\/li><li>l&#x27;intégrité de la glande périphérique, au cours de tests de stimulation<\/li><li>le déficit des hormones hypophysaires<\/li><\/ul><p>Une insuffisance centrale de siège hypophysaire s&#x27;accompagne en plus d&#x27;une non-réponse des hormones hypophysaires aux stimulations par les hormones hypothalamiques.<\/p><div class=\"pgm\">p. 34<\/div><h4>1. Le déficit gonadique<\/h4><p>Les hormones périphériques sont diminuées :<\/p><ul><li>Testostérone, testostérone libre abaissées<\/li><li>Estradiol, progestérone abaissées<\/li><li>LH, FSH diminuées<\/li><\/ul><h4>2. Le déficit thyroïdien<\/h4><ul><li>Diminution des hormones périphériques T3, T4<\/li><li>Baisse de la courbe de fixation de l&#x27;iode<\/li><li>TSH abaissée<\/li><\/ul><h4>3. Le déficit corticotrope<\/h4><ul><li>Cortisol, CLU abaissés<\/li><li>ACTH et βLPH sont basses<\/li><li>Le test de Thorn est normal<\/li><\/ul><h4>4. Secteur glucidique<\/h4><p>Défaillance du système contre-régulateur.<\/p><h4>Pathologies métaboliques liées aux hormones<\/h4><h4>Obésités<\/h4><h4>Quelle définition donner ?<\/h4><p>Il s&#x27;agit de la constellation de plusieurs anomalies cliniques et biologiques. C&#x27;est un déterminant essentiel du diabète et des maladies cardiovasculaires qui est induit par l&#x27;obésité abdominale ou viscérale. C&#x27;est une accumulation de tissu adipeux viscéral au point où certains auteurs parlent du « syndrome de la graisse viscérale ».<\/p><h4>Comment fait-on le diagnostic ?<\/h4><p>Tour de taille : homme &gt; 94 cm ; femme &gt; 80 cm, + 2 critères parmi les suivants :<\/p><ul><li>Hypertension existante ou sous traitement<\/li><li>Triglycérides &gt; 1,5 g/l ou sous traitement<\/li><li>Hyperglycémie ou diabète<\/li><li>HDL-cholestérol abaissé (homme &lt; 40 mg/dl, femme &lt; 50 mg/dl) ou sous traitement<\/li><\/ul>","<div class=\"pgm\">p. 34<\/div><h4>1. Le déficit gonadique<\/h4><p>Les hormones périphériques sont diminuées :<\/p><ul><li>Testostérone, testostérone libre abaissées<\/li><li>Estradiol, progestérone abaissées<\/li><li>LH, FSH diminuées<\/li><\/ul><h4>2. Le déficit thyroïdien<\/h4><ul><li>Diminution des hormones périphériques T3, T4<\/li><li>Baisse de la courbe de fixation de l&#x27;iode<\/li><li>TSH abaissée<\/li><\/ul><h4>3. Le déficit corticotrope<\/h4><ul><li>Cortisol, CLU abaissés<\/li><li>ACTH et βLPH sont basses<\/li><li>Le test de Thorn est normal<\/li><\/ul><h4>4. Secteur glucidique<\/h4><p>Défaillance du système contre-régulateur.<\/p><h4>Pathologies métaboliques liées aux hormones<\/h4><h4>Obésités<\/h4><h4>Quelle définition donner ?<\/h4><p>Il s&#x27;agit de la constellation de plusieurs anomalies cliniques et biologiques. C&#x27;est un déterminant essentiel du diabète et des maladies cardiovasculaires qui est induit par l&#x27;obésité abdominale ou viscérale. C&#x27;est une accumulation de tissu adipeux viscéral au point où certains auteurs parlent du « syndrome de la graisse viscérale ».<\/p><h4>Comment fait-on le diagnostic ?<\/h4><p>Tour de taille : homme &gt; 94 cm ; femme &gt; 80 cm, + 2 critères parmi les suivants :<\/p><ul><li>Hypertension existante ou sous traitement<\/li><li>Triglycérides &gt; 1,5 g/l ou sous traitement<\/li><li>Hyperglycémie ou diabète<\/li><li>HDL-cholestérol abaissé (homme &lt; 40 mg/dl, femme &lt; 50 mg/dl) ou sous traitement<\/li><\/ul><div class=\"pgm\">p. 35<\/div><h4>Quelle en est la réalité épidémiologique ?<\/h4><p>L&#x27;augmentation du niveau de vie engendre la dégradation de la qualité de vie.<\/p><p>En Côte d&#x27;Ivoire : selon la Fédération Internationale du Diabète (FID), la prévalence de l&#x27;obésité était de 23,55 % en 2005.<\/p><p>(Tableau des prévalences : J. Mc Knight, Écosse, 21 000 sujets, 79 % ; A. Sallé, Tunisie, 24 sujets, 100 % ; D. Kouassi, Côte d&#x27;Ivoire, 205 sujets, 0 % (définition OMS) ; A. Azoh, Côte d&#x27;Ivoire, 85 sujets, 23,35 % (FID 2005) ; A. Azoh, Côte d&#x27;Ivoire, 85 sujets, 8,24 % (NCEP ATP III).)<\/p><h4>Quelle est la physiopathogénie ?<\/h4><ul><li>Tout repose sur la survenue de la résistance à l&#x27;insuline, engendrée par l&#x27;apparition de la surcharge pondérale chez un sujet.<\/li><li>La surcharge pondérale, quant à elle, provient de facteurs génétiques et de facteurs environnementaux.<\/li><li>C&#x27;est donc l&#x27;insulino-résistance qui va être responsable de :<\/li><li>Stéatose puis cirrhose et plus tard CPF (cancer primitif du foie) au niveau du foie<\/li><li>Hypertension artérielle au niveau du cœur et de ses vaisseaux<\/li><li>Diabète au niveau du pancréas<\/li><li>SOPK (syndrome des ovaires polykystiques) au niveau des ovaires<\/li><\/ul><h4>Comment se fait la prise en charge ?<\/h4><p>La prise en charge du syndrome métabolique est multidisciplinaire. Elle fait appel à plusieurs spécialités, notamment :<\/p><ul><li>Endocrinologie<\/li><li>Gastro-entérologie<\/li><li>Diététique<\/li><li>Psychologie<\/li><li>Cardiologie<\/li><li>Chirurgie<\/li><li>Etc.<\/li><\/ul><div class=\"pgm\">p. 36<\/div><h4>Les moyens utilisés sont essentiellement<\/h4><ul><li>Le régime alimentaire<\/li><li>L&#x27;activité physique<\/li><li>Les médicaments<\/li><li>La chirurgie<\/li><\/ul><h4>La stratégie<\/h4><ul><li>La lutte contre la surcharge pondérale, grâce à : régime alimentaire ; activités physiques régulières<\/li><li>La lutte contre la résistance à l&#x27;insuline et le diabète par l&#x27;usage de : agents insulino-sensibilisants ; autres médicaments antidiabétiques<\/li><li>La lutte contre le stress oxydatif par l&#x27;utilisation de : agents hépatoprotecteurs ; agents antioxydants ; psychothérapie<\/li><\/ul><h4>Hypertension artérielle<\/h4><h4>Introduction<\/h4><p>L&#x27;hypertension artérielle est une « maladie silencieuse » qui peut entraîner de graves complications comme un infarctus ou un AVC. Néanmoins, beaucoup de personnes négligent de contrôler leur tension au point qu&#x27;on estime aujourd&#x27;hui qu&#x27;un Ivoirien sur trois est hypertendu mais que la moitié l&#x27;ignore !<\/p><p>Il existe deux groupes d&#x27;hypertension artérielle :<\/p><h4>L&#x27;HTA primaire ou essentielle<\/h4><p>Fréquente (95 %), sans cause évidente mais plurifactorielle (facteurs environnementaux et prédispositions congénitales), et qui suscite des difficultés thérapeutiques.<\/p><h4>L&#x27;HTA secondaire ou symptomatique<\/h4><p>Moins fréquente, dont la cause, à rechercher, existe, et qui guérit après traitement de cette cause :<\/p>","<div class=\"pgm\">p. 36<\/div><h4>Les moyens utilisés sont essentiellement<\/h4><ul><li>Le régime alimentaire<\/li><li>L&#x27;activité physique<\/li><li>Les médicaments<\/li><li>La chirurgie<\/li><\/ul><h4>La stratégie<\/h4><ul><li>La lutte contre la surcharge pondérale, grâce à : régime alimentaire ; activités physiques régulières<\/li><li>La lutte contre la résistance à l&#x27;insuline et le diabète par l&#x27;usage de : agents insulino-sensibilisants ; autres médicaments antidiabétiques<\/li><li>La lutte contre le stress oxydatif par l&#x27;utilisation de : agents hépatoprotecteurs ; agents antioxydants ; psychothérapie<\/li><\/ul><h4>Hypertension artérielle<\/h4><h4>Introduction<\/h4><p>L&#x27;hypertension artérielle est une « maladie silencieuse » qui peut entraîner de graves complications comme un infarctus ou un AVC. Néanmoins, beaucoup de personnes négligent de contrôler leur tension au point qu&#x27;on estime aujourd&#x27;hui qu&#x27;un Ivoirien sur trois est hypertendu mais que la moitié l&#x27;ignore !<\/p><p>Il existe deux groupes d&#x27;hypertension artérielle :<\/p><h4>L&#x27;HTA primaire ou essentielle<\/h4><p>Fréquente (95 %), sans cause évidente mais plurifactorielle (facteurs environnementaux et prédispositions congénitales), et qui suscite des difficultés thérapeutiques.<\/p><h4>L&#x27;HTA secondaire ou symptomatique<\/h4><p>Moins fréquente, dont la cause, à rechercher, existe, et qui guérit après traitement de cette cause :<\/p><div class=\"pgm\">p. 37<\/div><ul><li>Certaines maladies rénales ou endocriniennes : l&#x27;hyperthyroïdie, le diabète, la dyslipidémie…<\/li><li>Certains médicaments : les corticostéroïdes, la cyclosporine, des anabolisants<\/li><\/ul><p>La pression artérielle (PA) représente la force élastique appliquée sur le contenu sanguin par les parois artérielles. Un niveau minimal de pression est nécessaire pour que le sang circule dans tout l&#x27;organisme.<\/p><p>On parle d&#x27;hypertension artérielle quand cette pression est en permanence trop élevée. C&#x27;est un phénomène dangereux car il accélère la fatigue du cœur en augmentant le travail du muscle cardiaque, qui va donc grossir, devenir moins performant et s&#x27;épuiser.<\/p><p>La valeur normale de la pression artérielle chez un adulte est de 120/80 mm de mercure.<\/p><p>Cette pression est divisée en deux temps :<\/p><p>Le chiffre le plus élevé correspond à la pression artérielle systolique, c&#x27;est-à-dire la valeur de la pression artérielle au moment de la contraction ventriculaire. Le chiffre le plus faible représente la pression artérielle diastolique, soit la valeur de la pression artérielle au moment de la relaxation ventriculaire.<\/p><h4>Symptômes<\/h4><p>De manière générale, l&#x27;hypertension provoque peu de symptômes, mais certains peuvent tout de même donner l&#x27;alerte, notamment :<\/p><ul><li>Céphalées<\/li><li>Vertiges<\/li><li>Douleurs dans la poitrine<\/li><li>Essoufflements<\/li><li>Troubles visuels, fatigue…<\/li><\/ul><p>La valeur limite de la pression artérielle où l&#x27;on parle d&#x27;hypertension artérielle (ou HTA) est de 140/90 mmHg, ce qui signifie une PA systolique supérieure à 140 mmHg et une PA diastolique plus élevée que 90 mmHg.<\/p><div class=\"pgm\">p. 38<\/div><p>N.B. Cette valeur est réduite à 135/85 mmHg en cas d&#x27;auto-mesure.<\/p><p>Toutefois, une seule mesure ne reflète pas nécessairement la réalité car la pression artérielle varie dans une journée en fonction de différents facteurs comme le stress ou la fatigue. Pour poser un diagnostic d&#x27;HTA, il faut l&#x27;avoir prise au moins trois fois et avoir constaté les mêmes valeurs !<\/p><p>Par ailleurs, l&#x27;hypertension est divisée en trois catégories en fonction du stade ; une HTA peut être :<\/p><ul><li>Limitée : TA = (140 – 159) / (90 – 99) mmHg<\/li><li>Modérée : TA = (160 – 179) / (100 – 109) mmHg<\/li><li>Sévère : TA &gt; 180 / 110 mmHg<\/li><\/ul><h4>Facteurs favorisant les HTA primaires<\/h4><p>Dans la plupart des cas, l&#x27;hypertension primaire ou essentielle n&#x27;a pas une seule cause directe mais résulte d&#x27;une accumulation de plusieurs facteurs dont certains sur lesquels on ne peut agir, comme l&#x27;âge.<\/p><h4>Les facteurs favorisants non modifiables<\/h4><ul><li>L&#x27;âge : les artères ont tendance à se rigidifier sous l&#x27;effet du vieillissement. Aussi, avec l&#x27;âge, la pression artérielle aura tendance à s&#x27;élever.<\/li><li>Le sexe : les changements hormonaux sont des facteurs de risque avérés. Ainsi, les femmes peuvent plus facilement devenir hypertendues à trois occasions particulières : lors de la première prise de la pilule contraceptive (œstrogènes de synthèse), lors de la grossesse, ou encore à l&#x27;arrivée de la ménopause. Et plus d&#x27;une femme sur 2 ménopausée sera hypertendue.<\/li><li>Les gènes (hérédité) : avoir un de ses parents hypertendu augmente les risques de le devenir soi-même par deux.<\/li><\/ul><h4>Les facteurs favorisants modifiables<\/h4><ul><li>Certaines affections chroniques : l&#x27;obésité (surtout androïde) ou le surpoids ; le diabète<\/li><li>La prise au long cours de certains médicaments :<\/li><\/ul><div class=\"pgm\">p. 39<\/div><ul><li>AINS, corticoïdes, contraceptifs oraux<\/li><li>Les conditions socio-économiques et professionnelles : stress et anxiété<\/li><li>Certaines habitudes de vie : la consommation de tabac ; manger trop salé, gras (surtout animal), trop pauvre en potassium, en vitamine D ; la consommation excessive d&#x27;alcool ; la sédentarité<\/li><\/ul><p>De façon générale, c&#x27;est l&#x27;association de plusieurs facteurs qui multiplie le risque et qui provoque la maladie.<\/p><h4>Complications de la HTA<\/h4><p>L&#x27;hypertension altère les artères d&#x27;une manière qui peut être irréversible. Pour résister à la pression du sang, les artères se rigidifient et leurs parois s&#x27;épaississent. L&#x27;espace disponible pour laisser passer le flux sanguin se rétrécit. C&#x27;est d&#x27;autant plus grave que l&#x27;hypertension favorise parallèlement le développement de plaques d&#x27;athéromes (dépôts graisseux qui rétrécissent encore cet espace). Lorsqu&#x27;une plaque d&#x27;athérome se détache, l&#x27;artère peut se boucher et provoquer un accident cardio-vasculaire.<\/p><p>En effet, lorsqu&#x27;une artère se bouche complètement, c&#x27;est l&#x27;infarctus ! S&#x27;il s&#x27;agit d&#x27;une artère cérébrale, c&#x27;est un AVC. Il est estimé que 40 % des AVC seraient directement liés à une hypertension.<\/p><p>La situation est semblable dans les membres inférieurs : le rétrécissement des vaisseaux dans les jambes limite la distance de marche. On parle d&#x27;artériopathie oblitérante des membres inférieurs (AOMI). Si ceux-ci se bouchent, les douleurs dans les jambes peuvent devenir permanentes et il y a un risque d&#x27;amputation.<\/p><p>De même pour l&#x27;insuffisance cardiaque : le cœur travaille davantage pour envoyer le sang dans toutes les artères du corps quand on est hypertendu. Au bout d&#x27;un certain temps, il devient moins performant et se dilate. Par ailleurs, comme le cœur travaille plus, ses besoins en oxygène augmentent. Du coup, il n&#x27;est pas suffisamment irrigué ; cela peut provoquer des douleurs dues à un essoufflement d&#x27;effort, au repos, et à une angine de poitrine.<\/p><p>Une dissection aortique est également possible car l&#x27;enveloppe de l&#x27;aorte fragilisée par la pression peut se déchirer brutalement.<\/p><div class=\"pgm\">p. 40<\/div><p>Depuis plusieurs années, un lien a été établi entre l&#x27;hypertension et la survenue de démences. Apparemment, lorsqu&#x27;elle est négligée, l&#x27;hypertension engendre des lésions dans les petits vaisseaux qui irriguent le cerveau. Ceci peut aboutir à une perte progressive de la mémoire et favoriser par conséquent le développement de démences comme la maladie d&#x27;Alzheimer.<\/p><p>Enfin, l&#x27;insuffisance rénale et les lésions oculaires sont d&#x27;autres conséquences possibles sur le long terme.<\/p><h4>Diagnostic de la HTA<\/h4><p>Le diagnostic d&#x27;HTA consiste en la mise en évidence de valeurs pathologiques et l&#x27;exploration d&#x27;une possible origine secondaire de l&#x27;HTA.<\/p><p>Mais la prise en charge s&#x27;élargit avec l&#x27;évaluation du risque cardiovasculaire global et l&#x27;état des organes cibles. Compte tenu de la variabilité des valeurs de la pression artérielle, le diagnostic d&#x27;HTA doit être basé sur de multiples mesures, obtenues lors d&#x27;occasions séparées sur plusieurs semaines.<\/p><p>Il est préférable que :<\/p><ul><li>La prise ait lieu après 10 minutes de repos<\/li><li>En position assise<\/li><li>Il est nécessaire de procéder à la mesure aux deux bras (symétrie des valeurs) en considérant la valeur la plus haute<\/li><li>Il faut prêter attention à ce que le brassard soit adapté à la circonférence du bras (&gt; 32 cm = grosse manchette) et à la calibration régulière de l&#x27;appareil<\/li><li>Il est recommandé de prendre trois mesures avec une précision de 2 mmHg et de noter la moyenne des deux dernières valeurs<\/li><\/ul><p>Dans certaines indications, il est aussi préconisé de recourir à une MAPA, c&#x27;est-à-dire une « Mesure Ambulatoire de la Pression Artérielle », au moyen d&#x27;un tensiomètre porté par le patient pendant 24 à 48 heures, programmé pour prendre automatiquement la pression artérielle toutes les quinze à vingt minutes la journée et toutes les trente à soixante minutes pendant le sommeil. On y a recours notamment lorsque l&#x27;on constate une importante variabilité tensionnelle, ou des symptômes laissant suspecter une hypotension chez des patients prenant un traitement antihypertenseur. Cet examen peut aussi être effectué lorsque l&#x27;on suspecte un syndrome d&#x27;apnée du sommeil ou une hypertension de la blouse blanche.<\/p><p>Des examens complémentaires sont demandés, notamment :<\/p><div class=\"pgm\">p. 41<\/div><ul><li>Un ECG<\/li><li>Des analyses sanguines et d&#x27;urines : glycémie, créatininémie, cholestérol total, HDL-cholestérol, LDL-cholestérol, triglycérides, uricémie, ionogramme sanguin<\/li><\/ul><h4>Formes évolutives<\/h4><h4>Crise hypertensive<\/h4><ul><li>Augmentation des chiffres de la PA<\/li><li>Existence d&#x27;un contexte psychologique<\/li><li>Se réduit d&#x27;elle-même<\/li><\/ul><h4>Poussée hypertensive<\/h4><ul><li>Augmentation brutale des chiffres de la PA<\/li><li>Céphalées<\/li><li>Pas d&#x27;atteinte viscérale<\/li><\/ul><h4>Urgences hypertensives<\/h4><p>Augmentation brutale des chiffres de la PA :<\/p><ul><li>Céphalées<\/li><li>Atteinte viscérale<\/li><\/ul><p>L&#x27;absence d&#x27;une prise en charge rapide et adéquate engage le pronostic vital.<\/p><h4>Une fausse urgence hypertensive<\/h4><ul><li>Élévation brutale de la pression artérielle<\/li><li>Isolée<\/li><li>Sans souffrance d&#x27;organe<\/li><li>Sans lésion ischémique ni hémorragique cérébrale<\/li><\/ul><div class=\"pgm\">p. 42<\/div><h4>Prise en charge et traitements<\/h4><p>Le traitement de l&#x27;hypertension repose sur 8 « familles » de médicaments, dont les mécanismes d&#x27;action ne sont pas les mêmes et peuvent être complémentaires.<\/p><p>Chaque cas est différent et ne ressemble pas à un autre. Le médecin devra peut-être essayer plusieurs médicaments avant de trouver le traitement qui convient le mieux au patient, autant en termes d&#x27;efficacité que de tolérance.<\/p><p>Il est parfois nécessaire d&#x27;associer deux, voire trois médicaments de familles différentes pour contrôler la pression artérielle. C&#x27;est d&#x27;ailleurs le cas de plus de la moitié des personnes hypertendues.<\/p><h4>Les médicaments employés contre l&#x27;hypertension sont :<\/h4><h4>Les antagonistes des récepteurs de l&#x27;angiotensine<\/h4><p>Ils agissent contre une substance très active qui provoque la contraction des artères et l&#x27;hypertension. Très peu d&#x27;effets indésirables sont observés via ces molécules.<\/p><h4>Les inhibiteurs de l&#x27;enzyme de conversion (IEC)<\/h4><p>Ils ont une action favorable sur les artères et sur le cœur et sont donc aussi utilisés pour soigner l&#x27;insuffisance cardiaque. Ils peuvent provoquer une toux qui disparaît dès l&#x27;arrêt du traitement.<\/p><h4>Les inhibiteurs de la rénine (IDR)<\/h4><p>Ils bloquent une substance sécrétée par le rein qui favorise la contraction des artères.<\/p><h4>Les bêtabloquants<\/h4><p>Ils diminuent l&#x27;activité du système nerveux et réduisent la fréquence et la force des battements cardiaques.<\/p><h4>Les diurétiques thiazidiques et apparentés<\/h4><p>Ils agissent sur le rein et sont habituellement associés aux autres médicaments dont ils augmentent l&#x27;action.<\/p><h4>Les antagonistes calciques<\/h4><p>Ils assouplissent les artères et sont actifs dans l&#x27;angine de poitrine. Parmi les effets secondaires, on a les œdèmes des chevilles.<\/p><h4>Les antihypertenseurs centraux<\/h4><p>Ils ont un effet sur les fonctions cérébrales agissant sur le contrôle de la tension. Ils sont moins utilisés car ils ont plus d&#x27;effets indésirables que les autres médicaments. Ils ont une indication<\/p><div class=\"pgm\">p. 43<\/div><p>de troisième ou quatrième intention et s&#x27;utilisent en association avec les autres antihypertenseurs.<\/p><h4>Les alpha-bloquants<\/h4><p>Ils agissent directement sur les artères mais peuvent provoquer des baisses de tension en position debout.<\/p><p>Tous ces médicaments seront, dans la stratégie thérapeutique, associés de façon intelligente selon des schémas précis (schéma : bêtabloquant [aténolol, bisoprolol], ARA2 [losartan, valsartan], IEC [ramipril, périndopril], antagoniste calcique [amlodipine, nicardipine], diurétique thiazidique [HCT, indapamide]).<\/p><h4>Urgences hypertensives<\/h4><h4>La « fausse urgence hypertensive »<\/h4><ul><li>Une élévation de la pression artérielle isolée<\/li><li>Sans souffrance d&#x27;organe<\/li><li>Sans lésion ischémique ni hémorragique cérébrale<\/li><\/ul><h4>La « vraie urgence hypertensive »<\/h4><ul><li>Une élévation brutale de la pression artérielle avec<\/li><li>Atteinte viscérale aiguë ou progressive, où<\/li><li>L&#x27;absence de prise en charge urgente engage le pronostic vital<\/li><\/ul><h4>CAT de différents cas<\/h4><h4>Accident vasculaire cérébral (AVC)<\/h4><ul><li>PA élevée<\/li><li>Trouble de la conscience et/ou<\/li><li>Déficit moteur<\/li><\/ul>","<div class=\"pgm\">p. 43<\/div><p>de troisième ou quatrième intention et s&#x27;utilisent en association avec les autres antihypertenseurs.<\/p><h4>Les alpha-bloquants<\/h4><p>Ils agissent directement sur les artères mais peuvent provoquer des baisses de tension en position debout.<\/p><p>Tous ces médicaments seront, dans la stratégie thérapeutique, associés de façon intelligente selon des schémas précis (schéma : bêtabloquant [aténolol, bisoprolol], ARA2 [losartan, valsartan], IEC [ramipril, périndopril], antagoniste calcique [amlodipine, nicardipine], diurétique thiazidique [HCT, indapamide]).<\/p><h4>Urgences hypertensives<\/h4><h4>La « fausse urgence hypertensive »<\/h4><ul><li>Une élévation de la pression artérielle isolée<\/li><li>Sans souffrance d&#x27;organe<\/li><li>Sans lésion ischémique ni hémorragique cérébrale<\/li><\/ul><h4>La « vraie urgence hypertensive »<\/h4><ul><li>Une élévation brutale de la pression artérielle avec<\/li><li>Atteinte viscérale aiguë ou progressive, où<\/li><li>L&#x27;absence de prise en charge urgente engage le pronostic vital<\/li><\/ul><h4>CAT de différents cas<\/h4><h4>Accident vasculaire cérébral (AVC)<\/h4><ul><li>PA élevée<\/li><li>Trouble de la conscience et/ou<\/li><li>Déficit moteur<\/li><\/ul><div class=\"pgm\">p. 44<\/div><p>Conduite à tenir :<\/p><ul><li>Prendre une voie veineuse périphérique<\/li><li>Éviter de baisser les chiffres de la PA +++<\/li><li>Traitement symptomatique<\/li><li>Référer le patient<\/li><\/ul><h4>Œdème aigu du poumon (OAP)<\/h4><ul><li>PA élevée<\/li><li>Détresse respiratoire<\/li><\/ul><p>Conduite à tenir :<\/p><ul><li>Prendre une voie veineuse périphérique<\/li><li>Baisser les chiffres de la PA à &lt; 140/90 mmHg<\/li><li>Oxygénation si possible<\/li><li>Furosémide 40 mg/heure<\/li><li>Référer le patient sans attendre<\/li><\/ul><h4>Éclampsie<\/h4><ul><li>PA élevée<\/li><li>Grossesse<\/li><li>Trouble de la conscience<\/li><li>Convulsions<\/li><li>Protéinurie<\/li><\/ul><p>Conduite à tenir :<\/p><ul><li>Prendre une voie veineuse périphérique<\/li><li>Baisser les chiffres de la PA à &lt; 155/105 mmHg<\/li><li>Pas de CAPTOPRIL<\/li><li>Référer le patient sans attendre<\/li><\/ul>","<div class=\"pgm\">p. 46<\/div><h4>Généralités sur le cancer<\/h4><h4>I. Définition<\/h4><p>« Cancer » est un terme général désignant une maladie pour laquelle certaines cellules d&#x27;un organisme adoptent un comportement anormal caractérisé par :<\/p><ul><li>une indépendance vis-à-vis des signaux qui stimulent normalement la multiplication des cellules ;<\/li><li>une insensibilité aux signaux et mécanismes anti-prolifératifs ;<\/li><li>une capacité proliférative qui n&#x27;est plus limitée (croissance à l&#x27;infini) ;<\/li><li>la disparition du phénomène d&#x27;apoptose ;<\/li><li>une capacité anormale à susciter l&#x27;angiogenèse ;<\/li><li>et l&#x27;acquisition d&#x27;un pouvoir invasif et de production de métastases.<\/li><\/ul><p>Les nouvelles cellules résultantes, dites « cancéreuses » ou « tumorales », peuvent former une tumeur maligne (un néoplasme) ou se propager à travers le corps (métastase).<\/p><p>Un cancer (ou tumeur maligne) est une maladie caractérisée par une prolifération cellulaire (tumeur) anormalement importante au sein d&#x27;un tissu normal de l&#x27;organisme, de telle manière que la survie de ce dernier est menacée.<\/p><p>Ces cellules dérivent toutes d&#x27;un même clone, cellule initiatrice du cancer qui a acquis certaines caractéristiques lui permettant de se diviser indéfiniment.<\/p><p>Au cours de l&#x27;évolution de la maladie, certaines cellules peuvent migrer de leur lieu de production et former des métastases. Pour ces deux raisons, le dépistage du cancer doit être le plus précoce possible.<\/p><h4>II. Épidémiologie<\/h4><h4>Les chiffres du cancer (Monde &amp; Afrique)<\/h4><p>Dans le monde : le cancer est devenu un enjeu majeur de santé publique à l&#x27;échelle planétaire, tant dans les pays développés que ceux en voie de développement, et une des principales causes de mortalité.<\/p><div class=\"pgm\">p. 47<\/div><p>Pour l&#x27;année 2015, 8,8 millions de décès sont imputables au cancer, soit 13,5 % des décès enregistrés dans le monde. Plus de 32,6 millions de personnes vivent avec le cancer, dont 14,1 millions de nouveaux cas chaque année.<\/p><p>En 2012, 57 % (8 millions) des nouveaux cas de cancer, 65 % (5,3 millions) des décès par cancer et 48 % (15,6 millions) des personnes vivant avec le cancer depuis plus de 5 ans ont été recensés dans les pays en développement.<\/p><p>Les chiffres de la mortalité par cancer pourraient s&#x27;accroître de 50 % pour atteindre 15 millions d&#x27;ici à 2030 selon l&#x27;OMS. À cette date, près de 70 % des nouveaux cas de cancer se produiront dans les pays en développement.<\/p><p>En Afrique : en 2012, 846 961 personnes ont été atteintes de cancer. La mortalité a été de 591 161 durant la même période. Les études épidémiologiques prévoient 1,2 million de nouveaux cas de cancer en Afrique d&#x27;ici à 2030, avec plus de 970 000 morts si des mesures adéquates de prévention ne sont pas prises rapidement.<\/p><p>Les types de cancer les plus fréquents chez les Africaines sont : le cancer du sein, le cancer du col de l&#x27;utérus et le cancer primitif du foie.<\/p><p>Chez les hommes, les 3 cancers les plus communs sont le cancer de la prostate, le cancer primitif du foie et le sarcome de Kaposi.<\/p><p>La plupart des cancers de l&#x27;enfant enregistrés dans le monde (160 000 cas/an) touchent des enfants du tiers monde avec une surmortalité difficilement acceptable. Actuellement, 16 à 20 % des cancers de l&#x27;enfant sont guéris en Afrique subsaharienne, tandis que ce pourcentage avoisine les 75 % dans les pays économiquement avancés.<\/p><p>26 % des cas de cancers en Afrique sont consécutifs à des infections chroniques.<\/p><p>(Figures : incidence et mortalité — Source : Globocan 2012.)<\/p>","<div class=\"pgm\">p. 48<\/div><h4>III. Physiologie<\/h4><p>Les différentes liaisons qui existent entre les cellules sont :<\/p><ul><li>Les canaux de jonction intercellulaire : lors du déclenchement du processus cancéreux, ces éléments disparaissent progressivement, alors que la cellule commence à fonctionner d&#x27;elle-même. C&#x27;est la première étape de la cancérogenèse. Dès cet instant, la cellule présente, avec les autres cellules voisines, des perturbations au niveau des communications. Ce dysfonctionnement a un retentissement délétère sur son métabolisme (globalement son fonctionnement).<\/li><li>Le système paracrine, qui a pour but de faire sécréter par la cellule des molécules qui, en cas de processus cancéreux, ont une durée de vie très courte et qui ne diffusent pas vers les cellules éloignées, mais seulement vers les cellules situées à proximité.<\/li><li>Le système endocrinien est à l&#x27;origine de la sécrétion d&#x27;hormones qui passent dans le sang et peuvent de cette manière atteindre toutes les régions de l&#x27;organisme. Ce sont les messagers chimiques qui assurent le renouvellement d&#x27;un certain nombre de cellules dans l&#x27;organisme adulte. Ces messagers chimiques sont essentiellement les facteurs de croissance, qui facilitent ou inhibent la multiplication des cellules. Il existe dans les organismes vivants un système de contrôle qui permet de quantifier la prolifération cellulaire. Celui-ci est si précis que les cellules arrêtent de se diviser quand leur nombre est suffisant pour reconstituer un tissu en partie détruit préalablement.<\/li><\/ul><h4>IV. Physiopathologie<\/h4><p>Lors d&#x27;un cancer, les systèmes de jonction cellulaire fonctionnent soit mal, soit plus du tout.<\/p><p>Une tumeur cancéreuse est le résultat de la multiplication d&#x27;une cellule qui a perdu toutes les capacités décrites ci-dessus, et dont la descendance devient également cancéreuse.<\/p><p>Il a fallu attendre les années 1980 pour connaître avec précision le processus (appelé également oncogenèse) qui est dû à l&#x27;accumulation d&#x27;une série de défauts à l&#x27;intérieur du génome (ensemble des chromosomes) d&#x27;une cellule :<\/p><ul><li>Incapacité de la cellule à réguler sa reproduction, qui finit par s&#x27;emballer d&#x27;elle-même. Ainsi, il n&#x27;existe pas de signal en provenance du facteur de croissance, ou de la cellule elle-même, qui sécrète son propre facteur de croissance.<\/li><li>D&#x27;autres processus, comme le système d&#x27;inhibition par exemple, sont également perturbés.<\/li><\/ul><div class=\"pgm\">p. 49<\/div><ul><li>C&#x27;est au système d&#x27;immunosurveillance (constitué par le système immunitaire d&#x27;un individu et chargé de défendre celui-ci contre les corps étrangers) qu&#x27;il incombe de détruire les cellules n&#x27;appartenant pas aux tissus normaux, donc les cellules reconnues comme anormales. Les cellules précancéreuses peuvent quelquefois échapper à ce système d&#x27;immunosurveillance. Ce stade correspond à la phase cachée, pendant laquelle les cellules tumorales se multiplient lentement. Cette multiplication cellulaire est bien entendu différente de celle des cellules normales. Elle n&#x27;est pas plus rapide, mais elle n&#x27;est plus régulée comme pour les cellules normales. Le temps de doublement (temps pendant lequel la cellule se multiplie par 2) varie selon le type de tumeur. Ce temps varie entre une semaine et un an, mais chez la majorité des individus, il se compte en mois.<\/li><\/ul><p>De tout ce qui précède découle un ensemble de signes qui apparaissent au cours d&#x27;un cancer.<\/p><h4>1. Syndrome de masse<\/h4><p>La présence d&#x27;une tumeur en elle-même constitue un symptôme révélateur, soit directement, soit par les troubles qu&#x27;elle provoque. Comme le cancer envahit le tissu voisin, la masse est irrégulière et souvent dure au palper.<\/p><p>On peut citer comme exemples :<\/p><ul><li>« Boule » dans le sein<\/li><li>Tumeur cérébrale et œdème cérébral consécutif (syndrome d&#x27;hypertension intracrânienne marqué essentiellement par les céphalées et les vomissements, les crises d&#x27;épilepsie)<\/li><li>Dysphagie (blocage momentané du transit œsophagien) par la tumeur œsophagienne<\/li><li>Compression urétérale et/ou urétrale par la tumeur prostatique<\/li><li>Syndrome de petite vessie (mictions très nombreuses et réduites) provoqué par une volumineuse tumeur vésicale<\/li><li>Troubles digestifs variés par compression du grêle ou du côlon par une tumeur colique ou ovarienne<\/li><li>Gros testicule non douloureux typique d&#x27;un cancer<\/li><\/ul><h4>2. Invasion locale<\/h4><p>La tumeur cancéreuse envahit l&#x27;organe atteint localement, en perturbe rapidement l&#x27;aspect et les fonctions :<\/p><ul><li>Phénomène de la peau d&#x27;orange lorsque le cancer du sein envahit la peau<\/li><li>Dysphonie par atteinte des cordes vocales par un cancer du larynx<\/li><li>Troubles de la déglutition des cancers œsophagiens et ORL<\/li><li>Dyspepsie des tumeurs gastriques<\/li><\/ul><div class=\"pgm\">p. 50<\/div><ul><li>Constipation des tumeurs coliques<\/li><\/ul><p>Le cancer envahit le tissu environnant, provoquant :<\/p><ul><li>Œdème de compression (gros bras des tumeurs mammaires, phlébite des tumeurs pelviennes, ascite des tumeurs ovariennes, syndrome cave supérieur dans les tumeurs médiastinales)<\/li><li>Dyspnée et atélectasie des cancers du poumon ou des métastases pulmonaires<\/li><li>Lymphangites carcinomateuses du poumon réduisant l&#x27;amplitude des mouvements respiratoires utiles<\/li><li>Douleurs par atteinte des nerfs périphériques (otalgie des tumeurs du sinus piriforme, sciatiques des tumeurs osseuses ou pelviennes, etc.)<\/li><li>Tumeur de l&#x27;ombilic au cours des tumeurs ovariennes (syndrome de Sister Mary)<\/li><\/ul><h4>3. Hémorragie<\/h4><p>La nécessité d&#x27;un système de vascularisation pour nourrir la tumeur et la fragilité du système capillaire ainsi constitué expliquent la fréquence des hémorragies :<\/p><ul><li>Hémoptysie de la tumeur bronchique<\/li><li>Hématémèse et méléna de la tumeur gastrique<\/li><li>Hématurie des tumeurs vésicales, rénales, urétrales ou prostatiques<\/li><li>Hémospermie des tumeurs prostatiques<\/li><li>Rectorragies des tumeurs rectales<\/li><li>Métrorragies du cancer du col (avec son caractère particulier provoqué par les rapports sexuels)<\/li><li>Ménorragies et métrorragies des cancers du corps utérin<\/li><li>Ascite hémorragique des tumeurs ovariennes (ou des tumeurs digestives)<\/li><li>Pleurésie hémorragique des métastases pleurales<\/li><\/ul><p>Toute hémorragie mérite exploration, même en présence d&#x27;un traitement anticoagulant.<\/p><h4>4. Nécrose<\/h4><p>C&#x27;est la conséquence de la mauvaise vascularisation tumorale. Elle se complique fréquemment de :<\/p><ul><li>difficultés de cicatrisation<\/li><li>surinfection<\/li><li>mauvaises odeurs très caractéristiques (tumeurs ORL, tumeurs génitales)<\/li><li>fistules spontanées ou après traitement<\/li><\/ul><h4>5. Évolution à distance<\/h4><div class=\"pgm\">p. 51<\/div><p>La découverte du cancer par sa métastase survient dans 15 % des cas environ :<\/p><ul><li>Métastases ganglionnaires, avec notamment le ganglion sus-claviculaire de Troisier révélateur d&#x27;une tumeur digestive ou pelvienne, le ganglion inguinal révélateur d&#x27;une tumeur périnéale ou du membre inférieur, le ganglion cervical révélateur d&#x27;une tumeur ORL<\/li><li>Métastases cutanées (cancers du sein, cancers du rein, « Sister Mary » syndrome ou métastase ombilicale des cancers ovariens, tumeurs satellites des mélanomes, etc.)<\/li><li>Métastases hépatiques (exploration d&#x27;un ictère, de douleurs hépatiques)<\/li><li>Métastases pulmonaires (découvertes pour dyspnée ou par une radiographie pulmonaire systématique)<\/li><li>Métastases cérébrales (découvertes par une crise d&#x27;épilepsie, par exemple)<\/li><li>Autres métastases (n&#x27;importe quel organe)<\/li><\/ul><h4>V. Manifestations cliniques<\/h4><h4>I. Réactions générales<\/h4><h4>1. Anorexie<\/h4><p>L&#x27;anorexie correspond à la perte du désir de manger ou perte de l&#x27;appétit.<\/p><p>L&#x27;anorexie est induite par trois phénomènes différents qui se rencontrent au cours du cancer :<\/p><ul><li>La satiété précoce : la personne concernée est incapable de manger plus que quelques bouchées<\/li><li>Les nausées : la personne a envie de vomir dès qu&#x27;elle voit l&#x27;alimentation<\/li><li>La perte ou les modifications du goût et des odeurs : aucun élément n&#x27;est agréable à manger ; l&#x27;odeur de la viande, du porc, du jambon devient désagréable. La personne ne peut plus préparer ses repas du fait de cet inconfort.<\/li><\/ul><p>Au cours du cancer, l&#x27;anorexie peut être en rapport avec le cancer, avec le traitement mis en place ou avec les conséquences psychologiques du cancer.<\/p><p>Un certain nombre d&#x27;anomalies biologiques dues au cancer sont parfois retrouvées :<\/p><ul><li>Augmentation du taux de lactate sérique, en rapport avec la masse tumorale<\/li><li>Cétose en rapport avec le jeûne<\/li><li>Hypercalcémie (paranéoplasique ou au cours de métastases osseuses)<\/li><li>Les modifications anatomiques en rapport avec les tumeurs digestives et les conséquences mécaniques qu&#x27;elles entraînent : oropharynx, œsophage, estomac, pancréas, foie, péritoine<\/li><li>La sécrétion anormale de bombésine (neuropeptide) produite par les cancers à petites cellules du poumon, ou de sérotonine par les tumeurs car-<\/li><\/ul><div class=\"pgm\">p. 52<\/div><p>(Page dupliquée dans le scan : contenu identique à la page 50.)<\/p><div class=\"pgm\">p. 53<\/div><p>(Page dupliquée dans le scan : contenu identique à la page 51.)<\/p>","<div class=\"pgm\">p. 51<\/div><p>La découverte du cancer par sa métastase survient dans 15 % des cas environ :<\/p><ul><li>Métastases ganglionnaires, avec notamment le ganglion sus-claviculaire de Troisier révélateur d&#x27;une tumeur digestive ou pelvienne, le ganglion inguinal révélateur d&#x27;une tumeur périnéale ou du membre inférieur, le ganglion cervical révélateur d&#x27;une tumeur ORL<\/li><li>Métastases cutanées (cancers du sein, cancers du rein, « Sister Mary » syndrome ou métastase ombilicale des cancers ovariens, tumeurs satellites des mélanomes, etc.)<\/li><li>Métastases hépatiques (exploration d&#x27;un ictère, de douleurs hépatiques)<\/li><li>Métastases pulmonaires (découvertes pour dyspnée ou par une radiographie pulmonaire systématique)<\/li><li>Métastases cérébrales (découvertes par une crise d&#x27;épilepsie, par exemple)<\/li><li>Autres métastases (n&#x27;importe quel organe)<\/li><\/ul><h4>V. Manifestations cliniques<\/h4><h4>I. Réactions générales<\/h4><h4>1. Anorexie<\/h4><p>L&#x27;anorexie correspond à la perte du désir de manger ou perte de l&#x27;appétit.<\/p><p>L&#x27;anorexie est induite par trois phénomènes différents qui se rencontrent au cours du cancer :<\/p><ul><li>La satiété précoce : la personne concernée est incapable de manger plus que quelques bouchées<\/li><li>Les nausées : la personne a envie de vomir dès qu&#x27;elle voit l&#x27;alimentation<\/li><li>La perte ou les modifications du goût et des odeurs : aucun élément n&#x27;est agréable à manger ; l&#x27;odeur de la viande, du porc, du jambon devient désagréable. La personne ne peut plus préparer ses repas du fait de cet inconfort.<\/li><\/ul><p>Au cours du cancer, l&#x27;anorexie peut être en rapport avec le cancer, avec le traitement mis en place ou avec les conséquences psychologiques du cancer.<\/p><p>Un certain nombre d&#x27;anomalies biologiques dues au cancer sont parfois retrouvées :<\/p><ul><li>Augmentation du taux de lactate sérique, en rapport avec la masse tumorale<\/li><li>Cétose en rapport avec le jeûne<\/li><li>Hypercalcémie (paranéoplasique ou au cours de métastases osseuses)<\/li><li>Les modifications anatomiques en rapport avec les tumeurs digestives et les conséquences mécaniques qu&#x27;elles entraînent : oropharynx, œsophage, estomac, pancréas, foie, péritoine<\/li><li>La sécrétion anormale de bombésine (neuropeptide) produite par les cancers à petites cellules du poumon, ou de sérotonine par les tumeurs car-<\/li><\/ul><div class=\"pgm\">p. 52<\/div><p>(Page dupliquée dans le scan : contenu identique à la page 50.)<\/p><div class=\"pgm\">p. 53<\/div><p>(Page dupliquée dans le scan : contenu identique à la page 51.)<\/p><div class=\"pgm\">p. 54<\/div><p>-cinoïdes<\/p><ul><li>Augmentation du taux de tryptophane en rapport avec un métabolisme intra-tumoral anormal<\/li><li>La production de cytokines anorexigènes par la tumeur, notamment le TNFα (Tumor Necrosis Factor α), l&#x27;IL1 (interleukine 1) ou l&#x27;IFN-γ (interféron γ), qui semblent avoir un effet direct sur le centre nerveux de la satiété (aire hypothalamique)<\/li><\/ul><p>La plupart des traitements du cancer favorisent dans un premier temps l&#x27;anorexie :<\/p><ul><li>Modifications du goût et difficultés alimentaires post-opératoires<\/li><li>Vomissements et nausées entraînés par la radiothérapie, mucite, sécheresse des muqueuses digestives entraînant la disparition de la sécrétion salivaire<\/li><li>Nausées, vomissements, mucite induits par la chimiothérapie<\/li><\/ul><p>L&#x27;anorexie peut être en rapport avec les conséquences psychologiques induites par le cancer :<\/p><ul><li>Anorexie transitoire en rapport avec l&#x27;annonce de la maladie<\/li><li>Dépression psychotique réelle favorisée par le cancer, entraînant une perte de poids majeure et nécessitant un traitement à visée antidépressive<\/li><\/ul><h4>2. Cachexie<\/h4><p>La cachexie, ou altération de l&#x27;état général avec amaigrissement progressif, est la conséquence de l&#x27;anorexie et de l&#x27;évolution de la maladie cancéreuse. Plusieurs facteurs déclenchants sont incriminés :<\/p><ul><li>l&#x27;effet de détournement du métabolisme normal pour la construction de la tumeur<\/li><li>l&#x27;effet de masse tumorale elle-même, et la sécrétion par la tumeur ou les cellules mononucléées de l&#x27;hôte de cytokines nécrotiques<\/li><li>l&#x27;atteinte du tube digestif (avec syndromes sub-occlusifs a minima) avec des troubles de l&#x27;absorption des nutriments<\/li><li>l&#x27;effet complémentaire de mauvaise alimentation et de dénutrition entraîné par l&#x27;alcoolisme et le tabagisme<\/li><li>la présence de métastases hépatiques (mauvais métabolisme des différents nutriments)<\/li><\/ul><p>La manifestation clinique la plus facile à mesurer est l&#x27;amaigrissement, parfois masqué par un œdème ou un épanchement. Des pertes de poids de l&#x27;ordre de 10 % à 20 % du poids initial sont souvent rencontrées au cours des cancers très anorexigènes, comme le cancer de l&#x27;œsophage ou de l&#x27;estomac. Il existe un rapport très net entre l&#x27;amaigrissement constaté au début du traitement d&#x27;un cancer et le mauvais pronostic de ce cancer.<\/p><p>Une dénutrition très importante est parfois observée au cours de certains traitements (radiothérapie pour un cancer ORL, chimiothérapie mal supportée) et doit faire arrêter<\/p><div class=\"pgm\">p. 55<\/div><p>momentanément la thérapeutique et prendre des mesures correctives (comme l&#x27;hyperalimentation par composants nutritifs ou la nutrition parentérale totale).<\/p><p>La grande cachexie (notamment celle observée en fin de vie) se manifeste par une grande émaciation, une fonte des masses musculaires et même adipeuses, une fragilité de la peau qui devient parcheminée, une perte du dentier devenant trop grand, la vision du squelette à travers une peau racornie. Des complications peuvent survenir rapidement, notamment au niveau de la bouche sèche et des points d&#x27;appui du corps (escarre de décubitus).<\/p><p>Biologiquement, cette cachexie se manifeste par un métabolisme accru des lipides et des protides, une anémie (en dehors de toute cause clairement manifeste), une hypoalbuminémie, et une fréquente hyponatrémie (sans cause clairement définie).<\/p><h4>3. Fièvre<\/h4><p>La fièvre survient très fréquemment au cours des cancers, notamment en phase terminale. Il faut certes chercher systématiquement un syndrome infectieux (cf. chapitre sur les urgences en cancérologie), mais celui-ci n&#x27;est pas toujours présent.<\/p><p>La fièvre peut être spécifique de certains types de cancers (maladie de Hodgkin, leucémie aiguë, cancer du rein, sarcome ostéogénique, myxome atrial, notamment), s&#x27;accompagner de sueurs et faire partie des éléments de diagnostic et de pronostic de ces cancers (fabrication d&#x27;interleukine 1 ?).<\/p><p>Plus généralement, on observe une fièvre en cas de masse tumorale importante (à peu près les mêmes mécanismes que la cachexie), avec nécrose tumorale qui peut se compliquer de surinfections locales (parfois en raison de microbes anaérobies).<\/p><p>La présence de métastases hépatiques entraîne souvent des fièvres modérées qui répondent souvent aux anti-inflammatoires non stéroïdiens ou stéroïdiens (corticoïdes).<\/p><h4>II. Syndrome paranéoplasique<\/h4><p>Le porteur de la tumeur cancéreuse peut encore réagir différemment à la survenue du cancer. Certaines réactions systémiques peuvent être révélatrices de la tumeur ou survenir au cours de l&#x27;évolution.<\/p><p>Les syndromes paranéoplasiques sont des manifestations systémiques, en rapport avec la tumeur et disparaissant avec elle. L&#x27;aspect catalogue de l&#x27;énumération ci-dessous ne doit pas faire oublier la rareté de la plupart des syndromes ainsi décrits.<\/p><h4>1. Manifestations endocriniennes<\/h4><div class=\"pgm\">p. 56<\/div><p>Ce sont les mieux connues et explorées : elles correspondent à la sécrétion ectopique d&#x27;une substance ressemblant à une hormone (voire à l&#x27;hormone elle-même), retrouvée à un taux sérique élevé, disparaissant avec le traitement du cancer.<\/p><p>On peut citer comme exemples :<\/p><ul><li>La sécrétion ectopique d&#x27;HCG par les choriocarcinomes et les tumeurs germinales non séminomateuses, qu&#x27;elles soient gonadiques ou non, pouvant entraîner une gynécomastie bilatérale<\/li><li>La sécrétion ectopique de PTH (hormone parathyroïdienne) dans les hypercalcémies malignes des cancers épidermoïdes de la tête et du cou, du poumon et de l&#x27;œsophage<\/li><li>La sécrétion ectopique d&#x27;ACTH (syndrome cushingoïde) des cancers bronchiques à petites cellules<\/li><li>La sécrétion ectopique d&#x27;ADH (syndrome de Schwartz-Bartter avec hyponatrémie et œdème) des cancers bronchiques à petites cellules<\/li><li>La sécrétion ectopique de GH (expliquant peut-être l&#x27;ostéoarthropathie hypertrophiante de Pierre Marie : doigts en baguette de tambour) dans les cancers bronchiques et gastriques<\/li><\/ul><h4>2. Troubles hématologiques<\/h4><p>Ils sont variés et très fréquents :<\/p><ul><li>Polyglobulies des tumeurs rénales et des angiomes cérébelleux, expliquées dans 50 % des cas par une sécrétion ectopique d&#x27;érythropoïétine<\/li><li>Anémies de causes variées : déperditions sanguines dues au cancer lui-même ; syndrome inflammatoire ; coagulation intravasculaire disséminée ; anémie auto-immune des tumeurs lymphoïdes B ; troubles en rapport avec une mauvaise absorption de la vitamine B12 ou des folates ; la plupart des anémies au cours des phases terminales n&#x27;ont pas de cause très précise et sont plutôt un signe de la cachexie terminale<\/li><li>Réactions sur la lignée blanche : réaction leucémoïde devant faire rechercher un envahissement médullaire ; syndrome d&#x27;hypersécrétion de facteur de croissance GM-CSF, sans envahissement médullaire<\/li><li>Thrombocytose en rapport avec le syndrome inflammatoire des cancers<\/li><li>Thrombopénie en rapport avec une coagulation intravasculaire disséminée, un purpura thrombopénique auto-immun (syndromes lympho-prolifératifs)<\/li><\/ul><div class=\"pgm\">p. 57<\/div><ul><li>Troubles de la coagulation variés<\/li><\/ul><h4>3. Manifestations dermatologiques<\/h4><p>Il faut savoir tout d&#x27;abord reconnaître les métastases cutanées des cancers (sein, nodules de perméation, fistules tumorales, etc.), qui sont les manifestations les plus fréquentes. Un certain nombre de manifestations cutanées sont dites paranéoplasiques :<\/p><ul><li>Dermatomyosite : pouvant se voir avec de nombreux types de cancer, entraînant un érythème héliotrope et un gonflement des régions orbitaires, des joues, du front, s&#x27;accompagnant de plaques violacées « en ligne » au niveau du dos de la main et des doigts (notamment au niveau des ongles). L&#x27;atteinte musculaire est variée, touchant surtout les muscles proximaux. Le traitement est celui de la tumeur primitive associé à une corticothérapie.<\/li><li>Syndromes paranéoplasiques : maladie de Paget du sein, ou eczéma du mamelon associé à un cancer du sein ; ichtyose acquise de la maladie de Hodgkin ; acanthosis nigricans (hyperpigmentation notamment au niveau des aisselles et hyperkératose des plis) des cancers digestifs ; erythema gyratum repens ; hypertrichose lanugineuse acquise (duvet de la face des cancers pulmonaires ou digestifs)<\/li><\/ul><h4>4. Manifestations neurologiques<\/h4><p>La plupart des manifestations neurologiques sont en rapport avec une atteinte neurologique par métastase. On décrit comme manifestations paranéoplasiques :<\/p><ul><li>Manifestations cérébrales en rapport avec des perturbations métaboliques (notamment hyponatrémie)<\/li><li>Encéphalopathie paranéoplasique<\/li><li>Neuropathie sensitive subaiguë<\/li><li>Ataxie cérébelleuse<\/li><\/ul><h4>VI. Typologie<\/h4><p>Il existe généralement :<\/p><h4>I. Les carcinomes<\/h4><p>Cancer d&#x27;un épithélium, c&#x27;est-à-dire une surface composée uniquement de cellules ;<\/p>","<div class=\"pgm\">p. 57<\/div><ul><li>Troubles de la coagulation variés<\/li><\/ul><h4>3. Manifestations dermatologiques<\/h4><p>Il faut savoir tout d&#x27;abord reconnaître les métastases cutanées des cancers (sein, nodules de perméation, fistules tumorales, etc.), qui sont les manifestations les plus fréquentes. Un certain nombre de manifestations cutanées sont dites paranéoplasiques :<\/p><ul><li>Dermatomyosite : pouvant se voir avec de nombreux types de cancer, entraînant un érythème héliotrope et un gonflement des régions orbitaires, des joues, du front, s&#x27;accompagnant de plaques violacées « en ligne » au niveau du dos de la main et des doigts (notamment au niveau des ongles). L&#x27;atteinte musculaire est variée, touchant surtout les muscles proximaux. Le traitement est celui de la tumeur primitive associé à une corticothérapie.<\/li><li>Syndromes paranéoplasiques : maladie de Paget du sein, ou eczéma du mamelon associé à un cancer du sein ; ichtyose acquise de la maladie de Hodgkin ; acanthosis nigricans (hyperpigmentation notamment au niveau des aisselles et hyperkératose des plis) des cancers digestifs ; erythema gyratum repens ; hypertrichose lanugineuse acquise (duvet de la face des cancers pulmonaires ou digestifs)<\/li><\/ul><h4>4. Manifestations neurologiques<\/h4><p>La plupart des manifestations neurologiques sont en rapport avec une atteinte neurologique par métastase. On décrit comme manifestations paranéoplasiques :<\/p><ul><li>Manifestations cérébrales en rapport avec des perturbations métaboliques (notamment hyponatrémie)<\/li><li>Encéphalopathie paranéoplasique<\/li><li>Neuropathie sensitive subaiguë<\/li><li>Ataxie cérébelleuse<\/li><\/ul><h4>VI. Typologie<\/h4><p>Il existe généralement :<\/p><h4>I. Les carcinomes<\/h4><p>Cancer d&#x27;un épithélium, c&#x27;est-à-dire une surface composée uniquement de cellules ;<\/p><div class=\"pgm\">p. 58<\/div><h4>II. Les sarcomes<\/h4><p>Cancers proliférant dans des tissus conjonctifs comme les os ;<\/p><h4>III. Les cancers hématopoïétiques<\/h4><p>Cancer des cellules sanguines.<\/p><p>Il existe un classement selon les organes touchés, par exemple :<\/p><ul><li>le cancer du sein ;<\/li><li>le cancer du côlon et du rectum ;<\/li><li>le cancer du pancréas ;<\/li><li>le myélome multiple : cancer de la moelle osseuse ;<\/li><li>les leucémies : cancers du sang ;<\/li><li>le sarcome de Kaposi : cancer des vaisseaux sanguins ;<\/li><\/ul><h4>IV. Les lymphomes<\/h4><p>Maladie de Hodgkin et lymphome non hodgkinien ;<\/p><p>Il existe presque autant de sources de cancer que de tissus dans l&#x27;organisme. Certains sont toutefois plus fréquents que d&#x27;autres.<\/p><h4>VII. Les facteurs de risque<\/h4><p>Les facteurs de risque du cancer peuvent être endogènes ou exogènes.<\/p><h4>I. Risques endogènes<\/h4><p>Dans certains cas, l&#x27;apparition d&#x27;un cancer a une composante héréditaire. C&#x27;est le cas de quelques-uns, comme certains cancers du sein.<\/p><p>Certains cancers induits par certains comportements transmis de génération en génération (consommation d&#x27;alcool ou de tabac) peuvent être confondus avec un risque génétique vrai, et inversement certains gènes prédisposant au cancer pourraient n&#x27;être activés que dans certaines circonstances (obésité, alcoolisme, etc.).<\/p><h4>II. Risques exogènes dits « environnementaux »<\/h4><p>Les facteurs exogènes de risque dépassent le seul champ de l&#x27;environnement puisque recouvrant aussi, par exemple, les bactéries et virus inducteurs de cancers. Ils sont en partie liés :<\/p><h4>1. Aux comportements à risque<\/h4><p>Ils augmentent l&#x27;exposition de l&#x27;individu à ces facteurs.<\/p><p>Ainsi, le tabagisme est la principale cause du cancer du poumon, et l&#x27;éthanol (alcool), même à dose modérée, est classé dans la liste des cancérogènes du groupe 1 du CIRC.<\/p><div class=\"pgm\">p. 59<\/div><h4>2. À la radioactivité<\/h4><p>Les rayonnements ionisants sont cancérigènes ; il convient donc notamment d&#x27;éviter la pollution radioactive militaire, industrielle ou accidentelle.<\/p><h4>3. Aux radiations solaires<\/h4><p>Les UV du soleil sont cancérigènes. Il est notamment important d&#x27;éviter une surexposition au soleil, ou d&#x27;utiliser correctement les crèmes solaires lors d&#x27;une exposition prolongée au soleil.<\/p><h4>4. Aux micro-organismes<\/h4><p>Les virus et bactéries font partie des facteurs exogènes du cancer. Certains cancers peuvent être induits par des virus, tel le cancer du col de l&#x27;utérus provoqué par le VPH. Le cancer primitif du foie est aussi dû au virus de l&#x27;hépatite.<\/p><h4>5. À l&#x27;obésité<\/h4><p>Elle jouerait un rôle dans près de 4 % des cancers, et pour beaucoup des cancers hormono-dépendants (du sein et de l&#x27;utérus, et semble-t-il colorectal, de la vésicule biliaire, de la prostate, du pancréas et des reins ; à cause d&#x27;une production œstrogénique anormale et accrue dans les tissus gras).<\/p><h4>6. À l&#x27;alimentation<\/h4><p>L&#x27;alimentation joue un rôle dans la survenue de cancers. Selon le Fonds mondial de recherche contre le cancer, 30 à 40 % des cancers seraient imputables à l&#x27;alimentation.<\/p><h4>7. Aux mycotoxines<\/h4><p>Outre l&#x27;alcool cité plus haut, elles sont considérées comme des facteurs établis de cancer.<\/p><h4>8. Aux polluants<\/h4><p>Leur rôle exact dans la genèse des cancers reste difficile à évaluer. Les cancérologues accusent notamment l&#x27;exposition :<\/p><ul><li>aux pesticides, d&#x27;être responsable de cancers chez les agriculteurs<\/li><li>amiante<\/li><li>benzène<\/li><li>trichloréthylène<\/li><li>arsenic<\/li><li>formaldéhyde<\/li><li>gaz moutarde<\/li><li>iode 131<\/li><li>radon, etc.<\/li><\/ul><div class=\"pgm\">p. 60<\/div><ul><li>les poussières de bois<\/li><li>le goudron de houille et<\/li><li>la suie<\/li><\/ul><h4>9. Aux perturbateurs endocriniens<\/h4><p>Mimant les hormones naturelles, certains sont fortement soupçonnés d&#x27;initier des cancers dits « dépendants des hormones » (par exemple le cancer du sein) ; la perturbation peut se produire in utero et donner par exemple des cancers du testicule, ou d&#x27;autres types de cancers susceptibles d&#x27;être induits par des molécules telles que le distilbène.<\/p><h4>10. À l&#x27;éclairage artificiel<\/h4><p>Il est évoqué, et parfois assimilé à la catégorie pollution lumineuse (pour le cancer du sein au moins), via une perturbation endocrinienne chez les femmes exposées à une lumière artificielle la nuit.<\/p><h4>11. Aux nanomatériaux<\/h4><p>Certains nanomatériaux ont une toxicité avérée et/ou une génotoxicité potentielle, aggravée par la taille infime de ces particules qui peuvent ainsi atteindre l&#x27;ADN et le génome. Ils sont suspectés de peut-être contribuer à certains cancers.<\/p><p>En ce qui concerne les facteurs probables de cancer, sont cités :<\/p><ul><li>les produits laitiers<\/li><li>la viande<\/li><li>les charcuteries, à cause de leur teneur en nitrites<\/li><li>les glucides à haut indice glycémique<\/li><li>les résidus de pesticides<\/li><li>l&#x27;acrylamide et<\/li><li>le benzopyrène (issu des viandes grillées notamment)<\/li><\/ul><h4>VIII. Les facteurs protecteurs<\/h4><p>Certains comportements alimentaires diminueraient le risque de survenue d&#x27;un cancer :<\/p><ul><li>La consommation régulière de fruits et légumes, ainsi que la consommation de fibres, et peut-être celle d&#x27;antioxydants, de phyto-œstrogènes<\/li><\/ul><div class=\"pgm\">p. 61<\/div><ul><li>La pratique du jeûne intermittent pourrait avoir un effet protecteur également<\/li><li>Activité physique : l&#x27;activité physique pratiquée au quotidien a un effet protecteur vis-à-vis du cancer. Cet effet est plus marqué pour le cancer du côlon, du sein, de l&#x27;utérus et des poumons.<\/li><\/ul><h4>IX. Prévention<\/h4><p>La prévention du cancer se fonde sur :<\/p><h4>I. L&#x27;évitement ou la diminution de l&#x27;exposition aux agents cancérogènes environnementaux et industriels : principalement, la lutte contre :<\/h4><ul><li>le tabagisme<\/li><li>la consommation excessive d&#x27;alcool et<\/li><li>la consommation excessive de graisses animales<\/li><li>l&#x27;exposition excessive au soleil<\/li><li>les normes de construction (désamiantage), radioprotection<\/li><li>la manutention de produits dangereux dans le cadre professionnel<\/li><\/ul><h4>II. Le rôle protecteur (« oncostatique ») de certains éléments :<\/h4><ul><li>Fibres<\/li><li>Vitamines et autres antioxydants (céréales, légumes verts, fruits), ainsi que le thé vert (plus que le noir) ou le chocolat, et plus précisément les aliments contenant de la catéchine<\/li><li>Consommer une gousse d&#x27;ail par jour réduit de moitié le risque de cancer de l&#x27;estomac, du côlon et du rectum<\/li><li>Le traitement des lésions précancéreuses<\/li><\/ul><h4>III. Dépistage des cancers en médecine générale<\/h4><p>Il consiste en la détection la plus précoce possible de lésions précancéreuses ou de cancers, chez des personnes ne présentant pas encore de symptômes évidents. Le but est de trouver, dans une population donnée, des lésions que l&#x27;on peut encore traiter facilement.<\/p><p>Cela se fait par la clinique (l&#x27;examen du patient) :<\/p><ul><li>palpation des seins<\/li><li>frottis cervicovaginal<\/li><li>toucher rectal, etc.<\/li><\/ul><p>et des examens paracliniques :<\/p><ul><li>radiographie<\/li><li>dosages biologiques<\/li><\/ul>","<div class=\"pgm\">p. 61<\/div><ul><li>La pratique du jeûne intermittent pourrait avoir un effet protecteur également<\/li><li>Activité physique : l&#x27;activité physique pratiquée au quotidien a un effet protecteur vis-à-vis du cancer. Cet effet est plus marqué pour le cancer du côlon, du sein, de l&#x27;utérus et des poumons.<\/li><\/ul><h4>IX. Prévention<\/h4><p>La prévention du cancer se fonde sur :<\/p><h4>I. L&#x27;évitement ou la diminution de l&#x27;exposition aux agents cancérogènes environnementaux et industriels : principalement, la lutte contre :<\/h4><ul><li>le tabagisme<\/li><li>la consommation excessive d&#x27;alcool et<\/li><li>la consommation excessive de graisses animales<\/li><li>l&#x27;exposition excessive au soleil<\/li><li>les normes de construction (désamiantage), radioprotection<\/li><li>la manutention de produits dangereux dans le cadre professionnel<\/li><\/ul><h4>II. Le rôle protecteur (« oncostatique ») de certains éléments :<\/h4><ul><li>Fibres<\/li><li>Vitamines et autres antioxydants (céréales, légumes verts, fruits), ainsi que le thé vert (plus que le noir) ou le chocolat, et plus précisément les aliments contenant de la catéchine<\/li><li>Consommer une gousse d&#x27;ail par jour réduit de moitié le risque de cancer de l&#x27;estomac, du côlon et du rectum<\/li><li>Le traitement des lésions précancéreuses<\/li><\/ul><h4>III. Dépistage des cancers en médecine générale<\/h4><p>Il consiste en la détection la plus précoce possible de lésions précancéreuses ou de cancers, chez des personnes ne présentant pas encore de symptômes évidents. Le but est de trouver, dans une population donnée, des lésions que l&#x27;on peut encore traiter facilement.<\/p><p>Cela se fait par la clinique (l&#x27;examen du patient) :<\/p><ul><li>palpation des seins<\/li><li>frottis cervicovaginal<\/li><li>toucher rectal, etc.<\/li><\/ul><p>et des examens paracliniques :<\/p><ul><li>radiographie<\/li><li>dosages biologiques<\/li><\/ul><div class=\"pgm\">p. 62<\/div><h4>X. Diagnostic<\/h4><p>Même s&#x27;il existe des éléments permettant d&#x27;identifier un cancer avec une grande probabilité, le diagnostic de certitude ne se fait que sur analyse au microscope (anatomopathologie) d&#x27;un échantillon de la tumeur (éventuellement aidé par d&#x27;autres techniques). Cet échantillon vient soit d&#x27;une biopsie (simple prélèvement d&#x27;un morceau de la tumeur), qui peut être faite, suivant la localisation, selon différentes procédures (fibroscopie, ponction à travers la peau…), soit d&#x27;une pièce opératoire (tumeur enlevée par le chirurgien).<\/p><h4>XI. Traitements<\/h4><p>Le traitement est effectué en milieu spécialisé. C&#x27;est en règle le travail d&#x27;une équipe sur une stratégie médicale pluridisciplinaire (spécialités : oncologie, radiothérapie, chirurgie, gynécologie, gastro-entérologie, etc.).<\/p><p>Suivant les cas, il repose sur :<\/p><ul><li>l&#x27;exérèse (l&#x27;ablation) chirurgicale large de la tumeur quand cela est possible, « large » voulant dire que le bistouri du chirurgien passe uniquement par des tissus sains ;<\/li><li>un traitement mini-invasif percutané par radiofréquence, micro-ondes ou cryothérapie, en complément ou en alternative à la chirurgie ;<\/li><li>une chimiothérapie : prescription de médicaments s&#x27;attaquant au cancer et à ses métastases ;<\/li><li>une radiothérapie : l&#x27;irradiation de la tumeur permettant de faire fondre, voire disparaître celle-ci.<\/li><\/ul><p>Certains cancers peuvent bénéficier également :<\/p><ul><li>d&#x27;un traitement hormonal ;<\/li><li>d&#x27;un traitement à visée immunologique consistant à augmenter l&#x27;action du système immunitaire ; une piste est notamment explorée, qui associe l&#x27;interleukine-7 (IL-7) à un vaccin viral pour inciter le système immunitaire à attaquer les tumeurs. Ces travaux ont aussi montré comment l&#x27;IL-7 casse les barrières qui freinaient la réponse immunitaire aux tumeurs ;<\/li><li>d&#x27;un traitement à base d&#x27;ultrasons, une technologie en plein développement s&#x27;appuyant sur la focalisation d&#x27;un faisceau ultrasonore très puissant sur une métastase ;<\/li><li>d&#x27;un traitement par photochimiothérapie, qui consiste à détruire les cellules cancéreuses (notamment dans les cancers de la peau) au moyen de substances chimiques devenant toxiques à la lumière.<\/li><\/ul><div class=\"pgm\">p. 63<\/div><p>Souvent, plusieurs de ces types de traitements sont nécessaires chez un même patient. Il ne faut pas oublier le traitement des conséquences de la tumeur, la prise en charge des effets secondaires du traitement et le traitement de la douleur.<\/p><h4>Traitements alternatifs<\/h4><p>Il existe de nombreux traitements alternatifs, mais l&#x27;évaluation scientifique de leur efficacité est souvent soit inexistante, soit non validée en pratique clinique, c&#x27;est-à-dire validée dans des modèles expérimentaux ou animaux mais pas chez l&#x27;homme.<\/p><p>Par exemple, de nombreuses substances tuent les cellules cancéreuses en laboratoire ou chez l&#x27;animal mais fonctionnent mal chez l&#x27;homme.<\/p><p>Quelques exemples de traitements alternatifs :<\/p><ul><li>La supplémentation de très fortes doses de vitamine C en médecine orthomoléculaire<\/li><li>De nombreux régimes alimentaires censés lutter contre le cancer, par exemple : des régimes végétariens ; le jeûne thérapeutique dans le but de « détoxifier » l&#x27;organisme ou pour faire « maigrir » les tumeurs<\/li><li>D&#x27;autres méthodes font appel à la guérison par la foi et la prière ; depuis l&#x27;Antiquité, il existe notamment aux États-Unis des évangélistes guérisseurs.<\/li><\/ul><h4>Le cancer bronchique<\/h4><h4>Définition<\/h4><p>= Tumeur maligne qui se développe au niveau de la muqueuse bronchique.<\/p><p>NB : cancer bronchique secondaire = quand les métastases pulmonaires proviennent d&#x27;un<\/p>","<div class=\"pgm\">p. 63<\/div><p>Souvent, plusieurs de ces types de traitements sont nécessaires chez un même patient. Il ne faut pas oublier le traitement des conséquences de la tumeur, la prise en charge des effets secondaires du traitement et le traitement de la douleur.<\/p><h4>Traitements alternatifs<\/h4><p>Il existe de nombreux traitements alternatifs, mais l&#x27;évaluation scientifique de leur efficacité est souvent soit inexistante, soit non validée en pratique clinique, c&#x27;est-à-dire validée dans des modèles expérimentaux ou animaux mais pas chez l&#x27;homme.<\/p><p>Par exemple, de nombreuses substances tuent les cellules cancéreuses en laboratoire ou chez l&#x27;animal mais fonctionnent mal chez l&#x27;homme.<\/p><p>Quelques exemples de traitements alternatifs :<\/p><ul><li>La supplémentation de très fortes doses de vitamine C en médecine orthomoléculaire<\/li><li>De nombreux régimes alimentaires censés lutter contre le cancer, par exemple : des régimes végétariens ; le jeûne thérapeutique dans le but de « détoxifier » l&#x27;organisme ou pour faire « maigrir » les tumeurs<\/li><li>D&#x27;autres méthodes font appel à la guérison par la foi et la prière ; depuis l&#x27;Antiquité, il existe notamment aux États-Unis des évangélistes guérisseurs.<\/li><\/ul><h4>Le cancer bronchique<\/h4><h4>Définition<\/h4><p>= Tumeur maligne qui se développe au niveau de la muqueuse bronchique.<\/p><p>NB : cancer bronchique secondaire = quand les métastases pulmonaires proviennent d&#x27;un<\/p><div class=\"pgm\">p. 64<\/div><p>cancer extra-thoracique (sein, prostate et côlon).<\/p><ul><li>Première cause de décès par cancer chez les hommes !<\/li><li>Stable chez les hommes, en augmentation chez les femmes<\/li><li>Mauvais pronostic : seulement 10 % de survie à 5 ans !<\/li><\/ul><h4>Étiologies<\/h4><ul><li>Tabac : 80 % des cancers. La durée du tabagisme est plus importante que le nombre de cigarettes consommées…<\/li><li>Facteurs professionnels : 20 % (amiante, radioactivité, chrome, fer, arsenic…)<\/li><li>Pollution atmosphérique<\/li><\/ul><p>Il existe deux types :<\/p><ul><li>le carcinome bronchique non à petites cellules (CBNPC)<\/li><li>le carcinome bronchique à petites cellules (CBPC)<\/li><\/ul><h4>Le CBNPC<\/h4><ul><li>C&#x27;est le plus fréquent = 80 % des cancers bronchiques<\/li><li>Évolution lente<\/li><li>Opérable<\/li><li>Peu chimiosensible<\/li><\/ul><h4>1. Sémiologie<\/h4><p>Signes respiratoires :<\/p><ul><li>Toux persistante<\/li><li>Dyspnée<\/li><li>Infection qui traîne<\/li><li>Hémoptysies<\/li><\/ul><p>Signes de l&#x27;extension locorégionale :<\/p><ul><li>Douleur thoracique<\/li><li>Compression médiastinale avec dysphagie, dysphonie (modification de la voix), dyspnée…<\/li><\/ul><p>Signes généraux :<\/p><ul><li>AEG avec les 3 A (amaigrissement, anorexie, asthénie)<\/li><li>Fièvre<\/li><\/ul><p>Syndrome métastasique :<\/p><div class=\"pgm\">p. 65<\/div><ul><li>Foyers secondaires d&#x27;une affection, disséminés par voie lymphatique ou sanguine : hépatiques, osseux, cérébraux, surrénaliens ; adénopathies<\/li><\/ul><h4>2. Examens complémentaires<\/h4><ul><li>Clinique<\/li><li>Marqueurs tumoraux ACE<\/li><li>Radio / scanner thoracique : opacité tumorale, atélectasie…<\/li><li>Fibroscopie bronchique : examen clé du diagnostic ! Observation de la lésion avec bourgeon bronchique et infiltration muqueuse<\/li><li>Ponction transpariétale : ponction à l&#x27;aiguille guidée par un scanner de la masse pulmonaire<\/li><li>Examens complémentaires : scintigraphie osseuse, scanner cérébral…<\/li><\/ul><h4>3. Traitement<\/h4><p>Avant tout, faire un bilan d&#x27;extension locorégionale + un bilan d&#x27;extension à distance (recherche de métastases).<\/p><p>Ensuite, faire un bilan d&#x27;opérabilité (cardio, respi…).<\/p><ul><li>Formes opérables = chirurgie + radiothérapie post-opératoire. Survie &gt; 5 ans ! (lobectomie, pneumonectomie, curage ganglionnaire…)<\/li><li>Formes inopérables = radio + chimio. Survie médiocre !<\/li><\/ul><h4>Le CBPC<\/h4><ul><li>20 % des cancers bronchiques<\/li><li>Évolution très rapide !<\/li><li>Rapide diffusion systémique : métastases très fréquentes<\/li><li>Chimiosensible mais tendance à la récidive !<\/li><li>Non opérable<\/li><\/ul><h4>1. Sémiologie<\/h4><p>Idem que le CBNPC, avec des métastases révélatrices plus fréquentes et une AEG importante.<\/p><h4>2. Examens<\/h4><p>Idem.<\/p><h4>3. Traitement<\/h4><p>Évolution spontanée défavorable = décès en 1 à 4 mois !<\/p><p>Intérêt de la chimio contre les métastases.<\/p>","<div class=\"pgm\">p. 66<\/div><h4>Le cancer de la prostate<\/h4><p>= Cancer hormono-dépendant touchant la prostate.<\/p><ul><li>Adénocarcinome dans 95 % des cas<\/li><li>Second cancer chez l&#x27;homme dans les pays industrialisés<\/li><li>Évolution lente (10 ans)<\/li><li>1/3 de décès<\/li><\/ul><h4>Facteurs favorisants<\/h4><ul><li>Âge (&gt; 50 ans)<\/li><li>Formes familiales<\/li><li>Origines ethniques (Noirs, Antillais plus exposés)<\/li><\/ul><h4>Sémiologie<\/h4><p>Stade local = aucun symptôme.<\/p><p>Découverte fortuite ou grâce au dépistage individuel systématique à partir de 50 ans (45 ans si à risque) : PSA + TR tous les ans !<\/p><p>TR = nodule dur et PSA augmenté.<\/p><p>Stade évolué = envahissement ganglionnaire, métastases. Suivant l&#x27;atteinte :<\/p><ul><li>locorégionale (dysurie, hématurie, hydronéphrose, insuffisance rénale, douleurs, envahissement du rectum avec rectorragies…)<\/li><li>ganglionnaire (lymphœdème…)<\/li><li>métastatique (douleurs osseuses +++, poumons, foie)<\/li><\/ul><h4>Examens<\/h4><ul><li>TR +++<\/li><li>Dosage du PSA (antigène spécifique de la prostate : enzyme de liquéfaction du sperme contenue dans le liquide prostatique ; augmente en cas de cancer, d&#x27;HBP, de trauma, d&#x27;infection…)<\/li><li>Confirmation par biopsies prostatiques (minimum 6)<\/li><li>Bilan d&#x27;extension (scintigraphie osseuse, écho rénale, TDM, IRM…)<\/li><\/ul><div class=\"pgm\">p. 67<\/div><h4>Traitements<\/h4><h4>Si cancer localisé :<\/h4><ul><li>Prostatectomie radicale avec curage ganglionnaire<\/li><li>Radiothérapie<\/li><li>Curiethérapie : implants radioactifs dans la prostate<\/li><li>Ultrasons endorectaux<\/li><\/ul><p>PEC de la dysfonction érectile par injections intracaverneuses si besoin.<\/p><h4>Si cancer avancé :<\/h4><ul><li>Idem<\/li><li>Hormonothérapie (efficace 2 ans) : castration chimique (contre la testostérone) / chirurgicale (pulpectomie : ablation de la pulpe testiculaire)<\/li><li>TT palliatif de confort<\/li><\/ul><h4>Cancer du sein<\/h4><p>Le cancer du sein est le plus fréquent des cancers chez les femmes. On estime qu&#x27;une femme sur 11 sera touchée par ce cancer au cours de sa vie. Très rarement, le cancer du sein peut toucher aussi les hommes (1 % des cas).<\/p><p>On distingue plusieurs types de cancers du sein. Parmi les deux plus fréquents : le cancer non invasif, qui se forme à l&#x27;intérieur des canaux de lactation du sein, et le cancer invasif, qui touche les tissus autour de ces canaux.<\/p><p>Ce dernier a plus de risque de s&#x27;étendre dans le sein et à d&#x27;autres organes s&#x27;il n&#x27;est pas pris en charge rapidement. Dans tous les cas, dépisté tôt, le cancer du sein se soigne très bien et il n&#x27;est pas forcément nécessaire d&#x27;enlever tout le sein atteint.<\/p>","<div class=\"pgm\">p. 67<\/div><h4>Traitements<\/h4><h4>Si cancer localisé :<\/h4><ul><li>Prostatectomie radicale avec curage ganglionnaire<\/li><li>Radiothérapie<\/li><li>Curiethérapie : implants radioactifs dans la prostate<\/li><li>Ultrasons endorectaux<\/li><\/ul><p>PEC de la dysfonction érectile par injections intracaverneuses si besoin.<\/p><h4>Si cancer avancé :<\/h4><ul><li>Idem<\/li><li>Hormonothérapie (efficace 2 ans) : castration chimique (contre la testostérone) / chirurgicale (pulpectomie : ablation de la pulpe testiculaire)<\/li><li>TT palliatif de confort<\/li><\/ul><h4>Cancer du sein<\/h4><p>Le cancer du sein est le plus fréquent des cancers chez les femmes. On estime qu&#x27;une femme sur 11 sera touchée par ce cancer au cours de sa vie. Très rarement, le cancer du sein peut toucher aussi les hommes (1 % des cas).<\/p><p>On distingue plusieurs types de cancers du sein. Parmi les deux plus fréquents : le cancer non invasif, qui se forme à l&#x27;intérieur des canaux de lactation du sein, et le cancer invasif, qui touche les tissus autour de ces canaux.<\/p><p>Ce dernier a plus de risque de s&#x27;étendre dans le sein et à d&#x27;autres organes s&#x27;il n&#x27;est pas pris en charge rapidement. Dans tous les cas, dépisté tôt, le cancer du sein se soigne très bien et il n&#x27;est pas forcément nécessaire d&#x27;enlever tout le sein atteint.<\/p><div class=\"pgm\">p. 68<\/div><h4>Quels sont les symptômes du cancer du sein ?<\/h4><ul><li>Une boule dure dans le sein<\/li><li>Un écoulement du mamelon<\/li><li>Des douleurs au sein<\/li><li>Un mamelon qui se retourne vers l&#x27;intérieur<\/li><li>La peau du sein qui s&#x27;épaissit, durcit ou encore rougit<\/li><\/ul><p>Dernière info : à la suite de plusieurs décès, les autorités sanitaires avaient recommandé d&#x27;éviter le docétaxel. Le médicament utilisé dans le traitement du cancer du sein est de nouveau autorisé.<\/p><h4>Quels examens réaliser pour dépister un cancer du sein ?<\/h4><p>Le dépistage est primordial. Les médecins conseillent aux femmes de réaliser régulièrement une auto-palpation de leurs seins pour repérer une éventuelle masse dure. Si c&#x27;est le cas, une consultation s&#x27;impose.<\/p><p>Les femmes de 50 ans et plus sont invitées tous les deux ans à faire gratuitement une radiographie de leurs seins (mammographie). Pour affiner son interprétation des images, le médecin peut demander en plus une échographie, voire une IRM. Mais même si une anomalie est repérée, en général, elle n&#x27;est pas cancéreuse.<\/p><p>Pour évaluer si la tumeur est cancéreuse ou non, le médecin fait une biopsie.<\/p><p>Si le cancer est confirmé, d&#x27;autres examens comme un scanner ou une scintigraphie permettent de vérifier si d&#x27;autres organes sont atteints.<\/p><h4>Comment prévenir le cancer du sein ?<\/h4><ul><li>Avoir son premier enfant avant 30 ans et l&#x27;allaiter plusieurs mois<\/li><li>Éviter de consommer trop d&#x27;alcool<\/li><li>Perdre du poids si vous êtes en surpoids<\/li><li>Avoir une alimentation équilibrée et privilégier les fruits et légumes<\/li><li>Pratiquer une activité physique régulière<\/li><\/ul><p>À noter : d&#x27;après une étude américaine, la prise d&#x27;un traitement hormonal substitutif (THS) à la ménopause pendant plus de 5 ans augmenterait légèrement le risque de cancer du sein.<\/p><h4>Comment traiter le cancer du sein ?<\/h4><p>La chirurgie reste le premier traitement. Dans plus de 80 % des cas, le cancer est diagnostiqué assez tôt pour que seule la tumeur, encore petite, soit enlevée (tumorectomie) et non le sein<\/p><div class=\"pgm\">p. 69<\/div><p>entier (mastectomie). Si la mastectomie est inévitable, elle peut être suivie d&#x27;une reconstruction mammaire.<\/p><p>Après la chirurgie, le médecin conseille généralement de la radiothérapie pour éliminer les cellules cancéreuses éventuellement restantes. Si le risque de dissémination du cancer est réel, une chimiothérapie est préconisée en plus.<\/p><p>Dans le cas d&#x27;un cancer sensible aux hormones (hormono-dépendant), le médecin peut proposer un médicament hormonal, le tamoxifène, qui diminue le risque de récidive. Des études sont en cours pour évaluer son intérêt en prévention chez les femmes qui ont un risque élevé de développer un cancer du sein.<\/p><h4>Quel est le pronostic vital d&#x27;un cancer du sein ?<\/h4><p>D&#x27;un point de vue statistique, on estime à 4 % le pourcentage de femmes qui décéderont d&#x27;un cancer du sein au cours de leur vie. Le pronostic du cancer du sein est toutefois assez favorable, avec un taux de survie à 5 ans aux alentours de 85 %. Il présente une forte variation selon le stade du cancer (survie supérieure à 90 % pour un cancer du sein au stade local, survie inférieure à 25 % pour un cancer métastatique). Le taux de rémission d&#x27;un cancer du sein est, lui, légèrement supérieur à 70 %.<\/p><p>Dans tous les cas, dépisté tôt, le cancer du sein se soigne très bien et il n&#x27;est pas forcément nécessaire d&#x27;enlever tout le sein atteint.<\/p><h4>Cancer du col de l&#x27;utérus<\/h4>","<div class=\"pgm\">p. 69<\/div><p>entier (mastectomie). Si la mastectomie est inévitable, elle peut être suivie d&#x27;une reconstruction mammaire.<\/p><p>Après la chirurgie, le médecin conseille généralement de la radiothérapie pour éliminer les cellules cancéreuses éventuellement restantes. Si le risque de dissémination du cancer est réel, une chimiothérapie est préconisée en plus.<\/p><p>Dans le cas d&#x27;un cancer sensible aux hormones (hormono-dépendant), le médecin peut proposer un médicament hormonal, le tamoxifène, qui diminue le risque de récidive. Des études sont en cours pour évaluer son intérêt en prévention chez les femmes qui ont un risque élevé de développer un cancer du sein.<\/p><h4>Quel est le pronostic vital d&#x27;un cancer du sein ?<\/h4><p>D&#x27;un point de vue statistique, on estime à 4 % le pourcentage de femmes qui décéderont d&#x27;un cancer du sein au cours de leur vie. Le pronostic du cancer du sein est toutefois assez favorable, avec un taux de survie à 5 ans aux alentours de 85 %. Il présente une forte variation selon le stade du cancer (survie supérieure à 90 % pour un cancer du sein au stade local, survie inférieure à 25 % pour un cancer métastatique). Le taux de rémission d&#x27;un cancer du sein est, lui, légèrement supérieur à 70 %.<\/p><p>Dans tous les cas, dépisté tôt, le cancer du sein se soigne très bien et il n&#x27;est pas forcément nécessaire d&#x27;enlever tout le sein atteint.<\/p><h4>Cancer du col de l&#x27;utérus<\/h4><div class=\"pgm\">p. 70<\/div><p>Le cancer du col de l&#x27;utérus correspond au développement d&#x27;une tumeur maligne de la muqueuse du col utérin. On considère ce cancer comme une affection tumorale d&#x27;origine infectieuse à évolution lente. Dans la majorité des cas, le cancer du col de l&#x27;utérus survient après une exposition prolongée au papillomavirus humain (HPV).<\/p><p>En effet, la présence au long cours du virus dans la muqueuse a un effet délétère sur les cellules saines, qui peuvent se transformer en cellules cancéreuses. C&#x27;est la prolifération de ces cellules cancéreuses, peu nombreuses au départ, qui conduit à l&#x27;apparition d&#x27;une masse plus ou moins organisée qualifiée de tumeur.<\/p><p>Comme les tumeurs apparaissent dans la muqueuse, on les appelle aussi carcinomes épidermoïdes, et ils représentent près de 85 % des cas de cancer du col de l&#x27;utérus.<\/p><h4>Fréquence<\/h4><p>En 2015, près de 2 797 nouvelles femmes ont été touchées par le cancer du col de l&#x27;utérus. Ce faible nombre de nouveaux cas annuels le place au 12e rang des cancers les plus fréquents chez la femme. Ce cancer est, en moyenne, diagnostiqué à 51 ans et il a été responsable de 1 092 décès en 2015, en France. C&#x27;est un cancer qualifié de bon pronostic, car sa survie à 5 ans est de 67 %, c&#x27;est-à-dire que 67 % des patientes atteintes d&#x27;un cancer du col de l&#x27;utérus sont en vie 5 ans après le diagnostic. L&#x27;amélioration du dépistage par la réalisation régulière d&#x27;un frottis cervico-utérin (FCU) a permis de diminuer de près de moitié à la fois le nombre de nouveaux cas et le nombre de décès liés au cancer du col de l&#x27;utérus. On estime qu&#x27;avec un dépistage optimal, on pourrait faire diminuer le nombre de cancers du col de l&#x27;utérus de près de 90 %.<\/p><h4>Facteurs de risque<\/h4><p>Le fait d&#x27;avoir un ou plusieurs facteurs de risque n&#x27;entraîne pas forcément l&#x27;apparition d&#x27;un cancer. Ils augmentent la probabilité de développer ce cancer par rapport à une personne non exposée. Cependant, un cancer peut se développer sans qu&#x27;aucun facteur de risque ne soit présent.<\/p><p>À savoir ! Un facteur de risque désigne un élément qui peut favoriser le développement d&#x27;un cancer.<\/p><h4>Le papillomavirus humain (HPV)<\/h4><div class=\"pgm\">p. 71<\/div><p>C&#x27;est le principal agent inducteur de cancer du col de l&#x27;utérus. En effet, une infection prolongée d&#x27;une durée de 10 à 15 ans par le papillomavirus humain serait responsable de près de 70 % des tumeurs du col de l&#x27;utérus.<\/p><p>L&#x27;HPV se transmet par contact de la peau et des muqueuses, le plus souvent lors de rapports sexuels. L&#x27;infection par ce virus est très courante et guérit majoritairement de façon spontanée. Cependant, dans 10 % des cas, on voit une persistance du virus dans la muqueuse du col de l&#x27;utérus qui peut aboutir à des lésions précancéreuses susceptibles d&#x27;évoluer en cancer.<\/p><p>À savoir ! Il existe plus de 80 souches de papillomavirus et il n&#x27;en existe qu&#x27;un faible nombre qui provoquent un cancer du col de l&#x27;utérus.<\/p><p>Depuis 2007, il existe deux vaccins contre les papillomavirus de type 16 et 18. C&#x27;est un très bon moyen de prévention pour ce type de cancer, mais il ne se substitue pas au suivi gynécologique.<\/p><h4>Les autres facteurs de risque<\/h4><p>Un lien scientifique a été établi entre d&#x27;autres facteurs que le HPV et l&#x27;apparition du cancer du col de l&#x27;utérus :<\/p><ul><li>La précocité des rapports sexuels ;<\/li><li>La multiplicité des partenaires sexuels : plus le nombre de partenaires différents est important, plus la chance d&#x27;être exposé au papillomavirus augmente et donc plus on a de risque de développer un cancer ;<\/li><li>Le tabac ;<\/li><li>L&#x27;infection par le VIH (SIDA) ou la prise d&#x27;un traitement immunosuppresseur : car dans les deux cas, notre système immunitaire est moins performant, ce qui entraîne une perte d&#x27;efficacité dans la lutte contre les virus HPV ;<\/li><li>Le fait d&#x27;avoir plusieurs enfants ;<\/li><li>La prise de la pilule contraceptive ;<\/li><li>Des maladies sexuellement transmissibles : comme l&#x27;herpès génital et la chlamydiose.<\/li><\/ul><div class=\"pgm\">p. 72<\/div><h4>Les lésions précancéreuses du col de l&#x27;utérus<\/h4><p>Les lésions précancéreuses correspondent à des modifications des cellules de l&#x27;épithélium de la muqueuse du col de l&#x27;utérus (cellules recouvrant la muqueuse) qui ne sont pas encore des cancers, c&#x27;est-à-dire que le tissu est anormal mais pas encore cancéreux. En effet, la lésion précancéreuse n&#x27;est pas désignée comme un cancer, car elle ne possède pas tous les critères de malignité d&#x27;un cancer. Ces troubles sont causés le plus souvent par la présence durable du papillomavirus humain (HPV) dans le col de l&#x27;utérus.<\/p><p>L&#x27;infection virale entraîne une souffrance cellulaire rendant compte de l&#x27;évolution du tissu vers un cancer du col de l&#x27;utérus. Les lésions précancéreuses peuvent régresser spontanément ou progresser vers un cancer.<\/p><p>Les lésions précancéreuses sont aussi appelées néoplasies cervicales intraépithéliales ou CIN. Elles existent sous forme plus ou moins grave. Une classification permet de distinguer trois grands types de lésions en fonction de leurs gravités :<\/p><ul><li>CIN 1 : les cellules anormales touchent 1/3 de l&#x27;épaisseur de l&#x27;épithélium ;<\/li><li>CIN 2 : les cellules anormales touchent 2/3 de l&#x27;épaisseur de l&#x27;épithélium ;<\/li><li>CIN 3 : les cellules anormales touchent l&#x27;ensemble de l&#x27;épithélium.<\/li><\/ul><p>En fonction du grade de lésion précancéreuse, il a été établi une probabilité d&#x27;évolution vers une CIN de grade supérieur, un cancer du col de l&#x27;utérus ou vers une régression spontanée.<\/p><p>Probabilités de régression, de persistance et d&#x27;évolution des CIN (Ostor, 1993) :<\/p><ul><li>CIN 1 : régression 57 % ; persistance 32 % ; progression vers une CIN supérieure 11 % ; progression vers un cancer invasif 1 %<\/li><li>CIN 2 : régression 43 % ; persistance 35 % ; progression vers une CIN supérieure 22 % ; progression vers un cancer invasif 5 %<\/li><li>CIN 3 : régression 32 % ; persistance 56 % ; progression vers un cancer invasif &gt; 12 %<\/li><\/ul><p>Les lésions précancéreuses de bas grade (CIN 1) ont plus de chance de régresser que d&#x27;évoluer vers un grade supérieur. Plus la CIN est haute, plus le risque d&#x27;évolution vers un cancer est important et plus la probabilité de régression spontanée est limitée.<\/p><p>L&#x27;évolution de ces lésions précancéreuses vers un cancer est un phénomène évolutif, lent et pouvant être mis en évidence par un frottis cervico-utérin (FCU). Il est donc possible de les identifier et de les traiter avant qu&#x27;elles ne deviennent des cancers du col de l&#x27;utérus.<\/p><div class=\"pgm\">p. 73<\/div><h4>Le dépistage<\/h4><p>Du fait de son évolution lente et de la présence de lésions précancéreuses curables, le cancer du col de l&#x27;utérus peut être dépisté à un stade précoce, et même être totalement prévenu par la détection des lésions précancéreuses.<\/p><p>Le dépistage repose principalement sur un frottis cervico-utérin, qui est un prélèvement de cellules à la surface du col de l&#x27;utérus, ensuite analysées à l&#x27;aide d&#x27;un microscope. L&#x27;aspect des cellules ainsi que l&#x27;organisation du tissu permettent aux biologistes d&#x27;observer d&#x27;éventuelles lésions précancéreuses ou la présence d&#x27;un cancer du col de l&#x27;utérus.<\/p><p>À savoir ! Il est recommandé tous les trois ans, après 2 frottis normaux espacés d&#x27;un an, pour toutes les femmes âgées de 25 à 65 ans.<\/p><h4>Symptômes<\/h4><p>Le cancer du col de l&#x27;utérus se développe souvent sans provoquer de symptômes particuliers, notamment à un stade précoce. C&#x27;est pour cette raison qu&#x27;il est indispensable d&#x27;avoir un suivi gynécologique avec réalisation de frottis cervico-utérin afin de le détecter le plus précocement possible.<\/p><p>Il existe également un ensemble de symptômes qui ne sont pas spécifiques du cancer du col de l&#x27;utérus, mais dont la persistance ou l&#x27;intensité peuvent évoquer une tumeur :<\/p><ul><li>Des métrorragies provoquées : qui correspondent à un saignement par voie basse provoqué par un rapport sexuel<\/li><li>Des métrorragies spontanées : qui sont des saignements apparaissant sans causes apparentes ;<\/li><li>Des douleurs pendant les rapports sexuels ;<\/li><li>Des pertes vaginales blanches ;<\/li><li>Des douleurs dans le bas-ventre avec des difficultés pour uriner, une envie pressante et continuelle d&#x27;aller à la selle<\/li><li>Des douleurs lombaires.<\/li><\/ul><div class=\"pgm\">p. 74<\/div><p>(Schéma : évolution du cancer du col de l&#x27;utérus — sain, stade précoce, stade avancé, stade très avancé.)<\/p><p>Ces symptômes peuvent être retrouvés dans une autre maladie que le cancer du col de l&#x27;utérus, mais il est important de les signaler à votre médecin afin qu&#x27;il en détermine l&#x27;origine.<\/p><h4>Le diagnostic<\/h4><p>Le bilan diagnostique du cancer du col de l&#x27;utérus se met en place après un examen de dépistage anormal ou l&#x27;apparition de symptômes évocateurs. Des examens complémentaires sont alors mis en place, ayant pour objectifs de :<\/p><ul><li>Confirmer le diagnostic de cancer et définir le type de cellule impliquée<\/li><li>Déterminer le stade de la maladie afin de proposer un traitement adapté<\/li><li>Identifier d&#x27;éventuelles contre-indications à certains traitements<\/li><\/ul><p>La confirmation définitive du diagnostic de cancer du col de l&#x27;utérus n&#x27;est possible qu&#x27;après l&#x27;analyse d&#x27;une biopsie (prélèvement d&#x27;un fragment de tissu).<\/p><h4>La colposcopie<\/h4><p>Ce bilan se déroule en cabinet de gynécologie. Le médecin examine la surface du col de l&#x27;utérus et du vagin à l&#x27;aide d&#x27;un colposcope, qui est une loupe puissante dotée d&#x27;une lumière à son extrémité. Cet examen permet d&#x27;examiner les zones anormales, de déposer des liquides révélateurs de lésions précancéreuses et de réaliser des biopsies (prélèvements d&#x27;un fragment mince du col). La colposcopie n&#x27;est pas douloureuse mais peut causer de l&#x27;inconfort durant sa réalisation.<\/p><h4>La biopsie conique ou conisation<\/h4><p>Cet examen correspond au prélèvement d&#x27;un fragment de forme conique des lésions difficilement accessibles du col de l&#x27;utérus. La conisation est réalisée sous anesthésie locale ou générale. L&#x27;objectif est essentiellement diagnostique, mais dans certains cas la biopsie<\/p><div class=\"pgm\">p. 75<\/div><p>conique permet de retirer toutes les cellules présumées cancéreuses et, dans ce cadre, aucun autre traitement ne sera nécessaire.<\/p><h4>Examen anatomo-pathologique<\/h4><p>C&#x27;est l&#x27;examen au microscope des fragments de tissus obtenus par biopsie ou conisation. C&#x27;est l&#x27;examen de référence pour confirmer le diagnostic de cancer du col de l&#x27;utérus.<\/p><p>Les analyses pratiquées sur les cellules permettent de définir la cellule d&#x27;origine du cancer et ses caractéristiques.<\/p><h4>La prise en charge thérapeutique du col de l&#x27;utérus<\/h4><p>Le choix du traitement dans le cancer du col de l&#x27;utérus dépend de 2 critères :<\/p><ul><li>Des caractéristiques de la tumeur : notamment sa taille, sa localisation, du stade tumoral et du grade tumoral ;<\/li><li>De l&#x27;état général de la patiente.<\/li><\/ul><p>Grâce à ces critères, les professionnels de santé élaborent un protocole de soin en réunion de concertation pluridisciplinaire (RCP). L&#x27;avis de la RCP est ensuite soumis au patient par son médecin référent. C&#x27;est donc une concertation entre patient et médecin qui donne le « feu vert » à la prise en charge thérapeutique. Le patient valide l&#x27;avis de la RCP par son consentement éclairé, c&#x27;est-à-dire en ayant compris les enjeux et les risques liés aux traitements proposés.<\/p><p>Le traitement du cancer du col de l&#x27;utérus est organisé autour de 3 axes, qui sont : la chirurgie, la radiothérapie et la chimiothérapie. Les protocoles peuvent être utilisés seuls ou en associations et ont pour objectif, selon les cas, de : détruire la/les tumeurs, réduire le risque de rechute, ralentir le développement de la tumeur et traiter les symptômes liés à la maladie.<\/p><h4>La chirurgie<\/h4><p>Cet axe thérapeutique est principalement employé pour traiter les tumeurs locales et peu étendues du col de l&#x27;utérus. L&#x27;acte chirurgical permet de retirer l&#x27;ensemble de la tumeur et<\/p><div class=\"pgm\">p. 76<\/div><p>ainsi guérir la maladie. Plusieurs interventions existent. Le choix se fait en fonction de l&#x27;étendue du cancer mais aussi de l&#x27;âge et du désir éventuel de grossesse de la patiente.<\/p><h4>La colpo-hystérectomie élargie<\/h4><p>C&#x27;est l&#x27;acte chirurgical le plus réalisé pour le traitement du cancer du col de l&#x27;utérus. Au cours de cette opération, le chirurgien retire l&#x27;ensemble de l&#x27;utérus et la partie supérieure du vagin. De plus, les ovaires sont eux aussi fréquemment retirés. Ce traitement n&#x27;est possible que pour les patientes qui souffrent d&#x27;une tumeur limitée du col de l&#x27;utérus d&#x27;une taille inférieure à 4 cm.<\/p><h4>L&#x27;ablation des réseaux ganglionnaires<\/h4><p>Les cancers peuvent se disséminer à l&#x27;ensemble du corps par les ganglions lymphatiques. L&#x27;ablation des réseaux ganglionnaires proches de l&#x27;utérus permet de limiter le risque de propagation de la maladie ainsi que celui de rechute.<\/p><h4>L&#x27;hystérectomie<\/h4><p>Au cours de cette opération, le chirurgien ne retire que l&#x27;utérus en laissant intacte la partie haute du vagin. L&#x27;hystérectomie est un traitement indiqué dans les tumeurs de petites tailles et très limitées au col de l&#x27;utérus.<\/p><h4>La trachélectomie<\/h4><p>La trachélectomie consiste à ne retirer que le col de l&#x27;utérus. Une fois l&#x27;ablation réalisée, le chirurgien procède à des sutures particulières appelées « cerclage » qui permettent de fermer partiellement l&#x27;utérus à l&#x27;endroit où se trouvait le col. Ce nouvel orifice permet l&#x27;évacuation du sang au moment des règles.<\/p><p>Cette opération n&#x27;est possible que dans des tumeurs limitées au col de l&#x27;utérus et dont la taille n&#x27;excède pas 2 centimètres. Cette chirurgie est dite conservatrice car elle préserve l&#x27;utérus et donc la fertilité des jeunes femmes désirant une grossesse future.<\/p><h4>La radiothérapie<\/h4><p>La radiothérapie est un traitement local utilisant des rayonnements ionisants de hautes énergies pour détruire des cellules cancéreuses. Cette méthode thérapeutique permet de cibler très précisément une zone à traiter pour irradier la tumeur tout en préservant au maximum les tissus sains avoisinants. On peut employer deux modalités de radiothérapie dans le cancer du col de l&#x27;utérus.<\/p><div class=\"pgm\">p. 77<\/div><ul><li>La radiothérapie externe : est une technique où la source des rayons est à l&#x27;extérieur de la patiente. Le faisceau de rayonnement est dirigé contre la tumeur de la patiente en étant guidé par des points de repères. Plusieurs séances par semaine sont nécessaires, étalées sur quelques mois.<\/li><li>La radiothérapie interne ou curiethérapie : consiste à placer un applicateur contenant la source de rayons dans le vagin et au contact de la tumeur. L&#x27;irradiation du cancer se fait donc de manière continue. Cette thérapeutique peut être utilisée dans le cancer du col de l&#x27;utérus notamment avant une chirurgie afin de réduire la taille de la tumeur. Au cours de la curiethérapie, la patiente est considérée comme « radioactive », car la source émettrice de rayons est dans son organisme.<\/li><\/ul><h4>La chimiothérapie<\/h4><p>La chimiothérapie comprend l&#x27;ensemble des thérapeutiques médicamenteuses agissant sur les cellules cancéreuses et ayant pour but soit de les détruire, soit de limiter leurs multiplications. C&#x27;est le seul axe thérapeutique qui agit sur l&#x27;ensemble de l&#x27;organisme. Les traitements de chimiothérapie peuvent être utilisés par voie veineuse ou par voie orale en fonction des molécules employées.<\/p><p>Dans le cancer du col de l&#x27;utérus, la chimiothérapie est indiquée soit pour réduire la taille d&#x27;une tumeur pour augmenter la réussite d&#x27;une intervention chirurgicale, soit dans le traitement des cancers à fort risque de propagation ou métastatiques. Les molécules les plus couramment utilisées sont :<\/p><ul><li>Le 5-fluorouracile (5-FU) : qui est un anticancéreux bloquant la synthèse d&#x27;ADN de la tumeur, l&#x27;empêchant de se multiplier.<\/li><li>Les sels de platine : qui sont des anticancéreux capables de se fixer à l&#x27;ADN et qui stoppent la prolifération des cellules cancéreuses.<\/li><\/ul><h4>Cancer de la vessie<\/h4><h4>Introduction<\/h4><p>= Masse tissulaire anormale liée à une prolifération anarchique des cellules.<\/p><ul><li>Deuxième cancer uro-génital après celui de la prostate<\/li><li>Plus fréquent chez l&#x27;homme (3 pour 1)<\/li><li>Âge moyen 65 ans<\/li><\/ul><h4>Formes cliniques<\/h4>","<div class=\"pgm\">p. 77<\/div><ul><li>La radiothérapie externe : est une technique où la source des rayons est à l&#x27;extérieur de la patiente. Le faisceau de rayonnement est dirigé contre la tumeur de la patiente en étant guidé par des points de repères. Plusieurs séances par semaine sont nécessaires, étalées sur quelques mois.<\/li><li>La radiothérapie interne ou curiethérapie : consiste à placer un applicateur contenant la source de rayons dans le vagin et au contact de la tumeur. L&#x27;irradiation du cancer se fait donc de manière continue. Cette thérapeutique peut être utilisée dans le cancer du col de l&#x27;utérus notamment avant une chirurgie afin de réduire la taille de la tumeur. Au cours de la curiethérapie, la patiente est considérée comme « radioactive », car la source émettrice de rayons est dans son organisme.<\/li><\/ul><h4>La chimiothérapie<\/h4><p>La chimiothérapie comprend l&#x27;ensemble des thérapeutiques médicamenteuses agissant sur les cellules cancéreuses et ayant pour but soit de les détruire, soit de limiter leurs multiplications. C&#x27;est le seul axe thérapeutique qui agit sur l&#x27;ensemble de l&#x27;organisme. Les traitements de chimiothérapie peuvent être utilisés par voie veineuse ou par voie orale en fonction des molécules employées.<\/p><p>Dans le cancer du col de l&#x27;utérus, la chimiothérapie est indiquée soit pour réduire la taille d&#x27;une tumeur pour augmenter la réussite d&#x27;une intervention chirurgicale, soit dans le traitement des cancers à fort risque de propagation ou métastatiques. Les molécules les plus couramment utilisées sont :<\/p><ul><li>Le 5-fluorouracile (5-FU) : qui est un anticancéreux bloquant la synthèse d&#x27;ADN de la tumeur, l&#x27;empêchant de se multiplier.<\/li><li>Les sels de platine : qui sont des anticancéreux capables de se fixer à l&#x27;ADN et qui stoppent la prolifération des cellules cancéreuses.<\/li><\/ul><h4>Cancer de la vessie<\/h4><h4>Introduction<\/h4><p>= Masse tissulaire anormale liée à une prolifération anarchique des cellules.<\/p><ul><li>Deuxième cancer uro-génital après celui de la prostate<\/li><li>Plus fréquent chez l&#x27;homme (3 pour 1)<\/li><li>Âge moyen 65 ans<\/li><\/ul><h4>Formes cliniques<\/h4><div class=\"pgm\">p. 78<\/div><p>2 formes :<\/p><ul><li>superficielle = 80 % des cancers vésicaux<\/li><li>cancer infiltrant = 20 %<\/li><\/ul><p>NB : les polypes = tumeurs bénignes.<\/p><h4>Facteurs favorisants<\/h4><ul><li>Tabac +++ (50 % des cancers)<\/li><li>Expositions professionnelles aux teintures, caoutchouc, peintures…<\/li><li>Antalgiques avec phénacétine (exemple : Viscéralgine)<\/li><li>Infections chroniques type bilharziose<\/li><\/ul><h4>Sémiologie<\/h4><ul><li>Hématurie = 1er signe !<\/li><li>Troubles mictionnels : pollakiurie, dysurie…<\/li><li>Syndrome de cystite avec ECBU stérile<\/li><li>Extension loco-régionale<\/li><\/ul><h4>Examens<\/h4><ul><li>ECBU (étude cytologique)<\/li><li>Cystoscopie<\/li><li>Urographie intraveineuse<\/li><li>Échographie vésicale (visualisation d&#x27;une masse intravésicale)<\/li><li>Scanner<\/li><\/ul><h4>Traitements<\/h4><p>1. Arrêt du tabac !<\/p><h4>Pour les tumeurs superficielles<\/h4><ul><li>Résections endoscopiques de la tumeur (puis irrigation vésicale continue)<\/li><li>Traitement local<\/li><\/ul><h4>Pour les tumeurs invasives<\/h4><p>Cystectomie partielle ou totale avec curage ganglionnaire puis dérivation des urines ; si métastases, alors radiothérapie et chimiothérapie.<\/p>"]});
